// Content for Equal Parents (node g62, Parenthood, Chapter 8) — NEW v2 build to GDD 62 (mechanic-embodying),
// taking the equal-home work of Equal Partners (g55) into RAISING CHILDREN — the stage where gendered defaults
// snap back hardest. Parenting isn't mum's job with dad "helping". 84 researched, India-grounded scenarios across
// share-the-care → parental-mental-load → involved-dads → kids-are-watching → everyone-gains → tools-and-help,
// each encoded as one of the shared v2 play actions (strike-rewrite / branch / sort / reflect / match / role-play
// / spot) — no binary "tap the right card". Lead: strike-rewrite (bust the myth), branch (your move), sort. Six
// modes: share the care (split feeds, nights, appointments & school-runs through OWNED shares; both parents
// competent; only breastfeeding is mother-specific), the parental mental load (surface & share the invisible
// tracking/planning/worrying — sharing means owning the noticing, not doing tasks on request), involved dads
// (busts "fathers help / providing is enough / nurturing isn't a man's role"; hands-on, emotionally present
// fatherhood is good fathering AND a fuller manhood; addresses maternal gatekeeping), kids are watching (children
// learn gender roles by watching their parents — modelling shared care breaks the intergenerational divide;
// chores have no gender), everyone gains (shared parenting is better for children, mothers AND fathers — not a
// sacrifice or a trade; equality matters most exactly when kids arrive), tools & help (a fair-parenting &
// mental-load map, a shared calendar & weekly check-in, rebalanced over time; parental burnout routes to Looking
// After You g63). Even-handed and warm: engages fathers as equal OWNERS, never anti-men, frames involved
// fatherhood as PRO-men, and never shames any current arrangement. Builds on Equal Partners (g55) and Equalize
// (g26); beside Us, After Kids (g61). India: childcare defaults heavily to mothers & grandmothers, fathers cast as
// providers (reinforced by joint families & minimal paternity leave); greater paternal involvement lifts child
// development, marital satisfaction and fathers' own wellbeing. gameId "equal-parents".
import type { V2GameConfig, Scenario } from "./v2-schema";

const SCENARIOS: Scenario[] = [
  {"id":"ep2-001","cat":"share-the-care","type":"strike-rewrite","hook":"\"Hands-on childcare is naturally the mother's job.\"","myth":{"un":"Hands-on childcare is naturally the mother's job.","re":"Both parents can do feeds, nappies, nights and appointments; there's nothing about care that only a mother can do.","why":"Caregiving is learned by doing, not assigned by gender."},"relearn":"Hands-on care isn't naturally the mother's job; both parents can and should do it.","persona":"Vikram","source":"care isn't gendered"},
  {"id":"ep2-002","cat":"share-the-care","type":"sort","hook":"Sort: a task only the breastfeeding mother can do, or one either parent can own?","items":[{"id":"a","text":"Changing nappies"},{"id":"b","text":"Breastfeeding specifically"},{"id":"c","text":"Night soothing and rocking"},{"id":"d","text":"Booking and attending check-ups"},{"id":"e","text":"Giving a bottle feed"},{"id":"f","text":"Doing the school-run"}],"bins":[{"id":"either","label":"Either parent","valence":"pos"},{"id":"mum","label":"Mother-specific","valence":"neutral"}],"key":{"a":"either","b":"mum","c":"either","d":"either","e":"either","f":"either"},"relearn":"Only breastfeeding is mother-specific; nappies, soothing, appointments, bottle feeds and the school-run are jobs either parent can own.","persona":"any","source":"either or mum"},
  {"id":"ep2-003","cat":"share-the-care","type":"branch","hook":"The night feeds, school-runs and appointments have all quietly defaulted to one parent.","options":[{"text":"Map every recurring task and split it into fair, owned shares","consequence":"The load becomes visibly, genuinely shared.","outcome":"split","best":true},{"text":"Let the default stand because 'it's just easier'","consequence":"'It's just easier' quietly loads it all onto one parent."}],"debrief":"Map the recurring care and split it into fair, owned shares, not a one-parent default.","relearn":"Map and split the care fairly; 'it's easier' entrenches the default.","persona":"Divya","source":"split the tasks"},
  {"id":"ep2-004","cat":"share-the-care","type":"sort","hook":"Sort: a fairly shared care arrangement, or a lopsided one dressed up as sharing?","items":[{"id":"a","text":"Each parent owns whole tasks"},{"id":"b","text":"One does it all, one 'helps' sometimes"},{"id":"c","text":"Nights and mornings alternated"},{"id":"d","text":"One parent is always the backup"},{"id":"e","text":"Both can run a day solo"},{"id":"f","text":"She must remind him of each task"}],"bins":[{"id":"fair","label":"Fairly shared","valence":"pos"},{"id":"lopsided","label":"Lopsided","valence":"neg"}],"key":{"a":"fair","b":"lopsided","c":"fair","d":"lopsided","e":"fair","f":"lopsided"},"relearn":"Owning whole tasks, alternating nights and both running solo is fair; one doing it all while the other 'helps' or gets reminded is lopsided.","persona":"Vikram","source":"fair vs lopsided"},
  {"id":"ep2-005","cat":"share-the-care","type":"match","hook":"Match each shared-care move to what it achieves.","pairs":[{"left":"Each owns specific tasks","right":"No constant negotiating"},{"left":"Alternating nights","right":"Both rest and both bond"},{"left":"Both know the routines","right":"Either can step in fully"},{"left":"Both on the school forms","right":"Either parent gets the call"},{"left":"Dad does solo days","right":"Real skill, not supervised"}],"relearn":"Owning tasks, alternating nights, shared routines and contacts, and solo days all make care genuinely shareable.","persona":"any","source":"shared-care moves"},
  {"id":"ep2-006","cat":"share-the-care","type":"branch","hook":"You're the parent who's drifted into doing almost none of the hands-on care.","options":[{"text":"Step up and own real, regular care tasks, not occasional help","consequence":"You become a true co-parent.","outcome":"co-parent","best":true},{"text":"Keep offering only to 'help when needed'","consequence":"Owning regular care makes you a co-parent; 'helping when needed' keeps the load on the other parent."}],"debrief":"Own regular hands-on care to be a true co-parent, rather than offering occasional help.","relearn":"Step up to own regular care; occasional 'helping when needed' isn't co-parenting.","persona":"Vikram","source":"step up"},
  {"id":"ep2-007","cat":"share-the-care","type":"strike-rewrite","hook":"\"As long as I provide financially, I've done my part as a parent.\"","myth":{"un":"As long as I provide financially, I've done my part as a parent.","re":"Providing matters, but children need hands-on care and presence too; caregiving is a parent's responsibility, not an extra.","why":"Presence is part of the job, not a bonus."},"relearn":"Providing isn't the whole of parenting; hands-on care and presence are a parent's responsibility too.","persona":"Vikram","source":"more than providing"},
  {"id":"ep2-008","cat":"share-the-care","type":"role-play","hook":"Your partner assumes you can't handle the baby alone for a day. You want to claim your competence.","setup":"Claim it warmly:","yourLine":[{"text":"\"I've got this, go enjoy your day, I know our routines and I'll be fine on my own.\"","best":true},{"text":"\"Yeah, maybe leave a long list, I'll probably mess it up.\""}],"relearn":"Confidently owning solo care builds your competence and frees your partner from being the only capable one.","persona":"Vikram","source":"claim competence"},
  {"id":"ep2-009","cat":"share-the-care","type":"sort","hook":"Sort: builds both parents' competence, or keeps care one-sided?","items":[{"id":"a","text":"Both doing solo stretches with the child"},{"id":"b","text":"One always supervising the other"},{"id":"c","text":"Both learning the routines fully"},{"id":"d","text":"Treating one parent as the only 'expert'"},{"id":"e","text":"Swapping who does the early start"},{"id":"f","text":"Redoing his work 'properly' after"}],"bins":[{"id":"both","label":"Builds both","valence":"pos"},{"id":"oneside","label":"Keeps it one-sided","valence":"neg"}],"key":{"a":"both","b":"oneside","c":"both","d":"oneside","e":"both","f":"oneside"},"relearn":"Solo time, shared routines and swapping starts build both; constant supervision, a single 'expert' and redoing his work keep care one-sided.","persona":"any","source":"both vs one-sided"},
  {"id":"ep2-010","cat":"share-the-care","type":"spot","hook":"Spot the two things that aren't genuine shared care.","scene":[{"id":"a","text":"Both handle nights and appointments","trick":false},{"id":"b","text":"One parent named the 'main' one by default","trick":true},{"id":"c","text":"Either can run the day solo","trick":false},{"id":"d","text":"He only 'helps' when she asks","trick":true},{"id":"e","text":"Both know the full daily routine","trick":false}],"why":"A default 'main parent' and a dad who only 'helps when asked' aren't shared care; both should own real tasks and run solo.","relearn":"Shared care means both own the real tasks and either can run solo, with no default 'main parent' and no waiting to be asked.","persona":"any","source":"genuine shared care"},
  {"id":"ep2-011","cat":"share-the-care","type":"reflect","hook":"Lensy: shared care isn't a favour one parent does the other; it's just both doing their job. Sit right?","prompt":"What do you think?","options":["Sits right","Both our job","Not a favour"],"affirm":"Shared care is simply both parents doing their own job, not one doing the other a favour.","relearn":"Shared care isn't a favour; it's both parents doing their own job.","persona":"any","source":"not a favour"},
  {"id":"ep2-012","cat":"share-the-care","type":"branch","hook":"Grandparents step in to help, and the load quietly shifts to them and the mother, not you.","options":[{"text":"Stay a hands-on parent alongside any family help","consequence":"Your child gets you, not just a stand-in.","outcome":"hands-on","best":true},{"text":"Let grandparents and mum cover your share","consequence":"Letting others cover your share sidelines you from your own kid."}],"debrief":"Stay a hands-on parent even with grandparents helping; don't let your share shift to others.","relearn":"Welcome family help but stay hands-on; don't let your share pass to others.","persona":"Vikram","source":"stay hands-on"},
  {"id":"ep2-013","cat":"share-the-care","type":"strike-rewrite","hook":"\"Splitting care 'fairly' means keeping a strict scorecard.\"","myth":{"un":"Splitting care fairly means keeping a strict scorecard.","re":"Fair sharing is about both owning real responsibility and flexing for each other, not tallying every nappy.","why":"Ownership and flexibility beat score-keeping."},"relearn":"Fair care is shared ownership and flexing for each other, not a strict nappy-by-nappy scorecard.","persona":"any","source":"ownership not score"},
  {"id":"ep2-014","cat":"share-the-care","type":"match","hook":"Match each recurring duty to a fair way to share it.","pairs":[{"left":"Night wake-ups","right":"Take turns or split the week"},{"left":"Doctor and school runs","right":"Each owns some, not all on one"},{"left":"Daily feeding and bathing","right":"Whoever's free, both capable"},{"left":"Sick days off work","right":"Alternate who stays home"},{"left":"Bedtime routine","right":"Own set nights each"}],"relearn":"Night wake-ups, appointments, daily care, sick days and bedtime each have a fair split when both parents are capable and willing.","persona":"any","source":"fair splits"},
  {"id":"ep2-015","cat":"parental-mental-load","type":"strike-rewrite","hook":"\"Remembering jabs, sizes, supplies and appointments isn't real work.\"","myth":{"un":"Remembering jabs, sizes, supplies and appointments isn't real work.","re":"The parental mental load, the constant tracking, planning and worrying, is real, tiring cognitive work that must be shared.","why":"Invisible work still wears you out."},"relearn":"The parental mental load, tracking, planning and worrying, is real, tiring work that has to be shared.","persona":"Divya","source":"load is real work"},
  {"id":"ep2-016","cat":"parental-mental-load","type":"sort","hook":"Sort: visible care task, or invisible parental mental load?","items":[{"id":"a","text":"Feeding the baby"},{"id":"b","text":"Remembering the vaccine schedule"},{"id":"c","text":"Bathing the child"},{"id":"d","text":"Noticing the nappies are running out"},{"id":"e","text":"Packing the school bag"},{"id":"f","text":"Tracking when the uniform stops fitting"}],"bins":[{"id":"visible","label":"Visible task","valence":"neutral"},{"id":"mental","label":"Mental load","valence":"tell"}],"key":{"a":"visible","b":"mental","c":"visible","d":"mental","e":"visible","f":"mental"},"relearn":"Feeding, bathing and packing are visible; remembering jabs, noticing supplies and tracking sizes is the mental load.","persona":"any","source":"visible vs mental"},
  {"id":"ep2-017","cat":"parental-mental-load","type":"strike-rewrite","hook":"\"If I do tasks when asked, I'm sharing the parenting equally.\"","myth":{"un":"If I do tasks when asked, I'm sharing the parenting equally.","re":"Being asked still leaves one parent as the manager who notices and remembers; sharing means owning the noticing too.","why":"Sharing the load means sharing the thinking."},"relearn":"Doing tasks when asked isn't equal; true sharing means owning the noticing and planning, not just the doing.","persona":"Vikram","source":"share the thinking"},
  {"id":"ep2-018","cat":"parental-mental-load","type":"sort","hook":"Sort: carrying the mental load, or genuinely sharing it?","items":[{"id":"a","text":"One parent plans every meal and appointment"},{"id":"b","text":"Both track what the child needs"},{"id":"c","text":"One remembers all the dates"},{"id":"d","text":"Both own whole domains end-to-end"},{"id":"e","text":"One waits to be told what to do"},{"id":"f","text":"Both notice problems without a reminder"}],"bins":[{"id":"carry","label":"One carries it","valence":"uhoh"},{"id":"share","label":"Genuinely shared","valence":"pos"}],"key":{"a":"carry","b":"share","c":"carry","d":"share","e":"carry","f":"share"},"relearn":"One planning, remembering and waiting is carrying it; both tracking, owning domains and noticing is sharing it.","persona":"Divya","source":"carry or share"},
  {"id":"ep2-019","cat":"parental-mental-load","type":"branch","hook":"One of you remembers everything for the child while the other waits to be told.","options":[{"text":"Hand whole domains like health or school to each parent to own","consequence":"The remembering is shared, not delegated.","outcome":"owned","best":true},{"text":"Keep one parent as the family's memory and manager","consequence":"Keeping one parent as manager just adds delegating to their load."}],"debrief":"Share the mental load by each parent owning whole domains, not one staying the manager.","relearn":"Split the load by each owning whole domains; don't leave one as the family's memory.","persona":"Divya","source":"own domains"},
  {"id":"ep2-020","cat":"parental-mental-load","type":"match","hook":"Match each invisible duty to the parent-load it really is.","pairs":[{"left":"Tracking growth, jabs, milestones","right":"Health mental load"},{"left":"Planning meals, supplies, sizes","right":"Logistics mental load"},{"left":"Sensing moods and needs","right":"Emotional mental load"},{"left":"Knowing fees, forms and term dates","right":"School mental load"},{"left":"Remembering who to call when","right":"Social mental load"}],"relearn":"Health, logistics, emotional, school and social tracking are all real parts of the parental mental load to share.","persona":"any","source":"kinds of load"},
  {"id":"ep2-021","cat":"parental-mental-load","type":"strike-rewrite","hook":"\"Mothers are just naturally better at remembering all the kid stuff.\"","myth":{"un":"Mothers are just naturally better at remembering all the kid stuff.","re":"It's not nature; whoever does the tracking gets practised at it, and either parent can carry their share of the planning.","why":"Practice, not biology, builds the skill."},"relearn":"Mothers aren't naturally better at the mental load; whoever practises it gets good at it, and both can share it.","persona":"any","source":"not natural"},
  {"id":"ep2-022","cat":"parental-mental-load","type":"reflect","hook":"Lensy: you can't share what you can't see; naming the mental load is the first step to splitting it. Make sense?","prompt":"What do you think?","options":["Makes sense","Name it first","I see it now"],"affirm":"You can't split a load you can't see; naming the parental mental load is the first step to sharing it.","relearn":"Naming the invisible parental mental load is the first step to sharing it fairly.","persona":"any","source":"name to share"},
  {"id":"ep2-023","cat":"parental-mental-load","type":"spot","hook":"Spot the two lines that leave one parent as the only manager.","scene":[{"id":"a","text":"\"Just tell me what needs doing and I'll do it.\"","trick":true},{"id":"b","text":"\"I'll fully run all the health stuff from now.\"","trick":false},{"id":"c","text":"\"You always remember the dates, so you keep that.\"","trick":true},{"id":"d","text":"\"Let's split the calendar and both check it.\"","trick":false},{"id":"e","text":"\"I'll notice when supplies run low, not wait.\"","trick":false}],"why":"Waiting to be told and leaving the remembering to one parent keep that parent the manager.","relearn":"Lines that wait for instructions or hand all remembering to one parent keep the load lopsided.","persona":"Vikram","source":"who manages"},
  {"id":"ep2-024","cat":"parental-mental-load","type":"branch","hook":"You realise your partner's brain is full of invisible child-admin and yours isn't.","options":[{"text":"Ask them to hand you whole areas to carry, planning included","consequence":"You lift real weight, not just tasks.","outcome":"lift","best":true},{"text":"Offer to 'help more' with the doing only","consequence":"Helping with the doing only leaves the thinking on them."}],"debrief":"Take over whole areas, planning included, to lift the mental load, not just do more tasks.","relearn":"Take whole areas, planning and all, to truly lighten your partner's load.","persona":"Vikram","source":"lift the weight"},
  {"id":"ep2-025","cat":"parental-mental-load","type":"reflect","hook":"Lensy: the parent who never has to remember is the one who isn't carrying the load. Worth noticing?","prompt":"What's your take?","options":["Worth it","I'll notice","True"],"affirm":"If you never have to remember the child-admin, you're not carrying the mental load; noticing that is the start of change.","relearn":"The parent who never has to remember isn't carrying the mental load; noticing that starts the fix.","persona":"any","source":"who remembers"},
  {"id":"ep2-026","cat":"parental-mental-load","type":"match","hook":"Match a sign of an unequal mental load to the fair fix.","pairs":[{"left":"One parent is everyone's reminder service","right":"Each owns their own domains"},{"left":"One always 'just knows' the schedule","right":"Both keep the shared calendar"},{"left":"One worries alone at night","right":"Share the worrying out loud"},{"left":"One spots every problem first","right":"Both watch their own areas"},{"left":"One holds all the passwords and forms","right":"Split who-owns-what admin"}],"relearn":"Unequal load shows in who reminds, knows, worries, spots and holds it all; fair fixes share each of those.","persona":"Divya","source":"fair fixes"},
  {"id":"ep2-027","cat":"parental-mental-load","type":"branch","hook":"Your partner is exhausted by the invisible load, and you want to say 'just tell me what to do'.","options":[{"text":"Instead offer to take ownership so they stop having to manage you","consequence":"You remove the management, not add to it.","outcome":"ownership","best":true},{"text":"Say 'just make me a list' and wait","consequence":"'Make me a list' keeps them as your manager, which is the load itself."}],"debrief":"Offer to own areas so your partner stops managing you; a list keeps the load on them.","relearn":"Take ownership instead of asking for a list; the managing is the load to lift.","persona":"Vikram","source":"remove the managing"},
  {"id":"ep2-028","cat":"involved-dads","type":"strike-rewrite","hook":"\"A father looking after his own child is 'babysitting' or 'helping mum'.\"","myth":{"un":"A father looking after his own child is 'babysitting' or 'helping mum'.","re":"It's just parenting; caregiving is a father's own responsibility, not help he gives the mother.","why":"You don't help with, or babysit, your own kid."},"relearn":"A father caring for his child is parenting, his own responsibility, not babysitting or helping mum.","persona":"Vikram","source":"not babysitting"},
  {"id":"ep2-029","cat":"involved-dads","type":"strike-rewrite","hook":"\"Fathers are providers; nurturing just isn't a man's role.\"","myth":{"un":"Fathers are providers; nurturing just isn't a man's role.","re":"Men can nurture fully; involved, hands-on, emotionally present fathers are good for children and for fathers themselves.","why":"Tenderness isn't unmanly; it's good fathering."},"relearn":"Nurturing is fully a father's role; involved, emotionally present fathers are good for kids and for themselves.","persona":"Vikram","source":"men nurture"},
  {"id":"ep2-030","cat":"involved-dads","type":"strike-rewrite","hook":"\"Kids only really need their mother in the early years.\"","myth":{"un":"Kids only really need their mother in the early years.","re":"Infants attach to both parents from birth, and involved fathers boost children's development, confidence and behaviour.","why":"Both parents matter from day one."},"relearn":"Children need both parents from the start; involved fathers boost development, confidence and behaviour.","persona":"Vikram","source":"both from birth"},
  {"id":"ep2-031","cat":"involved-dads","type":"branch","hook":"You want to be close to your child, but worry hands-on fathering isn't 'manly'.","options":[{"text":"Lean fully into hands-on, tender fathering anyway","consequence":"You build a real bond and model new manhood.","outcome":"tender","best":true},{"text":"Hold back to fit an old idea of being a man","consequence":"Holding back to seem 'manly' costs you and your child."}],"debrief":"Be a hands-on, tender father; that's good fathering and a fuller manhood, not a weakness.","relearn":"Lean into tender fathering; the old 'manly distance' costs you and your child.","persona":"Vikram","source":"lean in"},
  {"id":"ep2-032","cat":"involved-dads","type":"role-play","hook":"Relatives tease you for doing nappies and night feeds 'like a woman'. You want to own it proudly.","setup":"Own it proudly:","yourLine":[{"text":"\"This is just being a dad, and I wouldn't miss it for anything.\"","best":true},{"text":"\"Haha, yeah, my wife usually handles that stuff.\""}],"relearn":"Owning hands-on fathering proudly shrugs off the teasing and models that caregiving is simply a dad's job.","persona":"Vikram","source":"own it proudly"},
  {"id":"ep2-033","cat":"involved-dads","type":"branch","hook":"You realise you instinctively pass the crying baby straight to your partner.","options":[{"text":"Practise soothing your child yourself until you're confident","consequence":"You become a parent your child turns to.","outcome":"confident","best":true},{"text":"Always hand off, staying the 'backup' parent","consequence":"Always handing off keeps you a backup your child learns not to rely on."}],"debrief":"Practise soothing yourself; always handing the baby off keeps you a backup parent.","relearn":"Soothe your child yourself rather than handing off; that's how you become their go-to.","persona":"Vikram","source":"dont hand off"},
  {"id":"ep2-034","cat":"involved-dads","type":"role-play","hook":"Your partner hovers and corrects how you parent, so you've stopped trying. You want to talk it through.","setup":"Raise it kindly:","yourLine":[{"text":"\"I want to do my full share, can you trust me to do it my way and learn?\"","best":true},{"text":"\"Fine, you do it, you clearly think I can't.\""}],"relearn":"Asking to be trusted to learn your own way addresses gatekeeping so you can become a true equal parent.","persona":"Vikram","source":"ask to be trusted"},
  {"id":"ep2-035","cat":"involved-dads","type":"reflect","hook":"Lensy: 'to be a good father, and to be seen as one' is a worthy goal, and it starts with showing up. Resonate?","prompt":"What do you think?","options":["Resonates","Showing up","That's the goal"],"affirm":"Being a good, hands-on father, and being recognised as one, starts with consistently showing up in the care.","relearn":"Being a good father, and seen as one, starts with showing up in the everyday care.","persona":"Vikram","source":"show up"},
  {"id":"ep2-036","cat":"involved-dads","type":"strike-rewrite","hook":"\"Asking a dad to be fully involved is somehow anti-men.\"","myth":{"un":"Asking a dad to be fully involved is somehow anti-men.","re":"Involved fatherhood is pro-men: it boosts fathers' bonds, confidence and wellbeing, and it's something to claim, not a burden.","why":"Equality here lifts fathers too."},"relearn":"Involved fatherhood isn't anti-men; it lifts fathers' bonds, confidence and wellbeing, and is theirs to claim.","persona":"any","source":"pro-men"},
  {"id":"ep2-037","cat":"involved-dads","type":"sort","hook":"Sort: involved, hands-on fatherhood, or distant 'provider-only' fathering?","items":[{"id":"a","text":"Doing nights, feeds and play"},{"id":"b","text":"Seeing kids only at weekends by choice"},{"id":"c","text":"Knowing your child's daily world"},{"id":"d","text":"Leaving all care to mum and elders"},{"id":"e","text":"Owning the bedtime routine yourself"},{"id":"f","text":"Sending money but rarely being home"}],"bins":[{"id":"involved","label":"Involved","valence":"pos"},{"id":"distant","label":"Distant","valence":"neg"}],"key":{"a":"involved","b":"distant","c":"involved","d":"distant","e":"involved","f":"distant"},"relearn":"Doing nights, knowing your child's world and owning bedtime is involved fathering; weekend-only and absent is distant.","persona":"Vikram","source":"involved vs distant"},
  {"id":"ep2-038","cat":"involved-dads","type":"match","hook":"Match each fathering act to what it gives the child.","pairs":[{"left":"Hands-on daily care","right":"Security and a real bond"},{"left":"Emotional presence","right":"Confidence and resilience"},{"left":"Showing up consistently","right":"Trust they can rely on you"},{"left":"Sharing the load with mum","right":"A calmer home for everyone"},{"left":"Soothing them yourself","right":"A parent they turn to too"}],"relearn":"Daily care, emotional presence, consistency, sharing and soothing are what an involved father gives his child.","persona":"Vikram","source":"what it gives"},
  {"id":"ep2-039","cat":"involved-dads","type":"reflect","hook":"Lensy: the most precious thing a father can give isn't money, it's himself, present and hands-on. Land okay?","prompt":"What's your take?","options":["Lands okay","Himself","Present matters"],"affirm":"A father's presence and hands-on care matter to a child even more than his financial provision.","relearn":"The most precious thing a father gives isn't money, it's himself, present and hands-on.","persona":"Vikram","source":"give himself"},
  {"id":"ep2-040","cat":"involved-dads","type":"spot","hook":"Spot the two lines that make a father a helper, not an equal parent.","scene":[{"id":"a","text":"Owning care without being asked","trick":false},{"id":"b","text":"Waiting to be told what to do","trick":true},{"id":"c","text":"Knowing the child's routines himself","trick":false},{"id":"d","text":"Only doing tasks he's handed","trick":true},{"id":"e","text":"Booking the appointments himself","trick":false}],"why":"Waiting to be told and only doing handed tasks make a helper; an equal parent owns care and knows the routines.","relearn":"An equal-parent father owns care unprompted and knows the routines, rather than waiting to be told.","persona":"Vikram","source":"equal not helper"},
  {"id":"ep2-041","cat":"involved-dads","type":"branch","hook":"Work culture treats your fatherhood as irrelevant, nudging you to stay a distant provider.","options":[{"text":"Protect time to actually parent, within what you can control","consequence":"Your child gets a present father.","outcome":"present","best":true},{"text":"Accept that work means you can't really parent","consequence":"Accepting that work rules it out cedes your fatherhood by default."}],"debrief":"Protect what parenting time you can against a work culture that erases fatherhood.","relearn":"Guard time to parent against work norms that sideline fathers; don't cede it by default.","persona":"Vikram","source":"protect the time"},
  {"id":"ep2-042","cat":"kids-are-watching","type":"strike-rewrite","hook":"\"Kids don't really notice who does what at home.\"","myth":{"un":"Kids don't really notice who does what at home.","re":"Children learn gender roles largely by watching their parents; what they see at home becomes their normal.","why":"Home is a child's first model of how the world works."},"relearn":"Children notice and absorb who does what at home; it teaches them what's normal for their own future.","persona":"Meena","source":"kids notice"},
  {"id":"ep2-043","cat":"kids-are-watching","type":"strike-rewrite","hook":"\"Telling kids about equality matters more than what they see us do.\"","myth":{"un":"Telling kids about equality matters more than what they see us do.","re":"Children copy what they see far more than what they're told; modelling equality at home is the most powerful lesson.","why":"Actions teach louder than lectures."},"relearn":"Kids learn equality from what they see us do, not what we say; modelling it at home teaches the most.","persona":"Meena","source":"show not tell"},
  {"id":"ep2-044","cat":"kids-are-watching","type":"sort","persona":"Meena","source":"what kids learn","hook":"Sort: what a child learns from a home where parenting is shared, or from one where it isn't?","items":[{"id":"a","text":"Care is everyone's job"},{"id":"b","text":"Caring is only for women"},{"id":"c","text":"Dads are nurturing too"},{"id":"d","text":"Men don't do 'kid stuff'"},{"id":"e","text":"Either parent can run the home"},{"id":"f","text":"A real man only earns, never cares"}],"bins":[{"id":"shared","label":"From a shared home","valence":"pos"},{"id":"unequal","label":"From an unequal one","valence":"neg"}],"key":{"a":"shared","b":"unequal","c":"shared","d":"unequal","e":"shared","f":"unequal"},"relearn":"A shared home teaches that care is everyone's job and dads nurture; an unequal one teaches the old divide."},
  {"id":"ep2-045","cat":"kids-are-watching","type":"branch","hook":"You catch your child mimicking a gendered split, 'that's mummy's job', from watching home.","options":[{"text":"Adjust what you model so they see care shared by both","consequence":"Your child relearns equality from real life.","outcome":"remodel","best":true},{"text":"Correct them verbally but keep the unequal split","consequence":"Words alone against an unequal split confuse more than they correct."}],"debrief":"When kids echo a gendered split, change what you model, not just what you say.","relearn":"Reteach equality by changing what kids see you do, not by correcting words.","persona":"Priya","source":"remodel it"},
  {"id":"ep2-046","cat":"kids-are-watching","type":"reflect","hook":"Lensy: your child's idea of a 'normal' family is being built right now, by watching you two. Powerful?","prompt":"What do you think?","options":["Powerful","Right now","I feel it"],"affirm":"Children build their template of a normal family by watching their parents, so shared parenting shapes their future.","relearn":"Your child's idea of a normal family is built by watching you; shared parenting shapes their future.","persona":"any","source":"building normal"},
  {"id":"ep2-047","cat":"kids-are-watching","type":"reflect","hook":"Lensy: break the cycle, and your kids may raise their kids more equally too. Worth it?","prompt":"What's your take?","options":["Worth it","Break the cycle","For their kids too"],"affirm":"Modelling equality can break an intergenerational cycle, shaping how your children parent their own children.","relearn":"Modelling shared parenting can break the cycle, shaping how your kids parent their own kids one day.","persona":"Meena","source":"break the cycle"},
  {"id":"ep2-048","cat":"kids-are-watching","type":"match","persona":"any","source":"see then expect","hook":"Match what kids see at home to what they grow up expecting.","pairs":[{"left":"Both parents caring and cooking","right":"That care is for everyone"},{"left":"Dad emotionally present","right":"That men can be tender"},{"left":"Decisions made together","right":"That partners are equals"},{"left":"Mum with her own work and rest","right":"That a mother is a whole person"},{"left":"Sons and daughters sharing chores","right":"That housework has no gender"}],"relearn":"What children see, shared care, a present dad, joint decisions, becomes what they expect and give as adults."},
  {"id":"ep2-049","cat":"kids-are-watching","type":"sort","persona":"Priya","source":"models which","hook":"Sort: models equality for kids, or models the old divide?","items":[{"id":"a","text":"A son seeing dad cook and care"},{"id":"b","text":"A daughter told kitchen is her future"},{"id":"c","text":"Both parents at the doctor visit"},{"id":"d","text":"Only mum ever handling the children"},{"id":"e","text":"Parents deciding the home budget together"},{"id":"f","text":"A son excused from chores his sister isn't"}],"bins":[{"id":"equality","label":"Models equality","valence":"pos"},{"id":"divide","label":"Models the divide","valence":"neg"}],"key":{"a":"equality","b":"divide","c":"equality","d":"divide","e":"equality","f":"divide"},"relearn":"A caring dad and both parents sharing model equality; gendered scripts and mum-only care model the old divide."},
  {"id":"ep2-050","cat":"kids-are-watching","type":"strike-rewrite","hook":"\"Raising a son to do 'girl' chores will confuse or weaken him.\"","myth":{"un":"Raising a son to do 'girl' chores will confuse or weaken him.","re":"Teaching all children to cook, clean and care raises capable, respectful adults; chores have no gender.","why":"Life skills aren't gendered, and they strengthen kids."},"relearn":"Teaching sons to cook, clean and care raises capable, respectful adults; chores have no gender.","persona":"Priya","source":"chores no gender"},
  {"id":"ep2-051","cat":"kids-are-watching","type":"spot","persona":"Meena","source":"teaches the wrong lesson","hook":"Spot the two moments that teach a child the opposite of equality at home.","scene":[{"id":"a","text":"Both parents sharing care visibly","trick":false},{"id":"b","text":"Praising dad loudly for rare 'help'","trick":true},{"id":"c","text":"Sons and daughters given the same chores","trick":false},{"id":"d","text":"'That's mum's job,' dad tells the kids","trick":true},{"id":"e","text":"Both parents at the school meeting","trick":false}],"why":"Cheering a dad's rare 'help' and calling care 'mum's job' teach kids care is mum's and a dad's care is extra.","relearn":"Kids learn equality from shared care and same-for-all chores, not from praising a father's rare help."},
  {"id":"ep2-052","cat":"kids-are-watching","type":"branch","hook":"Relatives push your kids toward gendered roles, girls cook, boys don't.","options":[{"text":"Gently counter it and keep modelling shared roles at home","consequence":"Your home stays your child's strongest lesson.","outcome":"counter","best":true},{"text":"Let the gendered scripting go unchallenged","consequence":"Unchallenged scripting shapes your kids instead of your example."}],"debrief":"Counter relatives' gendered scripting and keep modelling shared roles; home is the strongest lesson.","relearn":"Gently counter the scripting; your modelled equality at home is the lesson that lasts.","persona":"Priya","source":"counter scripting"},
  {"id":"ep2-053","cat":"kids-are-watching","type":"reflect","hook":"Lensy: the equality you live at home is the curriculum your kids actually absorb. Feel the weight?","prompt":"What's your take?","options":["Feel it","Lived curriculum","It matters"],"affirm":"The equality children absorb is the one their parents actually live at home, not the one they're told about.","relearn":"The equality you live at home is the real curriculum your kids absorb.","persona":"any","source":"lived curriculum"},
  {"id":"ep2-054","cat":"kids-are-watching","type":"match","persona":"any","source":"patterns plant beliefs","hook":"Match a home pattern to the belief it plants in a child.","pairs":[{"left":"Shared, respectful parenting","right":"Partners are equal teammates"},{"left":"Dad doing his fair share","right":"Care is unisex and normal"},{"left":"Mum with her own life too","right":"Women are full people, not just mums"},{"left":"Both parents owning the planning","right":"Remembering kid-stuff isn't only mum's"},{"left":"Sons taught to cook and clean","right":"Home skills belong to every child"}],"relearn":"Each home pattern plants a belief: equal teammates, unisex care, and women as full people."},
  {"id":"ep2-055","cat":"everyone-gains","type":"strike-rewrite","hook":"\"Equal parenting is a sacrifice fathers make for mothers.\"","myth":{"un":"Equal parenting is a sacrifice fathers make for mothers.","re":"Shared parenting is better for everyone: children thrive, mothers are less overloaded, and fathers gain bond, confidence and wellbeing.","why":"It's a win for all three, not a trade."},"relearn":"Equal parenting isn't a sacrifice; it's better for children, mothers and fathers alike.","persona":"Vikram","source":"win for all"},
  {"id":"ep2-056","cat":"everyone-gains","type":"match","hook":"Match each member of the family to what shared parenting gives them.","pairs":[{"left":"The child","right":"Two bonded parents and better development"},{"left":"The mother","right":"Less overload and burnout"},{"left":"The father","right":"A real bond, confidence and wellbeing"},{"left":"The grandparents","right":"A calmer home, not one tired parent to prop up"},{"left":"The marriage","right":"Two teammates instead of a manager and a helper"}],"relearn":"Shared parenting gives the child two bonded parents, the mother relief, and the father a real bond; everyone gains.","persona":"any","source":"everyone gains"},
  {"id":"ep2-057","cat":"everyone-gains","type":"reflect","hook":"Lensy: this isn't about fairness alone; an equal home is happier and healthier for the whole family. Agree?","prompt":"What do you think?","options":["Agree","Happier home","Healthier"],"affirm":"Shared parenting isn't only fair; it makes the whole family happier and healthier, which is why it's worth building.","relearn":"Equal parenting isn't just fair; it makes the whole family happier and healthier.","persona":"any","source":"happier home"},
  {"id":"ep2-058","cat":"everyone-gains","type":"sort","hook":"Sort: a real benefit of shared parenting, or a myth about it?","items":[{"id":"a","text":"Kids bond with both parents"},{"id":"b","text":"It makes fathers 'less manly'"},{"id":"c","text":"Mothers get relief and a life"},{"id":"d","text":"It harms the children"},{"id":"e","text":"Fathers gain confidence and a closer bond"},{"id":"f","text":"Sharing means dad 'loses' his role"}],"bins":[{"id":"benefit","label":"Real benefit","valence":"pos"},{"id":"myth","label":"Myth","valence":"neg"}],"key":{"a":"benefit","b":"myth","c":"benefit","d":"myth","e":"benefit","f":"myth"},"relearn":"Bonding with both parents, relief for mothers and a closer bond for fathers are real; 'less manly', 'harms kids' and 'dad loses out' are myths.","persona":"any","source":"benefit vs myth"},
  {"id":"ep2-059","cat":"everyone-gains","type":"strike-rewrite","hook":"\"A mother who shares the load is a lazy or lesser mother.\"","myth":{"un":"A mother who shares the load is a lazy or lesser mother.","re":"Sharing the load isn't laziness; it lets a mother be a whole person and a less depleted, more present parent.","why":"Support makes a better, not lesser, parent."},"relearn":"A mother who shares the load isn't lazy or lesser; she's a more rested, present and whole parent.","persona":"Divya","source":"not a lesser mum"},
  {"id":"ep2-060","cat":"everyone-gains","type":"branch","hook":"You frame equal parenting in your head as 'giving up' something as a father.","options":[{"text":"Reframe it as gaining a bond and a fuller life","consequence":"You lean in for what you get, not lose.","outcome":"gain","best":true},{"text":"Resent it as pure sacrifice","consequence":"Reframing as gain makes you lean in; framing it as pure sacrifice breeds resentment that the whole family feels."}],"debrief":"See equal parenting as gaining a bond and a fuller life, not giving something up.","relearn":"Reframe equal parenting as a gain, a bond and a richer life, not a sacrifice to resent.","persona":"Vikram","source":"reframe as gain"},
  {"id":"ep2-061","cat":"everyone-gains","type":"match","hook":"Match a worry about equal parenting to the reassuring reality.","pairs":[{"left":"'I'll lose my role as provider'","right":"You gain the role of a real parent"},{"left":"'She won't need me'","right":"Your child will know and need you"},{"left":"'It's all giving things up'","right":"Everyone in the family gains"},{"left":"'I'll have no time left for myself'","right":"A shared load frees time for you both"},{"left":"'People will think I'm henpecked'","right":"A present father is respected, not pitied"}],"relearn":"Each worry about equal parenting has a reassuring reality: a deeper role, a child who needs you, and gains for all.","persona":"Vikram","source":"worry to reality"},
  {"id":"ep2-062","cat":"everyone-gains","type":"reflect","hook":"Lensy: the home where parenting is shared is the home most kids would choose to grow up in. Sit right?","prompt":"What's your take?","options":["Sits right","Kids would choose it","Yes"],"affirm":"A home with shared, equal parenting is the kind of home that's best for children to grow up in.","relearn":"A home where parenting is shared is the one most kids would thrive growing up in.","persona":"any","source":"kids would choose"},
  {"id":"ep2-063","cat":"everyone-gains","type":"sort","hook":"Sort: a sign equal parenting is working for the whole family, or a sign of strain to address?","items":[{"id":"a","text":"Both parents rested enough to enjoy the child"},{"id":"b","text":"One parent always depleted"},{"id":"c","text":"Both bonded with the kids"},{"id":"d","text":"Resentment simmering under the surface"},{"id":"e","text":"Either parent can take a day off, guilt-free"},{"id":"f","text":"One parent keeps a silent mental tally"}],"bins":[{"id":"working","label":"Working for all","valence":"pos"},{"id":"strain","label":"Strain to address","valence":"uhoh"}],"key":{"a":"working","b":"strain","c":"working","d":"strain","e":"working","f":"strain"},"relearn":"Both rested and bonded means it's working; one always depleted or a silent tally is strain to rebalance together.","persona":"any","source":"working vs strain"},
  {"id":"ep2-064","cat":"everyone-gains","type":"strike-rewrite","hook":"\"Once kids arrive, gender equality has to take a back seat.\"","myth":{"un":"Once kids arrive, gender equality has to take a back seat.","re":"Parenthood is exactly when equality matters most; the defaults snap back hardest, so this is the time to hold the line.","why":"Don't surrender equality at the moment it counts most."},"relearn":"Parenthood is when equality matters most, not least; this is the time to hold the line, not surrender it.","persona":"Divya","source":"hold the line"},
  {"id":"ep2-065","cat":"everyone-gains","type":"role-play","hook":"Your partner doubts equal parenting can really work for your family. You want to make the case warmly.","setup":"Make the case:","yourLine":[{"text":"\"Let's try it properly, it's better for the kids, for you and for me, we all win.\"","best":true},{"text":"\"Maybe it's just not realistic for us.\""}],"relearn":"Framing equal parenting as a win for all three invites your partner to try it rather than dismiss it.","persona":"Vikram","source":"make the case"},
  {"id":"ep2-066","cat":"everyone-gains","type":"role-play","hook":"A new-father friend thinks being hands-on means losing status. You want to reframe it for him.","setup":"Reframe it for him:","yourLine":[{"text":"\"Being a present dad is the most rewarding thing I do, you gain way more than you give.\"","best":true},{"text":"\"Yeah, enjoy your freedom while it lasts, I guess.\""}],"relearn":"Sharing that involved fatherhood is rewarding, not a loss, helps a friend lean in rather than hold back.","persona":"Vikram","source":"reframe for friend"},
  {"id":"ep2-067","cat":"everyone-gains","type":"spot","hook":"Spot the two lies about who benefits from shared parenting.","scene":[{"id":"a","text":"Children, mothers and fathers all gain","trick":false},{"id":"b","text":"Only mothers benefit, at fathers' cost","trick":true},{"id":"c","text":"Whole families are happier and healthier","trick":false},{"id":"d","text":"A father gains a real bond with his kids","trick":false},{"id":"e","text":"It's a loss for men so women can win","trick":true}],"why":"Shared parenting benefits children, mothers and fathers; 'only mum benefits at dad's cost' and 'men lose so women win' are both false.","relearn":"Shared parenting is a whole-family gain, not a benefit to mothers at fathers' expense.","persona":"any","source":"who benefits"},
  {"id":"ep2-068","cat":"tools-and-help","type":"branch","hook":"You want a practical way to make parenting genuinely equal, not just intend it.","options":[{"text":"Map every task and the mental load, then each own a fair set","consequence":"Equality becomes a plan, not a wish.","outcome":"mapped","best":true},{"text":"Just promise to 'try to be fairer' vaguely","consequence":"A vague promise to try fairer rarely shifts the default."}],"debrief":"Make parenting equal with a real plan: map the tasks and mental load and each own a fair share.","relearn":"Turn fair-parenting intentions into a real map of owned tasks and load; vague promises don't.","persona":"Vikram","source":"make a plan"},
  {"id":"ep2-069","type":"match","persona":"any","source":"the toolkit","hook":"Match each tool to the job it does.","pairs":[{"left":"The task-and-load map","right":"See and split everything fairly"},{"left":"A shared family calendar","right":"Both hold the schedule"},{"left":"A weekly parenting check-in","right":"Rebalance as life changes"},{"left":"Owning a whole domain","right":"Carry the noticing, not just tasks"},{"left":"Routing real burnout to help","right":"Reach Tele-MANAS 14416"}],"relearn":"The task-and-load map, a shared calendar, a check-in, owned domains and routing burnout are the core tools of equal parenting.","cat":"tools-and-help"},
  {"id":"ep2-070","cat":"tools-and-help","type":"branch","hook":"Your fair split worked at first, but it's quietly drifted back to one parent.","options":[{"text":"Re-run the check-in and rebalance, defaults creep back","consequence":"You keep equality alive over time.","outcome":"rebalanced","best":true},{"text":"Assume it's fine because you split it once","consequence":"Assuming a one-time split holds lets the default quietly return."}],"debrief":"Equal parenting needs regular rebalancing; defaults creep back, so revisit the split as life changes.","relearn":"Rebalance regularly; an equal split set once drifts back to one parent over time.","persona":"Divya","source":"rebalance over time"},
  {"id":"ep2-071","cat":"tools-and-help","type":"reflect","hook":"Lensy: equality at home is maintained, not declared once; small regular check-ins keep it true. Make sense?","prompt":"What do you think?","options":["Makes sense","Maintained","Regular check-ins"],"affirm":"Equal parenting is maintained through small regular check-ins, not settled by a single declaration.","relearn":"Equality at home is maintained with regular check-ins, not declared once and forgotten.","persona":"any","source":"maintained"},
  {"id":"ep2-072","cat":"tools-and-help","type":"branch","hook":"One of you is burning out under the parenting load despite your best efforts.","options":[{"text":"Treat burnout seriously, rebalance and reach for support","consequence":"You protect the parent and the family.","outcome":"supported","best":true},{"text":"Push through until something breaks","consequence":"Pushing through risks the parent's health and the home."}],"debrief":"Take parental burnout seriously: rebalance the load and reach for support (see Looking After You).","relearn":"Treat parental burnout as real; rebalance and get support, don't push to breaking point.","persona":"Divya","source":"burnout is real"},
  {"id":"ep2-073","cat":"tools-and-help","type":"strike-rewrite","hook":"\"If equal parenting is hard to keep up, it's just not for our family.\"","myth":{"un":"If equal parenting is hard to keep up, it's just not for our family.","re":"It takes ongoing effort for everyone; the difficulty is normal and workable with tools and check-ins, not a reason to quit.","why":"Hard to maintain isn't impossible."},"relearn":"Equal parenting being hard to keep up is normal and workable with tools and check-ins, not a reason to give up.","persona":"any","source":"workable not quit"},
  {"id":"ep2-074","cat":"tools-and-help","type":"role-play","hook":"You want to set the tone with your partner for how you'll parent as a team. You open it warmly.","setup":"Set the tone together:","yourLine":[{"text":"\"Let's parent as true equals, share the load and the worry, and check in often so it stays fair.\"","best":true},{"text":"\"Let's just see how it goes and sort it later.\""}],"relearn":"Setting an explicit equal-team tone with regular check-ins keeps parenting fair instead of drifting to default.","persona":"Vikram","source":"set the tone"},
  {"id":"ep2-075","type":"sort","persona":"any","source":"support vs undermine","hook":"Sort: a healthy support for equal parenting, or a habit that undermines it?","items":[{"id":"a","text":"Regular check-ins and rebalancing"},{"id":"b","text":"Maternal gatekeeping of the dad"},{"id":"c","text":"Both owning the mental load"},{"id":"d","text":"Praising dad for the bare minimum"},{"id":"e","text":"One shared calendar you both keep"},{"id":"f","text":"Waiting to be told every task"}],"bins":[{"id":"support","label":"Supports equality","valence":"pos"},{"id":"undermine","label":"Undermines it","valence":"neg"}],"key":{"a":"support","c":"support","e":"support","b":"undermine","d":"undermine","f":"undermine"},"relearn":"Check-ins, shared load and a shared calendar support equal parenting; gatekeeping, bare-minimum praise and waiting undermine it.","cat":"tools-and-help"},
  {"id":"ep2-076","type":"spot","persona":"any","source":"sustainable path","hook":"Spot the two moves that aren't a sustainable path to equal parenting.","scene":[{"id":"a","text":"Small regular rebalancing","trick":false},{"id":"b","text":"One grand promise, never revisited","trick":true},{"id":"c","text":"Both owning load and care over time","trick":false},{"id":"d","text":"Set it once and never look again","trick":true},{"id":"e","text":"A check-in when life changes","trick":false}],"why":"A one-off promise and set-and-forget both let the default return; regular rebalancing and shared ownership last.","relearn":"Equal parenting lasts through regular rebalancing and shared ownership, not a single grand promise left unrevisited.","cat":"tools-and-help"},
  {"id":"ep2-077","cat":"tools-and-help","type":"reflect","hook":"Lensy: two parents, one team — share the care, split the load, model it for the kids, and rebalance as life shifts. Feel set up to parent as equals?","prompt":"Where do you land?","options":["Set up for it","Still finding our balance","We'll keep adjusting"],"affirm":"Splitting care and load, modelling equality for the kids, and rebalancing as life shifts is what lets a couple parent as a real team.","relearn":"The plan is simple: share care, split the load, model it for the kids, and rebalance as things change.","persona":"any","source":"equipped"},
  {"id":"ep2-078","cat":"tools-and-help","type":"branch","hook":"You want one principle to carry through all the years of raising your kids.","options":[{"text":"Lead with: both fully parent, share the load and worry, model it","consequence":"You have a compass for the whole journey.","outcome":"compass","best":true},{"text":"Let whoever's default it became keep carrying it","consequence":"Letting the default carry it rebuilds the gap you want to close."}],"debrief":"One principle carries it: both fully parent, share the load and worry, and model equality.","relearn":"Lead with both fully parenting and sharing the load; the default rebuilds the gap.","persona":"Vikram","source":"the one principle"},
  {"id":"ep2-079","type":"spot","persona":"any","source":"fair over years","hook":"Spot the two moves that fail to keep parenting fair as the years go on.","scene":[{"id":"a","text":"Revisiting the split as kids grow","trick":false},{"id":"b","text":"Assuming the first arrangement is forever","trick":true},{"id":"c","text":"Both staying hands-on and informed","trick":false},{"id":"d","text":"Letting the default quietly take over","trick":true},{"id":"e","text":"Re-trading domains at each new stage","trick":false}],"why":"Assuming the first split is forever and letting the default take over both unbalance it; revisiting and staying hands-on keep it fair.","relearn":"Keep parenting fair over the years by revisiting the split and both staying hands-on, not set-and-forget.","cat":"tools-and-help"},
  {"id":"ep2-080","cat":"parental-mental-load","type":"role-play","hook":"Your partner sighs that they're holding all the invisible child-admin in their head. You want to genuinely take some.","setup":"Take real ownership:","yourLine":[{"text":"\"Give me health and school to fully run, appointments, forms, the lot, so it's off your mind.\"","best":true},{"text":"\"Just remind me whenever something's due.\""}],"relearn":"Offering to fully run whole domains lifts the managing, not just the tasks, off your partner's mind.","persona":"Vikram","source":"take a domain"},
  {"id":"ep2-081","cat":"kids-are-watching","type":"role-play","hook":"Your young child says caring for babies is 'only for mummies'. You want to gently reframe it.","setup":"Reframe it warmly:","yourLine":[{"text":"\"Caring is for everyone, see how Papa feeds and cuddles you too? That's what dads do.\"","best":true},{"text":"\"You'll understand when you're older.\""}],"relearn":"Showing a child that caring is for everyone, with dad doing it, reteaches them in the moment they're learning.","persona":"Priya","source":"reframe for child"},
  {"id":"ep2-082","cat":"everyone-gains","type":"role-play","hook":"A relative pities your partner for 'having to do so much' while praising you for little. You want to set it straight.","setup":"Set it straight kindly:","yourLine":[{"text":"\"We share it as equals, and honestly I'm the lucky one getting this time with my kids.\"","best":true},{"text":"\"Yes, she's a saint, I don't know how she does it all.\""}],"relearn":"Naming that you share as equals, and that involvement is a gift to you, corrects the lopsided praise.","persona":"Vikram","source":"set praise straight"},
  {"id":"ep2-083","cat":"tools-and-help","type":"role-play","hook":"You and your partner are starting out as parents and want to agree how to keep it fair from day one.","setup":"Agree it upfront:","yourLine":[{"text":"\"Let's both own real shares from the start and check in weekly, so fair is the default, not the exception.\"","best":true},{"text":"\"We'll just figure it out as we go.\""}],"relearn":"Agreeing owned shares and a weekly check-in from day one makes fairness the default instead of a constant fight.","persona":"Vikram","source":"fair from day one"},
  {"id":"ep2-084","type":"spot","persona":"any","source":"keep load shared","hook":"Spot the two moves that quietly keep the mental load on one parent.","scene":[{"id":"a","text":"Both owning whole domains end-to-end","trick":false},{"id":"b","text":"One parent assigning tasks to the other","trick":true},{"id":"c","text":"A weekly check-in to rebalance","trick":false},{"id":"d","text":"One parent keeping all the lists","trick":true},{"id":"e","text":"Each tracking their own domain","trick":false}],"why":"Assigning tasks and keeping all the lists leave one parent the manager doing the tracking; owned domains share the load.","relearn":"Keep the mental load shared by both owning whole domains and checking in, not by one assigning tasks or holding the lists.","cat":"tools-and-help"},
  {"id":"ep2-1260","cat":"everyone-gains","type":"strike-rewrite","hook":"\"A father who does half the parenting has 'gone soft'.\"","myth":{"un":"A father who does half the parenting has 'gone soft'.","re":"A father who does half is a fuller parent and partner; involvement is strength, not softness.","why":"Showing up for your kids takes more, not less, of a man."},"relearn":"A hands-on father hasn't gone soft; he's claimed a fuller, stronger role at home.","persona":"Vikram","source":"not gone soft"},
  {"id":"ep2-1261","cat":"everyone-gains","type":"strike-rewrite","hook":"\"Equality at home is a women's issue that costs men.\"","myth":{"un":"Equality at home is a women's issue that costs men.","re":"Equal parenting is pro-men too: fathers gain bond, confidence and wellbeing, not a bill to pay.","why":"It lifts all three of you, never men losing so women win."},"relearn":"Equality at home isn't men's loss; it's a gain for fathers as much as for mothers and kids.","persona":"any","source":"pro-men gain"},
  {"id":"ep2-1262","cat":"everyone-gains","type":"strike-rewrite","hook":"\"The most a father gives his kids is a good income.\"","myth":{"un":"The most a father gives his kids is a good income.","re":"Income matters, but your presence and bond shape your child far more than your pay slip ever can.","why":"Kids remember a father who showed up, not his salary."},"relearn":"A father's biggest gift isn't his income; it's his presence and the bond it builds.","persona":"Vikram","source":"more than income"},
  {"id":"ep2-1263","cat":"everyone-gains","type":"strike-rewrite","hook":"\"A wife who shares the parenting is letting her husband do her job.\"","myth":{"un":"A wife who shares the parenting is letting her husband do her job.","re":"Parenting was never one parent's job; sharing it means two owners, not a wife offloading work.","why":"It's their child together, so the care is theirs together."},"relearn":"Sharing the parenting isn't a wife shirking; it's two parents owning what was always shared.","persona":"any","source":"never one job"},
  {"id":"ep2-1264","cat":"everyone-gains","type":"strike-rewrite","hook":"\"Splitting parenting fairly just leaves both parents exhausted.\"","myth":{"un":"Splitting parenting fairly just leaves both parents exhausted.","re":"A fair split spreads the load so neither parent burns out; that's the whole point, less depletion, not more.","why":"Two carrying half beats one carrying it all."},"relearn":"A fair split doesn't tire both out; it stops one parent carrying everything alone.","persona":"any","source":"less depletion"},
  {"id":"ep2-1265","cat":"everyone-gains","type":"strike-rewrite","hook":"\"A mother who travels for work is putting the family second.\"","myth":{"un":"A mother who travels for work is putting the family second.","re":"When the other parent owns the home in turn, her work and the kids both thrive; it's not a family she abandoned.","why":"Two capable parents means neither is chained to the door."},"relearn":"A working mother isn't sidelining the family; a shared home lets both her career and her kids flourish.","persona":"Divya","source":"both thrive"},
  {"id":"ep2-1266","cat":"everyone-gains","type":"strike-rewrite","hook":"\"Once you have kids, the marriage just has to take a back seat.\"","myth":{"un":"Once you have kids, the marriage just has to take a back seat.","re":"Sharing the load as teammates protects the marriage too; partners who share stay closer, not further apart.","why":"A manager and a helper drift; two teammates pull together."},"relearn":"Kids needn't sink the marriage; sharing the load keeps you teammates, not a manager and a helper.","persona":"any","source":"marriage gains too"},
  {"id":"ep2-1267","cat":"everyone-gains","type":"strike-rewrite","hook":"\"A father bonding deeply with a baby is unusual and a bit much.\"","myth":{"un":"A father bonding deeply with a baby is unusual and a bit much.","re":"Babies attach to fathers from birth; a deeply bonded dad is exactly how it's meant to be, and a gift to them both.","why":"That early bond shapes the child and lifts the father for life."},"relearn":"A father bonding deeply with a baby isn't 'too much'; it's natural, and good for them both.","persona":"Vikram","source":"bond is meant to be"},
  {"id":"ep2-1268","cat":"everyone-gains","type":"strike-rewrite","hook":"\"If I share parenting, my kids will respect me less as the man of the house.\"","myth":{"un":"If I share parenting, my kids will respect me less as the man of the house.","re":"Kids respect a father they actually know; the dad who feeds, plays and listens earns more respect, not less.","why":"Presence builds the bond that respect grows from."},"relearn":"Sharing the care doesn't cost a father respect; being present is what earns it.","persona":"Vikram","source":"respect from presence"},
  {"id":"ep2-1269","cat":"everyone-gains","type":"strike-rewrite","hook":"\"A less-stressed mother is just a mother who's stopped trying so hard.\"","myth":{"un":"A less-stressed mother is just a mother who's stopped trying so hard.","re":"A mother with the load shared isn't trying less; she's a rested, whole person and a more present parent for it.","why":"Support makes a better parent, not a slacker."},"relearn":"A less-stressed mother hasn't given up; sharing the load lets her be present and whole.","persona":"Divya","source":"rested not slacking"},
  {"id":"ep2-1270","cat":"everyone-gains","type":"strike-rewrite","hook":"\"Holding out for equal parenting will just wreck the peace at home.\"","myth":{"un":"Holding out for equal parenting will just wreck the peace at home.","re":"Naming an unfair split kindly and rebalancing it builds real peace; the buried resentment is what wrecks it.","why":"Quiet fairness lasts; silent imbalance corrodes."},"relearn":"Asking for a fair split needn't break the peace; the unspoken imbalance is what does.","persona":"any","source":"real peace"},
  {"id":"ep2-1271","cat":"everyone-gains","type":"match","hook":"Match each person to one real thing they gain from shared parenting.","pairs":[{"left":"A toddler","right":"Comfort from either parent, not just one"},{"left":"A new mother","right":"Sleep and her own self back"},{"left":"A father","right":"The closeness he'd otherwise have missed"},{"left":"An older child","right":"A model of how partners treat each other"},{"left":"The whole household","right":"Less tension, more steadiness"}],"relearn":"Every person in a home gains from shared parenting: the kids, both parents and the household itself.","persona":"any","source":"each one gains"},
  {"id":"ep2-1272","cat":"everyone-gains","type":"match","hook":"Match the 'sacrifice' fear to the gain that's actually waiting.","pairs":[{"left":"'I'll lose my evenings'","right":"You gain bedtime stories you'll never forget"},{"left":"'I'll lose my freedom'","right":"You gain a teammate to share it back"},{"left":"'I'll lose my edge at work'","right":"You gain a calmer home to come back to"},{"left":"'I'll lose face with friends'","right":"You gain kids who actually know you"},{"left":"'I'll lose the easy life'","right":"You gain a richer one"}],"relearn":"Each fear of sacrifice in shared parenting hides a real gain; it's a trade up, not a loss.","persona":"Vikram","source":"fear to gain"},
  {"id":"ep2-1273","cat":"everyone-gains","type":"match","hook":"Match the lopsided home to the shared home it could become.","pairs":[{"left":"One parent runs on empty","right":"Both rested enough to enjoy the kids"},{"left":"Dad is the 'fun visitor'","right":"Dad is a parent the kids rely on"},{"left":"Mum tracks every detail alone","right":"Each owns whole domains end to end"},{"left":"Resentment goes unspoken","right":"Check-ins keep it fair over time"},{"left":"Kids see one carer","right":"Kids see two equal parents"}],"relearn":"A lopsided home can become a shared one; naming it and rebalancing turns strain into a gain for all.","persona":"any","source":"lopsided to shared"},
  {"id":"ep2-1274","cat":"everyone-gains","type":"match","hook":"Match each family member to how a shared home shows up for them.","pairs":[{"left":"The daughter","right":"Sees a father who cooks and cares"},{"left":"The son","right":"Learns care is his to give too"},{"left":"The mother","right":"Is a person, not just a service"},{"left":"The father","right":"Is missed when he's away, not just obeyed"},{"left":"The couple","right":"Are partners, not boss and assistant"}],"relearn":"A shared home shows up well for everyone, shaping how each child and parent sees their place.","persona":"Priya","source":"shows up for each"},
  {"id":"ep2-1275","cat":"everyone-gains","type":"match","hook":"Match the myth about equal parenting to the truth that beats it.","pairs":[{"left":"'It's a loss for men'","right":"It's a gain in bond and wellbeing"},{"left":"'Mum is the lesser if she shares'","right":"She's a fuller, present parent"},{"left":"'Kids only need one carer'","right":"Kids thrive with two bonded parents"},{"left":"'Equality fades once kids come'","right":"It matters most once kids come"},{"left":"'It's a trade-off'","right":"It's a win for all three"}],"relearn":"Every myth about equal parenting has a truth that beats it; sharing is a whole-family win, not a trade.","persona":"any","source":"myth beaten"},
  {"id":"ep2-1276","cat":"everyone-gains","type":"match","hook":"Match each gain of shared parenting to who feels it most.","pairs":[{"left":"A deeper bond from the start","right":"The father"},{"left":"Room to breathe and rebuild herself","right":"The mother"},{"left":"Two safe laps to climb into","right":"The child"},{"left":"A calmer, less-stretched house","right":"The grandparents"},{"left":"Two pulling together, not apart","right":"The marriage"}],"relearn":"Each gain of shared parenting lands somewhere real; the father, mother, child, elders and the marriage all benefit.","persona":"any","source":"who feels it"},
  {"id":"ep2-1277","cat":"everyone-gains","type":"match","hook":"Match the comment relatives make to the calm reframe that holds.","pairs":[{"left":"'Poor thing, doing it all alone?'","right":"'We share it, so neither of us is alone'"},{"left":"'You're so good to help her'","right":"'It's my child too, not helping'"},{"left":"'Won't this spoil the kids?'","right":"'Two bonded parents is good for them'"},{"left":"'A man shouldn't be in the kitchen'","right":"'My kids see both of us cook'"},{"left":"'She's lucky to have you'","right":"'We're lucky to have each other'"}],"relearn":"A calm reframe meets each relative's comment, naming the home as shared without picking a fight.","persona":"any","source":"relative reframe"},
  {"id":"ep2-1278","cat":"everyone-gains","type":"match","hook":"Match each parent's old story to the gain hiding inside it.","pairs":[{"left":"'I gave up my career edge'","right":"You gained kids who know you"},{"left":"'I gave up being the boss at home'","right":"You gained a real partner"},{"left":"'I gave up my Sundays'","right":"You gained being missed when away"},{"left":"'I gave up the quiet life'","right":"You gained a fuller one"},{"left":"'I gave up doing it my way'","right":"You gained doing it together"}],"relearn":"Inside each 'I gave up' is a real gain; shared parenting trades a thinner life for a richer one.","persona":"Vikram","source":"old story flipped"},
  {"id":"ep2-1279","cat":"everyone-gains","type":"reflect","hook":"Lensy: when a father is fully in, he doesn't just give his kids more; he gets a whole side of life he'd have missed. True for you?","prompt":"What's your sense?","options":["True for me","He gains a lot","Worth claiming"],"affirm":"A father who's fully in gains a bond and a side of life he'd otherwise miss; the gain runs both ways.","relearn":"Involved fatherhood isn't only a gift to the kids; the father gains just as much.","persona":"Vikram","source":"gains both ways"},
  {"id":"ep2-1280","cat":"everyone-gains","type":"reflect","hook":"Lensy: a home where the load is shared tends to be a calmer, warmer home for everyone in it. Ring true?","prompt":"What do you think?","options":["Rings true","Calmer home","Warmer too"],"affirm":"When the load is shared, the whole home runs calmer and warmer; that's a gain everyone living there feels.","relearn":"Sharing the load makes the whole home calmer and warmer, not just fairer.","persona":"any","source":"calmer warmer"},
  {"id":"ep2-1281","cat":"everyone-gains","type":"reflect","hook":"Lensy: a mother getting a full night's sleep and a bit of her own life back isn't a luxury; it's good for the whole family. Agree?","prompt":"Your take?","options":["Agree","Good for all","Not a luxury"],"affirm":"A rested mother with a little of herself back is a more present parent; the family gains, it's not a luxury.","relearn":"A mother's rest and space aren't a luxury; they make her a more present parent and the family gains.","persona":"Divya","source":"rest helps all"},
  {"id":"ep2-1282","cat":"everyone-gains","type":"reflect","hook":"Lensy: equality at home isn't about keeping score; it's about both of you ending the week less stretched. Sit right?","prompt":"What's your view?","options":["Sits right","Less stretched","Not a scoreboard"],"affirm":"Equality at home is two people less stretched, not a scoreboard; the aim is a lighter load for both.","relearn":"Equality at home isn't a scoreboard; it's both parents ending up less stretched.","persona":"any","source":"not a scoreboard"},
  {"id":"ep2-1283","cat":"everyone-gains","type":"reflect","hook":"Lensy: of all the times to keep equality alive, the years with young kids may matter most. How does that land?","prompt":"What do you feel?","options":["Lands true","Matters most now","Hold the line"],"affirm":"The young-kid years are exactly when equality matters most; holding the line then sets the tone for years.","relearn":"Equality matters most in the early-kid years, when defaults snap back hardest; that's the time to hold it.","persona":"any","source":"matters most now"},
  {"id":"ep2-1284","cat":"everyone-gains","type":"reflect","hook":"Lensy: when both parents are bonded and steady, a child gets two safe places to land instead of one. Worth it?","prompt":"What's your sense?","options":["Worth it","Two safe places","Good for the child"],"affirm":"Two bonded parents give a child two safe places to land; the child's wellbeing is right at the centre of this.","relearn":"Shared parenting centres the child too; two bonded parents give them two safe places to land.","persona":"Priya","source":"two safe places"},
  {"id":"ep2-1285","cat":"everyone-gains","type":"reflect","hook":"Lensy: nobody chooses the perfect split overnight; the win is just both of you a little less alone in it. Fair?","prompt":"Your take?","options":["Fair","Less alone","Step by step"],"affirm":"The win isn't a perfect overnight split; it's both parents a little less alone in the work, built step by step.","relearn":"The gain isn't a flawless split; it's both parents feeling less alone, rebalanced over time.","persona":"any","source":"less alone"},
  {"id":"ep2-1286","cat":"everyone-gains","type":"reflect","hook":"Lensy: a son who grows up seeing his dad care learns that caring is his too; that's a quiet gift to his future family. Agree?","prompt":"What do you think?","options":["Agree","A quiet gift","Good for him"],"affirm":"A son who sees his dad care learns it's his to give too; that's a gain for him and the family he'll one day build.","relearn":"Watching a caring father teaches a son that care is his too; the gain reaches the next generation.","persona":"Priya","source":"gift to his future"},
  {"id":"ep2-1287","cat":"everyone-gains","type":"sort","hook":"Sort: who is a winner when parenting is truly shared?","items":[{"id":"a","text":"The child, with two bonded parents"},{"id":"b","text":"Nobody; someone always loses"},{"id":"c","text":"The mother, less depleted"},{"id":"d","text":"The father, more confident and close"},{"id":"e","text":"Only the mother, never the father"},{"id":"f","text":"The marriage, two teammates"}],"bins":[{"id":"win","label":"A real winner","valence":"pos"},{"id":"false","label":"False framing","valence":"neg"}],"key":{"a":"win","b":"false","c":"win","d":"win","e":"false","f":"win"},"relearn":"Shared parenting has many winners: the child, the mother, the father and the marriage; 'someone loses' is false.","persona":"any","source":"who wins"},
  {"id":"ep2-1288","cat":"everyone-gains","type":"sort","hook":"Sort: a gain a father gets from being fully involved, or a loss he was warned he'd suffer?","items":[{"id":"a","text":"A close, lasting bond with his kids"},{"id":"b","text":"More confidence as a parent"},{"id":"c","text":"Losing his place as head of the house"},{"id":"d","text":"Being 'demoted' from provider"},{"id":"e","text":"Better wellbeing and less regret later"},{"id":"f","text":"Looking weak in front of others"}],"bins":[{"id":"gain","label":"A real gain","valence":"pos"},{"id":"warned","label":"A warned-of 'loss'","valence":"neg"}],"key":{"a":"gain","b":"gain","c":"warned","d":"warned","e":"gain","f":"warned"},"relearn":"Involved fathers gain a bond, confidence and wellbeing; the 'losses' they're warned of, weakness or demotion, are myths.","persona":"Vikram","source":"gain vs warned loss"},
  {"id":"ep2-1289","cat":"everyone-gains","type":"sort","hook":"Sort: a whole-family gain of equal parenting, or a zero-sum trade where one wins and one loses?","items":[{"id":"a","text":"Mum rests; dad bonds; kids thrive"},{"id":"b","text":"Dad gives up time so mum can rest"},{"id":"c","text":"Both parents less burnt out"},{"id":"d","text":"Mum wins only if dad loses"},{"id":"e","text":"The kids get more of both parents"},{"id":"f","text":"One parent's gain is the other's cost"}],"bins":[{"id":"whole","label":"Whole-family gain","valence":"pos"},{"id":"zero","label":"Zero-sum myth","valence":"neg"}],"key":{"a":"whole","b":"zero","c":"whole","d":"zero","e":"whole","f":"zero"},"relearn":"Equal parenting is a whole-family gain; the zero-sum 'one wins, one loses' framing is a myth.","persona":"any","source":"gain vs zero-sum"},
  {"id":"ep2-1290","cat":"everyone-gains","type":"sort","hook":"Sort: a sign a couple reframed parenting as a shared gain, or a sign it's still seen as one person's burden?","items":[{"id":"a","text":"'We' language about the kids"},{"id":"b","text":"'I'm helping her out today'"},{"id":"c","text":"Either parent plans the week"},{"id":"d","text":"'Ask your mother, she handles that'"},{"id":"e","text":"Both proud of the bond they've built"},{"id":"f","text":"One keeps score of who did more"}],"bins":[{"id":"shared","label":"Shared gain","valence":"pos"},{"id":"burden","label":"One's burden","valence":"uhoh"}],"key":{"a":"shared","b":"burden","c":"shared","d":"burden","e":"shared","f":"burden"},"relearn":"'We' language and shared planning signal a shared gain; 'helping her out' or keeping score signals one person's burden.","persona":"any","source":"shared vs burden"},
  {"id":"ep2-1291","cat":"everyone-gains","type":"sort","hook":"Sort: a true reason equality matters most once kids arrive, or a false reason to let it slide then?","items":[{"id":"a","text":"Defaults snap back hardest now"},{"id":"b","text":"Kids learn from what they watch"},{"id":"c","text":"'Survival mode means roles must split'"},{"id":"d","text":"Both are stretched, so share more"},{"id":"e","text":"'No time for fairness with a baby'"},{"id":"f","text":"'One of us must be the default carer'"}],"bins":[{"id":"true","label":"True: hold the line","valence":"pos"},{"id":"slide","label":"False: let it slide","valence":"neg"}],"key":{"a":"true","b":"true","c":"slide","d":"true","e":"slide","f":"slide"},"relearn":"Kids arriving is the reason to hold the line, not let it slide; defaults snap back hardest just as kids start watching.","persona":"any","source":"hold vs slide"},
  {"id":"ep2-1292","cat":"everyone-gains","type":"sort","hook":"Sort: a real upside of a shared home for the kids, or a worry that simply doesn't hold?","items":[{"id":"a","text":"They can turn to either parent"},{"id":"b","text":"'They'll be confused by two carers'"},{"id":"c","text":"They see partners as a team"},{"id":"d","text":"'A boy needs only his father's example'"},{"id":"e","text":"They learn care has no gender"},{"id":"f","text":"'Dad's care will make them soft'"}],"bins":[{"id":"upside","label":"Real upside","valence":"pos"},{"id":"worry","label":"Worry that fails","valence":"neg"}],"key":{"a":"upside","b":"worry","c":"upside","d":"worry","e":"upside","f":"worry"},"relearn":"Kids gain from two carers and a team to watch; 'confused', 'too soft' or 'only dad's example' are worries that don't hold.","persona":"Priya","source":"upside vs worry"},
  {"id":"ep2-1293","cat":"everyone-gains","type":"sort","hook":"Sort: a healthy way to keep equal parenting going, or depletion creeping in that needs support?","items":[{"id":"a","text":"A monthly check-in on who carries what"},{"id":"b","text":"One parent crying from sheer tiredness"},{"id":"c","text":"Swapping domains when one's stretched"},{"id":"d","text":"Persistent emptiness for weeks"},{"id":"e","text":"Both naming what they need out loud"},{"id":"f","text":"Snapping at the kids, feeling numb"}],"bins":[{"id":"healthy","label":"Healthy upkeep","valence":"pos"},{"id":"depleted","label":"Depletion to support","valence":"uhoh"}],"key":{"a":"healthy","b":"depleted","c":"healthy","d":"depleted","e":"healthy","f":"depleted"},"relearn":"Check-ins and swapping domains keep it healthy; weeks of emptiness is burnout, reach Tele-MANAS 14416.","persona":"any","source":"healthy vs depleted"},
  {"id":"ep2-1294","cat":"everyone-gains","type":"sort","hook":"Sort: a genuine gain for the mother when the load is shared, or a slur thrown at her for sharing it?","items":[{"id":"a","text":"Time to be a whole person again"},{"id":"b","text":"'She's lazy for not doing it all'"},{"id":"c","text":"Less burnout, more patience with kids"},{"id":"d","text":"'A real mother manages alone'"},{"id":"e","text":"A career and motherhood, both alive"},{"id":"f","text":"'She's a lesser mum now'"}],"bins":[{"id":"gain","label":"Her real gain","valence":"pos"},{"id":"slur","label":"Unfair slur","valence":"neg"}],"key":{"a":"gain","b":"slur","c":"gain","d":"slur","e":"gain","f":"slur"},"relearn":"A mother who shares gains rest, patience and her whole self; 'lazy' or 'lesser mum' are unfair slurs, not truths.","persona":"Divya","source":"gain vs slur"},
  {"id":"ep2-1295","cat":"everyone-gains","type":"branch","hook":"A friend says, 'I earn, she does the kids, everyone's happy.' You see what he's missing.","options":[{"text":"Tell him you gained most by being hands-on","consequence":"He hears a gain to claim, not a chore.","outcome":"opens","best":true},{"text":"Call him a bad father for opting out","consequence":"Shame shuts the door; the gain opens it.","outcome":"closes"}],"debrief":"Naming the bond he stands to gain invites a father in; shame just makes him defend the old split.","relearn":"Reach a provider-only father by showing what he gains by leaning in, not by shaming him.","persona":"Vikram","source":"show the gain"},
  {"id":"ep2-1296","cat":"everyone-gains","type":"branch","hook":"Exhausted with a newborn, you're tempted by 'she does nights, I do money'.","options":[{"text":"Share nights and own domains together","consequence":"Both stay rested; neither is the lone default.","outcome":"shared","best":true},{"text":"Let the default harden 'just for now'","consequence":"That quietly makes one parent the manager for years."}],"debrief":"The newborn fog is when defaults set; sharing nights now keeps the gain alive for everyone.","relearn":"In the newborn haze, share nights and domains rather than letting the default harden.","persona":"any","source":"don't let it harden"},
  {"id":"ep2-1297","cat":"everyone-gains","type":"branch","hook":"Your wife wants to return to work; your mother says the kids will suffer.","options":[{"text":"Back her and own your half","consequence":"Both her work and the kids thrive.","outcome":"thrive","best":true},{"text":"Ask her to wait till the kids are older","consequence":"Stalling her quietly tells the kids one parent matters less."}],"debrief":"Backing her return and carrying your share is a gain for her, you and the kids, not a risk.","relearn":"Supporting a partner's return to work and owning your half is a win for the children.","persona":"Vikram","source":"back her return"},
  {"id":"ep2-1298","cat":"everyone-gains","type":"branch","hook":"At dinner, an uncle praises you for 'allowing' your wife her job.","options":[{"text":"Say it's her right and a gain for us all","consequence":"Kids hear her work is normal and shared.","outcome":"models","best":true},{"text":"Take the praise and say nothing","consequence":"Silent praise teaches the kids dad 'permits' mum."}],"debrief":"Correcting 'allowing' in front of the kids models that a mother's work is hers by right.","relearn":"How you answer 'allowing her to work' teaches the kids who decides; name it as her right.","persona":"any","source":"not allowing"},
  {"id":"ep2-1299","cat":"everyone-gains","type":"branch","hook":"You've started real parenting and a mate teases that you're 'whipped'.","options":[{"text":"Own it: 'Best thing I do, my kids know me'","consequence":"You reframe it as a gain; he sees no shame.","outcome":"reframes","best":true},{"text":"Laugh it off and pull back at home","consequence":"Pulling back to look tough costs you the bond."}],"debrief":"Naming involved fatherhood as the best thing you do shrugs off the jibe and protects the bond.","relearn":"Teased for being a hands-on dad, own it as a gain; don't trade the bond back to look 'tough'.","persona":"Vikram","source":"own it warmly"},
  {"id":"ep2-1300","cat":"everyone-gains","type":"branch","hook":"Both stretched thin, equality feels too hard to keep up. What now?","options":[{"text":"Remap who carries what and rebalance","consequence":"The split eases; you stay teammates.","outcome":"rebalance","best":true},{"text":"Let it slide back to the old default","consequence":"Sliding back puts the whole load on one parent."}],"debrief":"When it feels too hard, that's the cue to remap and rebalance, not to quit; difficulty is workable.","relearn":"Equal parenting feeling hard is normal; remap and rebalance rather than sliding back to one carrier.","persona":"any","source":"rebalance not quit"},
  {"id":"ep2-1301","cat":"everyone-gains","type":"branch","hook":"You've slipped into the 'fun parent' while your partner carries the rest.","options":[{"text":"Take a whole domain, dull bits included","consequence":"You become a parent the kids rely on, not a guest.","outcome":"owns","best":true},{"text":"Keep the fun bits, call it your share","consequence":"Cherry-picking fun keeps you a visitor."}],"debrief":"Claiming a whole domain, dull parts and all, turns the fun visitor into an equal parent.","relearn":"Being the 'fun parent' isn't sharing; own a full domain to become an equal parent.","persona":"Vikram","source":"more than fun bits"},
  {"id":"ep2-1302","cat":"everyone-gains","type":"role-play","hook":"Your wife says she feels guilty taking a weekend away from the kids. You want to free her of that guilt.","setup":"Reassure her:","yourLine":[{"text":"\"Go; the kids and I will be great, and you coming back rested is good for all of us.\"","best":true},{"text":"\"I'll manage somehow, I suppose, if you really have to go.\""}],"relearn":"Telling a partner her rest is good for the whole family frees her guilt and makes the break a shared gain.","persona":"Vikram","source":"free her guilt"},
  {"id":"ep2-1303","cat":"everyone-gains","type":"role-play","hook":"A colleague jokes that taking parental leave will 'kill your career'. You want to push back without heat.","setup":"Push back calmly:","yourLine":[{"text":"\"Honestly, this time with my kids is the best call I've made; I don't regret a day of it.\"","best":true},{"text":"\"Yeah, maybe you're right, I should be careful about that.\""}],"relearn":"Naming involved fatherhood as a gain, not a career risk, models that leave is worth claiming, not apologising for.","persona":"Vikram","source":"leave is worth it"},
  {"id":"ep2-1304","cat":"everyone-gains","type":"role-play","hook":"Your teenager asks why you do half the cooking when 'other dads don't'. You want to answer honestly.","setup":"Answer them:","yourLine":[{"text":"\"Because this is our home together, and I'd hate to miss out on caring for you all.\"","best":true},{"text":"\"Your mother made me, that's just how it is here.\""}],"relearn":"Framing your share as something you'd hate to miss teaches a child that care is a gain a father claims, not a chore imposed.","persona":"Vikram","source":"why you share"},
  {"id":"ep2-1305","cat":"everyone-gains","type":"role-play","hook":"Your partner says, 'Sometimes I feel I've lost myself in being a mum.' You want to respond as a teammate.","setup":"Respond warmly:","yourLine":[{"text":"\"Let's get you some real time back; I've got the kids, and I want you to have your life too.\"","best":true},{"text":"\"That's just what being a mum is, isn't it; we all make sacrifices.\""}],"relearn":"Offering to hold the kids so a partner reclaims herself turns her depletion into a shared, fixable gain, not a fate.","persona":"any","source":"get yourself back"},
  {"id":"ep2-1306","cat":"everyone-gains","type":"role-play","hook":"A relative tells your son that 'helping mummy cook isn't for boys'. You want to correct it gently for him.","setup":"Correct it for him:","yourLine":[{"text":"\"In our home everyone cooks; it'll make him a man people are glad to live with.\"","best":true},{"text":"\"Hmm, maybe, let's not make a fuss about it now.\""}],"relearn":"Standing up for a son's right to care teaches him it's a strength to gain, and corrects the relative without a row.","persona":"Priya","source":"cooking is for boys too"},
  {"id":"ep2-1307","cat":"everyone-gains","type":"role-play","hook":"Your father says you 'spoil' your wife by sharing the housework and kids. You want to answer with respect.","setup":"Answer respectfully:","yourLine":[{"text":"\"We're partners, Papa; sharing it keeps us both well, and I'm a better father for it.\"","best":true},{"text":"\"You're right, I'm probably being too soft about all this.\""}],"relearn":"Naming the sharing as partnership and a gain for you both holds your ground with elders without disrespect.","persona":"Vikram","source":"not spoiling her"},
  {"id":"ep2-1308","cat":"everyone-gains","type":"role-play","hook":"Your partner thanks you 'for helping so much' with the kids. You want to gently reframe it.","setup":"Reframe it kindly:","yourLine":[{"text":"\"You don't have to thank me; they're mine too, and I'd not miss this for anything.\"","best":true},{"text":"\"No problem, happy to pitch in whenever you need a hand.\""}],"relearn":"Declining the 'thanks for helping' frame names you as an equal owner, not a helper, and claims the gain as yours too.","persona":"Vikram","source":"not helping, owning"},
  {"id":"ep2-1309","cat":"everyone-gains","type":"role-play","hook":"At a parents' meeting, another father says fathers 'just aren't built for this stuff'. You want to counter it.","setup":"Counter him kindly:","yourLine":[{"text":"\"I wasn't sure either at first; turns out we learn it by doing, and it's the best part of my week.\"","best":true},{"text":"\"True, it really is more of a mother's thing in the end.\""}],"relearn":"Saying you learned care by doing, and love it, busts 'not built for it' and shows other fathers the gain on offer.","persona":"Vikram","source":"learned by doing"},
  {"id":"ep2-1310","cat":"everyone-gains","type":"role-play","hook":"Your partner worries the neighbours will judge her for going back to work. You want to steady her.","setup":"Steady her:","yourLine":[{"text":"\"Let them talk; our kids will have two parents they're proud of, and that's the win.\"","best":true},{"text":"\"Maybe wait a bit, you know how people here gossip.\""}],"relearn":"Backing a partner against the gossip names two proud, present parents as the real win and keeps equality on track.","persona":"any","source":"let them talk"},
  {"id":"ep2-1311","cat":"everyone-gains","type":"role-play","hook":"Your kids ask if you're 'babysitting' while mum's away. You want to set the word straight, lightly.","setup":"Set it straight:","yourLine":[{"text":"\"It's not babysitting when it's my own kids; this is just me being your dad.\"","best":true},{"text":"\"Yes, dad's in charge of babysitting duty today, lucky me.\""}],"relearn":"Correcting 'babysitting' even in a joke teaches kids a father's care is his job and his gain, not a favour.","persona":"Vikram","source":"not babysitting"},
  {"id":"ep2-1312","cat":"everyone-gains","type":"role-play","hook":"Your partner says she's scared sharing more means you'll resent her. You want to reassure her honestly.","setup":"Reassure her:","yourLine":[{"text":"\"I won't resent it; I'd resent missing out on the kids far more, this is a gift to me too.\"","best":true},{"text":"\"I'll try not to mind too much, I suppose, for your sake.\""}],"relearn":"Telling a partner the sharing is a gift, not a grudge, frees her fear and names the gain as mutual.","persona":"Vikram","source":"a gift to me too"},
  {"id":"ep2-1313","cat":"everyone-gains","type":"spot","hook":"Spot the two lines that frame equal parenting as men losing out.","scene":[{"id":"a","text":"'I get a real bond with my kids out of this'","trick":false},{"id":"b","text":"'Every hour I parent is an hour I lose'","trick":true},{"id":"c","text":"'We're both less burnt out this way'","trick":false},{"id":"d","text":"'She gains, so I must be losing'","trick":true},{"id":"e","text":"'Our home is calmer for all of us'","trick":false}],"why":"'Every hour I lose' and 'she gains so I lose' are zero-sum lies; shared parenting is a gain for fathers too, not a loss.","relearn":"Equal parenting isn't men losing out; the 'every hour is a loss' and 'she gains so I lose' framings are false.","persona":"Vikram","source":"men-lose lines"},
  {"id":"ep2-1314","cat":"everyone-gains","type":"spot","hook":"Spot the two comments that treat a sharing mother as a lesser mum.","scene":[{"id":"a","text":"'She's a whole person and a present parent'","trick":false},{"id":"b","text":"'A good mother wouldn't need help'","trick":true},{"id":"c","text":"'Rested, she has more patience for the kids'","trick":false},{"id":"d","text":"'She's gone lazy since he started helping'","trick":true},{"id":"e","text":"'Sharing lets her keep her own life too'","trick":false}],"why":"'A good mother wouldn't need help' and 'she's gone lazy' shame a sharing mother; sharing makes her more present, not lesser.","relearn":"A mother who shares isn't lazy or lesser; the comments calling her so are myths, not truths.","persona":"Divya","source":"lesser-mum comments"},
  {"id":"ep2-1315","cat":"everyone-gains","type":"spot","hook":"Spot the two excuses for letting equality slide once the baby arrives.","scene":[{"id":"a","text":"'Defaults snap back now, so hold the line'","trick":false},{"id":"b","text":"'No time for fairness with a newborn'","trick":true},{"id":"c","text":"'Sharing nights keeps us both standing'","trick":false},{"id":"d","text":"'Someone has to be the default carer'","trick":true},{"id":"e","text":"'The kids watch how we split this'","trick":false}],"why":"'No time for fairness' and 'someone must default' are excuses; the newborn stage is when equality matters most.","relearn":"A new baby is the reason to hold the line, not drop it; 'no time' and 'someone must default' are myths.","persona":"any","source":"slide excuses"},
  {"id":"ep2-1316","cat":"everyone-gains","type":"spot","hook":"Spot the two lines that frame a father's care as a favour, not his own job.","scene":[{"id":"a","text":"'These are my kids; caring for them is mine to do'","trick":false},{"id":"b","text":"'I helped her out with the baby today'","trick":true},{"id":"c","text":"'I own bedtime end to end'","trick":false},{"id":"d","text":"'I babysat so she could rest'","trick":true},{"id":"e","text":"'I'd hate to miss this part of their lives'","trick":false}],"why":"'Helped her out' and 'babysat' frame a father's own parenting as a favour to mum; it's his job and his gain, not a favour.","relearn":"A father caring for his child isn't 'helping' or 'babysitting'; the lines that say so miss that it's his own role.","persona":"Vikram","source":"favour lines"},
  {"id":"ep2-1317","cat":"everyone-gains","type":"spot","hook":"Spot the two worries about shared parenting that simply don't hold for the kids.","scene":[{"id":"a","text":"'Two bonded parents help them thrive'","trick":false},{"id":"b","text":"'Dad's care will make our son soft'","trick":true},{"id":"c","text":"'They learn partners can be a team'","trick":false},{"id":"d","text":"'Kids only really need mum early on'","trick":true},{"id":"e","text":"'They get comfort from either of us'","trick":false}],"why":"'Dad's care makes him soft' and 'kids only need mum early' are false; children thrive bonded to both parents from birth.","relearn":"Shared parenting is good for kids; 'it'll make him soft' and 'they only need mum early' are worries that don't hold.","persona":"Priya","source":"kid worries"},
  {"id":"ep2-1318","cat":"everyone-gains","type":"spot","hook":"Spot the two lines that sell equal parenting as a sacrifice instead of a gain.","scene":[{"id":"a","text":"'I gained kids who actually know me'","trick":false},{"id":"b","text":"'I gave up my whole life for this'","trick":true},{"id":"c","text":"'We're both less stretched now'","trick":false},{"id":"d","text":"'It's a price I pay so she's happy'","trick":true},{"id":"e","text":"'Best decision our family ever made'","trick":false}],"why":"'I gave up my whole life' and 'a price I pay for her' frame sharing as sacrifice; it's a gain for the whole family, not a cost.","relearn":"Equal parenting isn't a sacrifice you pay; the 'I gave up everything' and 'a price for her' lines miss the shared gain.","persona":"Vikram","source":"sacrifice lines"},
  {"id":"ep2-1319","cat":"everyone-gains","type":"spot","hook":"Spot the two replies that quietly undermine a co-parent instead of backing them.","scene":[{"id":"a","text":"'You've got this; do it your way'","trick":false},{"id":"b","text":"'You're doing it wrong, let me'","trick":true},{"id":"c","text":"'I trust how you handle bedtime'","trick":false},{"id":"d","text":"'Just leave it, I'll redo it'","trick":true},{"id":"e","text":"'Thanks for owning that, it helps'","trick":false}],"why":"'You're doing it wrong' and 'I'll redo it' undermine a co-parent; backing each other is what makes sharing work.","relearn":"Partners gain when they back, not undermine, each other; 'you're doing it wrong' quietly pushes a co-parent out.","persona":"any","source":"undermine replies"},
  {"id":"ep2-1080","cat":"involved-dads","type":"strike-rewrite","hook":"\"A good dad's main job is to earn; the hands-on stuff is the mother's department.\"","myth":{"un":"A good dad's main job is to earn; the hands-on stuff is the mother's department.","re":"Earning is part of the job, not all of it; your child also needs your hands, time and presence.","why":"A salary can't bathe, feed or comfort a child."},"relearn":"Providing is part of fathering, not the whole of it; kids need your hands-on care and presence too.","persona":"Vikram","source":"provide and present"},
  {"id":"ep2-1081","cat":"involved-dads","type":"strike-rewrite","hook":"\"He gives the baby a bottle sometimes, so he's basically doing half the parenting.\"","myth":{"un":"Doing a few visible tasks sometimes means he's doing half the parenting.","re":"Quality and ownership matter more than the odd task; a present father carries his share day in, day out.","why":"A bottle on Sunday isn't a shared load."},"relearn":"Quality of engagement matters more than the odd task; a present father owns his share daily, not occasionally.","persona":"Vikram","source":"quality over tokens"},
  {"id":"ep2-1082","cat":"involved-dads","type":"strike-rewrite","hook":"\"Men just aren't wired to soothe a crying baby; that's mum's instinct.\"","myth":{"un":"Men aren't wired to soothe a crying baby; that's a mother's instinct.","re":"Soothing is a learned skill, not an instinct; a father who practises becomes just as good at it.","why":"Whoever does the soothing gets practised at it."},"relearn":"Soothing is learned by practice, not a maternal instinct; fathers who do it get just as skilled.","persona":"Vikram","source":"soothing is learned"},
  {"id":"ep2-1083","cat":"involved-dads","type":"strike-rewrite","hook":"\"Taking paternity leave looks like he's not serious about his career.\"","myth":{"un":"Taking paternity leave makes a man look unserious about his career.","re":"Taking the leave you're owed to bond with your newborn is claiming good fatherhood, not slacking.","why":"Being there at the start is a strength, not a lapse."},"relearn":"Using paternity leave to bond is claiming good fatherhood; it's a strength, not a sign of being unserious.","persona":"Vikram","source":"claim the leave"},
  {"id":"ep2-1142","cat":"involved-dads","type":"strike-rewrite","hook":"\"Real fathers stay strict and distant; getting tender confuses the kids.\"","myth":{"un":"Real fathers stay strict and distant; being tender confuses the kids.","re":"Warmth and tenderness build trust and security; a child gains, not loses, from a gentle father.","why":"Tenderness is good fathering, not weakness."},"relearn":"A warm, tender father builds his child's trust and security; distance isn't strength, it's a missed bond.","persona":"Vikram","source":"tender not distant"},
  {"id":"ep2-1084","cat":"involved-dads","type":"strike-rewrite","hook":"\"He works all day, so it's fair he does none of the nights or mornings.\"","myth":{"un":"He earns all day, so it's only fair he does none of the nights or mornings.","re":"Care work is real work too; both parents are tired, and both can own a share of nights and mornings.","why":"One paid job doesn't cancel the unpaid one."},"relearn":"Earning doesn't exempt a father from nights and mornings; care is real work both parents can own.","persona":"Vikram","source":"both are tired"},
  {"id":"ep2-1085","cat":"involved-dads","type":"strike-rewrite","hook":"\"Let the grandparents handle the baby; a father would just get in the way.\"","myth":{"un":"Leave the baby to the grandparents; a father would only get in the way.","re":"Grandparents are a gift, but your child still needs you hands-on; you're a parent, not a spare.","why":"Loving help doesn't replace a present father."},"relearn":"Grandparents help, but a father is still central; their care doesn't replace his own hands-on presence.","persona":"Vikram","source":"not a spare"},
  {"id":"ep2-1086","cat":"involved-dads","type":"strike-rewrite","hook":"\"Changing nappies and wiping noses is below a man; that's not a father's job.\"","myth":{"un":"Nappies and wiping noses are beneath a man; not a father's job.","re":"Nothing about care is beneath a father; the small, messy tasks are exactly how a bond is built.","why":"Bonds grow in the ordinary, messy moments."},"relearn":"No care task is beneath a father; the small, messy jobs are where a real bond with his child is built.","persona":"Vikram","source":"nothing beneath"},
  {"id":"ep2-1087","cat":"involved-dads","type":"strike-rewrite","hook":"\"As long as I show up for the fun bits on Sunday, I'm an involved dad.\"","myth":{"un":"Showing up for the fun bits on Sunday makes me an involved dad.","re":"Involvement is the dull, daily care too, not just the outings; quality of engagement beats mere contact.","why":"Sundays alone don't make a present father."},"relearn":"Real involvement is the daily, unglamorous care, not just weekend fun; engagement matters more than contact.","persona":"Vikram","source":"daily not sunday"},
  {"id":"ep2-1088","cat":"involved-dads","type":"strike-rewrite","hook":"\"A father bonds later; in the first months a baby only really wants its mother.\"","myth":{"un":"A father bonds later; in the first months a baby only really wants its mother.","re":"Infants attach to both parents from birth; the more you hold and soothe early, the deeper the bond.","why":"Attachment starts on day one, for both of you."},"relearn":"Infants attach to both parents from birth; early holding and soothing build a father's bond, not delay it.","persona":"Vikram","source":"bond from birth"},
  {"id":"ep2-1089","cat":"involved-dads","type":"strike-rewrite","hook":"\"If a dad does the cooking and care, the neighbours will say he's under his wife's thumb.\"","myth":{"un":"A dad who cooks and cares will be seen as under his wife's thumb.","re":"Sharing the home is partnership, not being ruled; what others gossip is no measure of a good father.","why":"A strong father isn't scared of a ladle."},"relearn":"Sharing home and care is partnership, not being controlled; neighbours' gossip doesn't define a good father.","persona":"any","source":"not under the thumb"},
  {"id":"ep2-1090","cat":"involved-dads","type":"strike-rewrite","hook":"\"Knowing the kid's shoe size or doctor's name is mum-stuff; dads don't track that.\"","myth":{"un":"Knowing shoe sizes and the doctor's name is mum-stuff; dads don't track that.","re":"Carrying the details of your child's life is part of fathering; either parent can hold that map.","why":"Knowing your child's world isn't gendered."},"relearn":"Tracking a child's details is part of fathering, not just mum-stuff; either parent can carry that map.","persona":"Vikram","source":"dads track too"},
  {"id":"ep2-1091","cat":"involved-dads","type":"strike-rewrite","hook":"\"He's a great dad, he never raises his voice and leaves all the discipline and care to her.\"","myth":{"un":"Being the easy-going parent who leaves all the work to her makes him a great dad.","re":"Being the fun one while she carries everything isn't great fathering; share the hard parts too.","why":"Fun is easy when someone else does the load."},"relearn":"Being only the fun parent while she carries the work isn't great fathering; an involved dad shares the hard parts.","persona":"Vikram","source":"more than the fun one"},
  {"id":"ep2-1092","cat":"involved-dads","type":"strike-rewrite","hook":"\"He helps so much with the kids,\" people say of an involved father.","myth":{"un":"A father who looks after his own kids is 'helping' with them.","re":"He's not helping; he's parenting his own children, the same responsibility as their mother.","why":"You don't 'help' with your own job."},"relearn":"A father caring for his own children is parenting, not helping; it's his responsibility, equal to hers.","persona":"any","source":"not helping"},
  {"id":"ep2-1093","cat":"involved-dads","type":"strike-rewrite","hook":"\"Wanting fathers more involved is just one more way modern life puts men down.\"","myth":{"un":"Asking fathers to be more involved is one more way modern life puts men down.","re":"Inviting fathers into full care lifts them; the bond, confidence and joy of it are a gain for men.","why":"More fatherhood is more for fathers, not less."},"relearn":"Inviting fathers into full care isn't anti-men; the bond, confidence and joy it brings is a gain for them.","persona":"any","source":"a gain for men"},
  {"id":"ep2-1094","cat":"involved-dads","type":"branch","hook":"Your toddler falls and cries, and instinctively reaches past you for mum, who's not home.","options":[{"text":"Pick her up and comfort her yourself until she settles","consequence":"She learns you're a safe pair of arms too.","outcome":"comforter","best":true},{"text":"Call mum and wait, since the child wants her","consequence":"Waiting for mum teaches the child you're not the one to turn to."}],"debrief":"Comfort her yourself; being the parent who soothes is how a child learns to turn to you too.","relearn":"Soothe your child yourself instead of deferring to mum; that's how you become a safe pair of arms.","persona":"Vikram","source":"safe arms"},
  {"id":"ep2-1095","cat":"involved-dads","type":"branch","hook":"Your firm offers two weeks' paternity leave. Colleagues hint that 'serious' men skip it.","options":[{"text":"Take the leave and be there for the early weeks","consequence":"You bond early and back up your partner.","outcome":"present","best":true},{"text":"Skip it to look committed at work","consequence":"Skipping the early weeks trades a once-only bond for office optics."}],"debrief":"Take the leave; the early weeks come once, and being there builds a bond office optics never will.","relearn":"Use the paternity leave you're owed; the newborn weeks come once and the bond outlasts any office optics.","persona":"Vikram","source":"take the leave"},
  {"id":"ep2-1096","cat":"involved-dads","type":"branch","hook":"At a family lunch, an uncle laughs that you 'babysit' your own kids while your wife relaxes.","options":[{"text":"Gently correct him: it's parenting, not babysitting","consequence":"You name it kindly and reset the frame.","outcome":"reframe","best":true},{"text":"Laugh along to keep the peace","consequence":"Laughing along lets 'babysitting' stand as the family's word for your care."}],"debrief":"Name it kindly: a father minding his own children is parenting, not babysitting, and worth saying out loud.","relearn":"Gently correct 'babysitting'; minding your own kids is parenting, and naming it resets the family frame.","persona":"Vikram","source":"name it kindly"},
  {"id":"ep2-1097","cat":"involved-dads","type":"branch","hook":"You've never done the school run alone and feel unsure of the bags, snacks and timings.","options":[{"text":"Take it on fully and learn the routine yourself","consequence":"You learn it and own a whole domain.","outcome":"owns-it","best":true},{"text":"Ask your wife to write you a list each morning","consequence":"A daily list keeps her the manager and you the helper who's told what to do."}],"debrief":"Take the school run on fully and learn it; owning the routine beats being handed a list each morning.","relearn":"Own the school run and learn its details yourself; a daily list keeps you the helper, not an equal parent.","persona":"Vikram","source":"own the routine"},
  {"id":"ep2-1098","cat":"involved-dads","type":"branch","hook":"Your partner keeps redoing how you dress or feed the baby, so you've started stepping back.","options":[{"text":"Talk it through and ask for room to do it your way","consequence":"You name the gatekeeping and stay in the care.","outcome":"stay-in","best":true},{"text":"Step back and let her take over again","consequence":"Stepping back hands the whole load back to her and parks you on the bench."}],"debrief":"Name the gatekeeping kindly and ask for room to learn; stepping back parks you as a backup parent.","relearn":"Address gatekeeping and ask for room to learn, rather than retreating and handing the load back.","persona":"Vikram","source":"ask for room"},
  {"id":"ep2-1099","cat":"involved-dads","type":"branch","hook":"A late-night work group keeps you online while your child's bedtime routine happens without you.","options":[{"text":"Block bedtime as protected family time most nights","consequence":"You share a daily ritual your child relies on.","outcome":"protected","best":true},{"text":"Treat bedtime as optional whenever work pings","consequence":"Letting work win each night makes you a stranger to your child's evenings."}],"debrief":"Protect bedtime most nights; a daily ritual builds a bond that always-on work quietly erodes.","relearn":"Guard bedtime as protected time; letting work win each evening makes you a stranger to it.","persona":"Vikram","source":"protect bedtime"},
  {"id":"ep2-1100","cat":"involved-dads","type":"branch","hook":"Your son says he wants to be 'just like papa.' You notice he never sees you do any care.","options":[{"text":"Start doing visible care so he sees it as normal","consequence":"He grows up seeing care as a man's work too.","outcome":"models-it","best":true},{"text":"Keep care invisible; he'll learn it elsewhere","consequence":"Keeping care invisible teaches him it isn't a man's job."}],"debrief":"Let your son see you do care; what he watches at home becomes his idea of what fathers do.","relearn":"Do care visibly so your son sees it as a man's work too; what he watches becomes his normal.","persona":"Vikram","source":"he watches you"},
  {"id":"ep2-1101","cat":"involved-dads","type":"branch","hook":"Your partner returns to work and assumes you'll keep 'helping when you can' with the kids.","options":[{"text":"Agree to own whole domains, not just help out","consequence":"You become a true co-parent, not a backup.","outcome":"co-owner","best":true},{"text":"Keep 'helping when you can' as the arrangement","consequence":"'Helping when you can' leaves her the manager of everything you don't."}],"debrief":"Own whole domains rather than 'helping when you can'; ownership is what makes you a real co-parent.","relearn":"Take ownership of whole domains instead of helping ad hoc; helping leaves her managing all the rest.","persona":"Vikram","source":"own a domain"},
  {"id":"ep2-1102","cat":"involved-dads","type":"branch","hook":"At the clinic, the nurse directs every question about the baby to your wife, not you.","options":[{"text":"Step in and answer; you know your child too","consequence":"You signal you're an equal, informed parent.","outcome":"step-in","best":true},{"text":"Let your wife field it all as usual","consequence":"Letting her field everything keeps you the parent who doesn't know the details."}],"debrief":"Answer the clinic's questions yourself; knowing your child's details marks you as an equal, informed parent.","relearn":"Step in and answer questions about your child; deferring every time keeps you the parent who doesn't know.","persona":"Vikram","source":"answer yourself"},
  {"id":"ep2-1103","cat":"involved-dads","type":"branch","hook":"Friends invite you for a long weekend away, leaving your partner solo with a newborn.","options":[{"text":"Skip or shorten it so you share these early weeks","consequence":"You back her up when it's hardest.","outcome":"backs-up","best":true},{"text":"Go for the full trip; she'll manage with her mother","consequence":"Going off keeps the newborn weeks her load while you opt out."}],"debrief":"Share the newborn weeks rather than opting out; being present when it's hardest is real fathering.","relearn":"Stay and share the hard newborn weeks; opting out leaves the whole early load on her.","persona":"Vikram","source":"share the hard weeks"},
  {"id":"ep2-1104","cat":"involved-dads","type":"branch","hook":"You realise you've never once taken your child to the doctor or known which jabs are due.","options":[{"text":"Take over health as a domain you own end-to-end","consequence":"You carry a real share of the mental load.","outcome":"owns-health","best":true},{"text":"Leave health to her; she 'just knows' that stuff","consequence":"Leaving health to her keeps you blind to half your child's life."}],"debrief":"Own a domain like health end-to-end; 'she just knows' is practice you can build, not a fixed truth.","relearn":"Take a whole domain such as health; she 'just knows' from practice you can build, not from instinct.","persona":"Vikram","source":"own health"},
  {"id":"ep2-1105","cat":"involved-dads","type":"role-play","hook":"A relative praises your wife for 'letting you help so much.' You want to gently reset the frame.","setup":"Reset it warmly:","yourLine":[{"text":"\"They're my kids too, so it's not helping, it's just being their dad.\"","best":true},{"text":"\"Ha, yes, she's kind to let me pitch in now and then.\""}],"relearn":"Saying 'it's not helping, it's being their dad' resets care as your own job, not a favour to your wife.","persona":"Vikram","source":"not helping line"},
  {"id":"ep2-1106","cat":"involved-dads","type":"role-play","hook":"Your boss assumes you'll skip the parent-teacher meeting because 'the mother handles that.'","setup":"Claim your place:","yourLine":[{"text":"\"I'll take that hour; I go to my child's meetings, same as anyone would.\"","best":true},{"text":"\"You're right, my wife will go, no need for me there.\""}],"relearn":"Claiming the hour for your child's meeting shows fathering is part of your life, not the mother's job alone.","persona":"Vikram","source":"claim the meeting"},
  {"id":"ep2-1107","cat":"involved-dads","type":"role-play","hook":"Your father says holding the baby all evening will make you 'soft.' You want to stand your ground kindly.","setup":"Stand your ground:","yourLine":[{"text":"\"Holding my child isn't soft, papa; it's the best part of my day.\"","best":true},{"text":"\"Maybe you're right, I should leave the cuddling to her.\""}],"relearn":"Saying holding your child isn't 'soft' but the best part of your day claims tenderness as good fathering.","persona":"Vikram","source":"not soft"},
  {"id":"ep2-1108","cat":"involved-dads","type":"role-play","hook":"Your partner starts listing what needs doing for the baby. You want to own a part, not wait for tasks.","setup":"Take ownership:","yourLine":[{"text":"\"Leave the night feeds and the doctor visits to me; I'll own those fully.\"","best":true},{"text":"\"Just tell me what to do and I'll do it when you ask.\""}],"relearn":"Offering to own night feeds and doctor visits fully makes you a co-parent, not a helper waiting for tasks.","persona":"Vikram","source":"i'll own those"},
  {"id":"ep2-1109","cat":"involved-dads","type":"role-play","hook":"A colleague jokes that your leaving on time to bathe your kids means you've 'gone soft' at work.","setup":"Own it lightly:","yourLine":[{"text":"\"I leave on time to be a dad; that's a priority, not a weakness.\"","best":true},{"text":"\"Yeah, I know, I really should stay later like the rest of you.\""}],"relearn":"Saying you leave on time to be a dad frames present fatherhood as a priority you own, not a weakness.","persona":"Vikram","source":"priority not weakness"},
  {"id":"ep2-1110","cat":"involved-dads","type":"role-play","hook":"Your wife hovers and corrects how you swaddle the baby. You want room to learn without a fight.","setup":"Ask for room:","yourLine":[{"text":"\"Let me find my own way with him; I'll get there if you give me space.\"","best":true},{"text":"\"Fine, you do it, clearly I can't get anything right.\""}],"relearn":"Asking for space to find your own way addresses gatekeeping so you can build real confidence as a parent.","persona":"Vikram","source":"my own way"},
  {"id":"ep2-1111","cat":"involved-dads","type":"role-play","hook":"At a wedding, men gather away from the babies. You'd rather stay with your fussing child.","setup":"Stay and own it:","yourLine":[{"text":"\"I'll stay with the little one; settling him is my job tonight too.\"","best":true},{"text":"\"Take him to the women's side, I'll catch you all later.\""}],"relearn":"Staying to settle your child instead of handing him off shows care is a father's job in any room.","persona":"Vikram","source":"stay with him"},
  {"id":"ep2-1112","cat":"involved-dads","type":"role-play","hook":"Your teenager asks why you never learned to cook or plait hair like 'other dads now.' You want to commit.","setup":"Commit to learning:","yourLine":[{"text":"\"You're right; teach me, I want to be that kind of dad for you.\"","best":true},{"text":"\"That's really more your mother's thing, beta.\""}],"relearn":"Telling your child you'll learn their care shows it's never too late to become a more hands-on father.","persona":"Vikram","source":"teach me"},
  {"id":"ep2-1113","cat":"involved-dads","type":"reflect","hook":"Lensy: the bond you build by being hands-on is yours to keep for life. Does that land?","prompt":"What's your take?","options":["It lands","Mine to keep","Worth the time"],"affirm":"The bond a father builds through daily, hands-on care is his own, lifelong, and no one can do it for him.","relearn":"The bond built through hands-on care is a father's own and lifelong; it's claimed by showing up, not delegated.","persona":"Vikram","source":"bond to keep"},
  {"id":"ep2-1114","cat":"involved-dads","type":"reflect","hook":"Lensy: 'helping' makes care sound like her job you assist with. Sit with that word a moment?","prompt":"What do you think?","options":["I see it","Just my word","It's my job too"],"affirm":"When a father 'helps', care still belongs to her; when he owns it, it's simply his job as a parent.","relearn":"Calling care 'helping' keeps it her job; owning it makes care a father's own equal responsibility.","persona":"any","source":"the word helping"},
  {"id":"ep2-1115","cat":"involved-dads","type":"reflect","hook":"Lensy: being there isn't only about money; your time and attention are gifts too. Resonate?","prompt":"How does that sit?","options":["Resonates","Time counts","Not only money"],"affirm":"A father's time, attention and presence are gifts to a child that no amount of provision can replace.","relearn":"A father's presence and attention are gifts money can't replace; providing is part of the job, not all of it.","persona":"Vikram","source":"presence is a gift"},
  {"id":"ep2-1116","cat":"involved-dads","type":"reflect","hook":"Lensy: getting better at care comes from doing it, not from being born for it. Land okay?","prompt":"What's your view?","options":["Lands okay","Practice, not birth","I can learn"],"affirm":"Fathers get good at care the same way anyone does, by practising; it was never a skill reserved for mothers.","relearn":"Skill at care comes from practice, not from being born to it; a father can learn it as well as anyone.","persona":"Vikram","source":"practice not birth"},
  {"id":"ep2-1117","cat":"involved-dads","type":"reflect","hook":"Lensy: every father starts unsure; the first nappy is clumsy for everyone. Comforting?","prompt":"What do you feel?","options":["Comforting","All start unsure","I'll learn it"],"affirm":"Every parent fumbles at first; a father's early clumsiness is the start of skill, not proof he can't do it.","relearn":"Early fumbling is normal for any parent; a father's clumsy first tries are the start of skill, not a verdict.","persona":"Vikram","source":"all start unsure"},
  {"id":"ep2-1118","cat":"involved-dads","type":"reflect","hook":"Lensy: claiming hands-on fatherhood is something you do for yourself, not just for her. Agree?","prompt":"Your take?","options":["I agree","For me too","A gain, not a chore"],"affirm":"Hands-on fatherhood lifts a father's own bond, confidence and joy; claiming it is a gain, not a sacrifice.","relearn":"Involved fatherhood is pro-men: claiming it lifts a father's own bond, confidence and joy, not just hers.","persona":"any","source":"for me too"},
  {"id":"ep2-1119","cat":"involved-dads","type":"reflect","hook":"Lensy: a child who can turn to either parent is steadier. Does that feel true to you?","prompt":"How does it land?","options":["Feels true","Either parent","Steadier kid"],"affirm":"When a child can turn to both parents, not just one, they feel safer and the load is genuinely shared.","relearn":"A child who can turn to either parent feels safer; building that means a father must be soothing, not just present.","persona":"Vikram","source":"either parent"},
  {"id":"ep2-1120","cat":"involved-dads","type":"reflect","hook":"Lensy: 'fun dad, tired mum' isn't really equal. Worth a pause?","prompt":"What do you notice?","options":["Worth a pause","Not equal","Share the dull bits"],"affirm":"Being only the fun parent while she carries the dull, daily load isn't shared parenting; both halves count.","relearn":"Being the fun parent while she carries the daily grind isn't equal; an involved dad shares the unglamorous half too.","persona":"Vikram","source":"fun dad tired mum"},
  {"id":"ep2-1121","cat":"involved-dads","type":"sort","hook":"Sort each line: owning the parenting, or staying a helper who waits to be told?","items":[{"id":"a","text":"Knowing the jab schedule yourself"},{"id":"b","text":"Waiting for a list before you act"},{"id":"c","text":"Taking the night feed without being asked"},{"id":"d","text":"Only doing tasks she hands you"},{"id":"e","text":"Owning the school run end-to-end"},{"id":"f","text":"Asking 'what should I do?' every time"}],"bins":[{"id":"owner","label":"Owning it","valence":"pos"},{"id":"helper","label":"Just helping","valence":"neg"}],"key":{"a":"owner","b":"helper","c":"owner","d":"helper","e":"owner","f":"helper"},"relearn":"Knowing schedules, taking feeds unasked and owning the school run is owning it; waiting for tasks is just helping.","persona":"Vikram","source":"owner vs helper"},
  {"id":"ep2-1122","cat":"involved-dads","type":"sort","hook":"Sort: present, hands-on fathering, or distant 'provider-only' fathering?","items":[{"id":"a","text":"Doing the bedtime routine nightly"},{"id":"b","text":"Seeing the kids only at weekends by choice"},{"id":"c","text":"Knowing your child's friends and worries"},{"id":"d","text":"Leaving all care to mum and grandparents"},{"id":"e","text":"Taking leave to be there at birth"},{"id":"f","text":"Sending money but rarely being home"}],"bins":[{"id":"present","label":"Present","valence":"pos"},{"id":"distant","label":"Distant","valence":"neg"}],"key":{"a":"present","b":"distant","c":"present","d":"distant","e":"present","f":"distant"},"relearn":"Bedtimes, knowing your child's world and being there at birth is present fathering; weekend-only and absent is distant.","persona":"Vikram","source":"present vs distant"},
  {"id":"ep2-1123","cat":"involved-dads","type":"sort","hook":"Sort each comment: a real myth about dads, or a true thing about involved fathers?","items":[{"id":"a","text":"Men can't soothe babies, it's instinct"},{"id":"b","text":"Fathers bond with newborns from day one"},{"id":"c","text":"Nappies are beneath a real man"},{"id":"d","text":"A present father lifts a child's confidence"},{"id":"e","text":"Care is mum's department, not dad's"},{"id":"f","text":"Soothing is a skill any parent can learn"}],"bins":[{"id":"myth","label":"Myth","valence":"neg"},{"id":"true","label":"True","valence":"pos"}],"key":{"a":"myth","b":"true","c":"myth","d":"true","e":"myth","f":"true"},"relearn":"That men can't soothe or that care is mum's job are myths; bonding from day one and learned soothing are true.","persona":"any","source":"myth vs true"},
  {"id":"ep2-1124","cat":"involved-dads","type":"sort","hook":"Sort: speak up and claim it, or quietly let your fatherhood get sidelined?","items":[{"id":"a","text":"\"They're my kids, not babysitting\""},{"id":"b","text":"Laughing along when called a babysitter"},{"id":"c","text":"\"I'll take the clinic visit myself\""},{"id":"d","text":"Letting the nurse ask only mum"},{"id":"e","text":"\"Leave bedtime to me tonight\""},{"id":"f","text":"Going quiet when told care is her job"}],"bins":[{"id":"claim","label":"Claim it","valence":"tell"},{"id":"sidelined","label":"Sidelined","valence":"uhoh"}],"key":{"a":"claim","b":"sidelined","c":"claim","d":"sidelined","e":"claim","f":"sidelined"},"relearn":"Naming 'not babysitting' and taking visits and bedtime claims your fatherhood; staying quiet lets it get sidelined.","persona":"Vikram","source":"claim vs sidelined"},
  {"id":"ep2-1125","cat":"involved-dads","type":"sort","hook":"Sort each barrier a dad meets: a real obstacle to name, or just an excuse to opt out?","items":[{"id":"a","text":"Workplace gives men no real leave"},{"id":"b","text":"\"I earn, so care isn't my job\""},{"id":"c","text":"Partner redoes everything you try"},{"id":"d","text":"\"Babies just don't want dads\""},{"id":"e","text":"No older men modelled hands-on care"},{"id":"f","text":"\"I'm too clumsy, why bother\""}],"bins":[{"id":"real","label":"Real barrier","valence":"uhoh"},{"id":"excuse","label":"Just an excuse","valence":"neg"}],"key":{"a":"real","b":"excuse","c":"real","d":"excuse","e":"real","f":"excuse"},"relearn":"Thin leave, gatekeeping and no role models are real barriers to name; 'I earn' or 'I'm clumsy' are excuses to opt out.","persona":"any","source":"barrier vs excuse"},
  {"id":"ep2-1126","cat":"involved-dads","type":"sort","hook":"Sort: quality engagement that builds a bond, or mere contact that doesn't?","items":[{"id":"a","text":"Listening to your child's day fully"},{"id":"b","text":"On the phone while 'watching' them"},{"id":"c","text":"Reading and playing together nightly"},{"id":"d","text":"In the room but never looking up"},{"id":"e","text":"Handling a tantrum patiently yourself"},{"id":"f","text":"Sitting beside them, both on screens"}],"bins":[{"id":"quality","label":"Real engagement","valence":"pos"},{"id":"contact","label":"Just contact","valence":"neutral"}],"key":{"a":"quality","b":"contact","c":"quality","d":"contact","e":"quality","f":"contact"},"relearn":"Listening, playing and handling tantrums is real engagement; being in the room on a phone is mere contact.","persona":"Vikram","source":"quality vs contact"},
  {"id":"ep2-1127","cat":"involved-dads","type":"sort","hook":"Sort each line a dad might say: owning his share, or pushing care back onto her?","items":[{"id":"a","text":"\"I've got the night feeds this week\""},{"id":"b","text":"\"You're just better with him than me\""},{"id":"c","text":"\"I booked the dentist for both kids\""},{"id":"d","text":"\"Wake me only if you really need to\""},{"id":"e","text":"\"I'll learn his routine myself\""},{"id":"f","text":"\"That's mother's stuff, you do it\""}],"bins":[{"id":"owns","label":"Owns his share","valence":"pos"},{"id":"pushes","label":"Pushes it back","valence":"neg"}],"key":{"a":"owns","b":"pushes","c":"owns","d":"pushes","e":"owns","f":"pushes"},"relearn":"Taking feeds, booking the dentist and learning the routine owns his share; 'you're better' or 'that's mother's stuff' pushes it back.","persona":"Vikram","source":"owns vs pushes"},
  {"id":"ep2-1128","cat":"involved-dads","type":"match","hook":"Match each involved-dad act to what it gives the child.","pairs":[{"left":"Doing the daily care","right":"A secure, real bond"},{"left":"Being emotionally present","right":"Confidence and resilience"},{"left":"Showing up consistently","right":"Trust they can rely on you"},{"left":"Sharing the load with mum","right":"A calmer, less-stretched home"},{"left":"Modelling care as a man","right":"A wider idea of what men do"}],"relearn":"Daily care, presence, consistency, sharing the load and modelling are what an involved father gives his child.","persona":"Vikram","source":"act to gift"},
  {"id":"ep2-1129","cat":"involved-dads","type":"match","hook":"Match each old myth about dads to the truth that replaces it.","pairs":[{"left":"He's just babysitting his own kids","right":"He's parenting; it's his job too"},{"left":"Nurturing isn't a man's role","right":"Men can nurture fully and well"},{"left":"Babies only want their mother","right":"Infants attach to both from birth"},{"left":"Care is beneath a real man","right":"Care is how a father builds a bond"},{"left":"Asking dads to do more is anti-men","right":"Involved fatherhood is pro-men"}],"relearn":"Babysitting becomes parenting, nurturing is a man's role, babies attach to both, care builds bonds, involvement is pro-men.","persona":"any","source":"myth to truth"},
  {"id":"ep2-1130","cat":"involved-dads","type":"match","hook":"Match each barrier a father faces to a way to meet it without opting out.","pairs":[{"left":"Thin or no paternity leave","right":"Take what you can and guard home time"},{"left":"Partner redoing your efforts","right":"Ask kindly for room to learn"},{"left":"Work that erases fatherhood","right":"Protect a daily ritual you keep"},{"left":"No older men modelled care","right":"Be the model your own kids see"},{"left":"\"It's not manly\" pressure","right":"Claim tenderness as good fathering"}],"relearn":"Thin leave, gatekeeping, greedy work, no role models and 'not manly' pressure are each met by claiming your share, not opting out.","persona":"any","source":"barrier to move"},
  {"id":"ep2-1131","cat":"involved-dads","type":"match","hook":"Match each domain a father can own to what owning it actually means.","pairs":[{"left":"Health","right":"Tracking jabs and booking the doctor"},{"left":"Sleep","right":"Owning the bedtime routine and nights"},{"left":"School","right":"Knowing the bags, timings and meetings"},{"left":"Food","right":"Planning and making the kids' meals"},{"left":"Play","right":"Being the one who reads and plays daily"}],"relearn":"Owning a domain like health, sleep, school, food or play means tracking and doing it end-to-end, not when asked.","persona":"Vikram","source":"domain to meaning"},
  {"id":"ep2-1132","cat":"involved-dads","type":"match","hook":"Match each thing a present father does to the gain it brings him.","pairs":[{"left":"Soothing his baby himself","right":"Confidence he can parent"},{"left":"Sharing nights and feeds","right":"A deeper bond with his child"},{"left":"Knowing his child's world","right":"Closeness as they grow"},{"left":"Modelling care openly","right":"A son who respects care work"},{"left":"Claiming hands-on time","right":"Joy he'd otherwise miss"}],"relearn":"Soothing, sharing nights, knowing his child and modelling care give a father confidence, bond, closeness and joy.","persona":"Vikram","source":"act to dad's gain"},
  {"id":"ep2-1133","cat":"involved-dads","type":"match","hook":"Match each phrase to whether it's an involved-dad move or a stay-distant move.","pairs":[{"left":"\"Leave the doctor visit to me\"","right":"Involved: owning a domain"},{"left":"\"Just tell me what to do\"","right":"Distant: staying a helper"},{"left":"\"I'll learn his routine myself\"","right":"Involved: building real skill"},{"left":"\"You're the natural with him\"","right":"Distant: ducking the load"},{"left":"\"Bedtime's mine tonight\"","right":"Involved: sharing the daily care"}],"relearn":"Taking visits, learning routines and owning bedtime is involved; 'tell me what to do' or 'you're the natural' stays distant.","persona":"Vikram","source":"involved vs distant phrase"},
  {"id":"ep2-1134","cat":"involved-dads","type":"match","hook":"Match each setting to the involved-dad action that fits it.","pairs":[{"left":"Newborn weeks at home","right":"Take leave and share the nights"},{"left":"At the child's clinic","right":"Answer the questions yourself"},{"left":"Family lunch teasing","right":"Name it: parenting, not babysitting"},{"left":"Late work pings at bedtime","right":"Protect the bedtime ritual"},{"left":"Partner hovering as you try","right":"Ask for room to learn your way"}],"relearn":"Newborn weeks, the clinic, teasing, work pings and hovering each have an involved-dad move: show up and own it.","persona":"Vikram","source":"setting to action"},
  {"id":"ep2-1135","cat":"involved-dads","type":"spot","hook":"Spot the two lines that keep a father a helper instead of an equal parent.","scene":[{"id":"a","text":"He knows the kids' routines himself","trick":false},{"id":"b","text":"He waits to be told what to do","trick":true},{"id":"c","text":"He owns bedtime without being asked","trick":false},{"id":"d","text":"He only does tasks she hands him","trick":true},{"id":"e","text":"He books the doctor visits himself","trick":false}],"why":"Waiting to be told and only doing handed tasks keep him a helper; an equal parent owns and notices himself.","relearn":"A father stays a helper when he waits to be told and only does handed tasks; owning care himself makes him equal.","persona":"Vikram","source":"helper red flags"},
  {"id":"ep2-1136","cat":"involved-dads","type":"spot","hook":"Spot the two lines that wrongly treat fathering as not a man's job.","scene":[{"id":"a","text":"\"Holding my baby is the best part of my day\"","trick":false},{"id":"b","text":"\"Nappies are beneath a real man\"","trick":true},{"id":"c","text":"\"I take the kids to the doctor too\"","trick":false},{"id":"d","text":"\"Nurturing just isn't a man's thing\"","trick":true},{"id":"e","text":"\"I'll learn his routine myself\"","trick":false}],"why":"'Nappies are beneath a man' and 'nurturing isn't a man's thing' are the myths; care is fully a father's role.","relearn":"Saying care is beneath a man or not a man's thing are myths to catch; nurturing is fully a father's role.","persona":"any","source":"not-a-mans-job myths"},
  {"id":"ep2-1137","cat":"involved-dads","type":"spot","hook":"Spot the two lines that excuse a father opting out of care.","scene":[{"id":"a","text":"\"Work was hard, but I'll still do bath time\"","trick":false},{"id":"b","text":"\"I earn, so the care isn't my job\"","trick":true},{"id":"c","text":"\"Let me take the night feed tonight\"","trick":false},{"id":"d","text":"\"Babies just don't really want dads\"","trick":true},{"id":"e","text":"\"I'll learn what jabs are due\"","trick":false}],"why":"'I earn, so care isn't my job' and 'babies don't want dads' are excuses to opt out; both parents owe the care.","relearn":"'I earn so care isn't mine' and 'babies don't want dads' are opt-out excuses to catch; care is a father's job too.","persona":"Vikram","source":"opt-out excuses"},
  {"id":"ep2-1138","cat":"involved-dads","type":"spot","hook":"Spot the two replies that quietly let a father's care be called 'babysitting'.","scene":[{"id":"a","text":"\"It's not babysitting, they're my kids\"","trick":false},{"id":"b","text":"\"Ha, yes, I'm on babysitting duty today\"","trick":true},{"id":"c","text":"\"I parent them, same as their mother\"","trick":false},{"id":"d","text":"\"She lets me help out now and then\"","trick":true},{"id":"e","text":"\"Minding my own children is just being dad\"","trick":false}],"why":"Calling it babysitting duty and saying 'she lets me help' both frame care as a favour; it's his own job.","relearn":"Accepting 'babysitting' or 'she lets me help' frames care as a favour to catch; it's a father's own responsibility.","persona":"Vikram","source":"babysitting language"},
  {"id":"ep2-1139","cat":"involved-dads","type":"spot","hook":"Spot the two moves that show 'present' on paper but not real engagement.","scene":[{"id":"a","text":"He listens fully to his child's day","trick":false},{"id":"b","text":"He's on his phone while 'minding' them","trick":true},{"id":"c","text":"He reads and plays with them nightly","trick":false},{"id":"d","text":"He's in the room but never looks up","trick":true},{"id":"e","text":"He handles the tantrum patiently himself","trick":false}],"why":"Being on a phone or never looking up is mere contact, not engagement; quality of attention is what builds a bond.","relearn":"Being physically there on a phone or never looking up is contact, not engagement; real attention builds the bond.","persona":"Vikram","source":"contact not engagement"},
  {"id":"ep2-1140","cat":"involved-dads","type":"spot","hook":"Spot the two lines that pressure a dad to stay distant to seem 'manly'.","scene":[{"id":"a","text":"\"Cuddle him all you like, it's good for him\"","trick":false},{"id":"b","text":"\"Holding the baby will make you soft\"","trick":true},{"id":"c","text":"\"Take the leave, be there at the start\"","trick":false},{"id":"d","text":"\"Real men leave the crying to the wife\"","trick":true},{"id":"e","text":"\"Learn his routine, you'll be glad you did\"","trick":false}],"why":"'Holding makes you soft' and 'real men leave crying to the wife' push distance; tenderness is good fathering.","relearn":"'Cuddling makes you soft' and 'real men leave crying to wives' are the pressure to catch; tenderness is strength.","persona":"Vikram","source":"manly distance"},
  {"id":"ep2-1141","cat":"involved-dads","type":"spot","hook":"Spot the two lines that hand the whole mental load back to the mother.","scene":[{"id":"a","text":"\"I track his jabs and sizes myself\"","trick":false},{"id":"b","text":"\"You just remember that stuff better\"","trick":true},{"id":"c","text":"\"I'll plan the week's meals this time\"","trick":false},{"id":"d","text":"\"Make me a list and I'll do it\"","trick":true},{"id":"e","text":"\"I'll own the school bags and timings\"","trick":false}],"why":"'You remember better' and 'make me a list' keep her the manager who notices; sharing means owning the noticing too.","relearn":"'You remember better' and 'make me a list' keep her the manager to catch; a father shares the noticing, not just tasks.","persona":"Vikram","source":"load handed back"},
  {"id":"ep2-1170","cat":"kids-are-watching","type":"strike-rewrite","persona":"Meena","source":"sons see kitchen","hook":"\"My son seeing me in the kitchen and his dad on the sofa won't shape him.\"","myth":{"un":"My son seeing me cook while his dad relaxes won't shape him.","re":"What a boy watches at home becomes his idea of 'normal'; he learns whose job care is by who does it.","why":"Children build their template from the home they grow up in."},"relearn":"What your son sees you both do at home becomes his idea of whose job care is."},
  {"id":"ep2-1171","cat":"kids-are-watching","type":"strike-rewrite","persona":"Priya","source":"daughter expects","hook":"\"If I do all the home work, my daughter will still aim high at her career.\"","myth":{"un":"Doing all the home work myself won't lower what my daughter expects for herself.","re":"A daughter who only sees mum carry the home learns to expect that load on top of any career she builds.","why":"Kids absorb what a 'wife and mother' does from the one they watch."},"relearn":"A daughter learns what she'll be expected to carry from watching who carries it at home."},
  {"id":"ep2-1172","cat":"kids-are-watching","type":"strike-rewrite","persona":"Meena","source":"praise dad rare","hook":"\"Praising my husband loudly when he changes a nappy teaches our kids he's a great dad.\"","myth":{"un":"Praising my husband loudly for changing one nappy teaches the kids he's a great dad.","re":"Cheering a father for routine care teaches kids it's extra and optional for men, not simply his job too.","why":"Kids read what's normal from what gets treated as a favour."},"relearn":"Treating a dad's everyday care as a favour teaches kids it's optional for men."},
  {"id":"ep2-1173","cat":"kids-are-watching","type":"strike-rewrite","persona":"Priya","source":"too young to notice","hook":"\"My kids are too small to notice who cooks, cleans or earns at home.\"","myth":{"un":"My kids are too small to notice who cooks, cleans or earns at home.","re":"Even young children track who does what; the home roles they watch early become the ones they assume are natural.","why":"The earliest model a child sees is the hardest to unlearn later."},"relearn":"Even small children track who does what, and early home roles feel 'natural' to them for life."},
  {"id":"ep2-1174","cat":"kids-are-watching","type":"strike-rewrite","persona":"Meena","source":"dad fun parent","hook":"\"Dad being the fun playtime parent while I handle the rest is a fine split for the kids.\"","myth":{"un":"Dad as the fun playtime parent while I handle the rest is a fine split for the kids.","re":"When kids only see dad play and mum manage, they learn care-work is mum's and dads just visit the fun bits.","why":"Children copy the division of labour they actually watch."},"relearn":"If kids only see dad play and mum manage, they learn care is mum's job and dads just drop in."},
  {"id":"ep2-1175","cat":"kids-are-watching","type":"strike-rewrite","persona":"Priya","source":"weekend modelling","hook":"\"As long as my husband helps on weekends, the kids see a fair home.\"","myth":{"un":"As long as my husband helps on weekends, the kids see a fair home.","re":"Kids watch the daily pattern, not the weekend cameo; a weekday split that's all mum is what they absorb.","why":"The everyday routine, not the occasional one, sets a child's normal."},"relearn":"Kids absorb the daily routine, not the weekend cameo, so weekday sharing is what models fairness."},
  {"id":"ep2-1176","cat":"kids-are-watching","type":"strike-rewrite","persona":"Meena","source":"sons learn respect","hook":"\"A boy learns to respect women from being told to, not from chores at home.\"","myth":{"un":"A boy learns to respect women from being told to, not from chores at home.","re":"A boy who shares cooking and cleaning at home learns women aren't there to serve him, far more than a lecture can.","why":"Respect is learned in the doing, not the telling."},"relearn":"A boy who shares the home work learns women aren't there to serve him, better than any lecture."},
  {"id":"ep2-1177","cat":"kids-are-watching","type":"strike-rewrite","persona":"Priya","source":"grandparents model","hook":"\"My kids see grandparents in old roles, so what we two do at home barely matters.\"","myth":{"un":"With grandparents in old roles around, what we two do at home barely matters to the kids.","re":"Parents are a child's closest, most-watched model; your shared split stands out even amid older patterns.","why":"Kids weight what their own parents do most heavily."},"relearn":"Your kids watch you two most closely; your shared home stands out even amid older family patterns."},
  {"id":"ep2-1178","cat":"kids-are-watching","type":"strike-rewrite","persona":"Meena","source":"care confuses boys","hook":"\"Letting my son rock the baby or fold clothes will make him soft or confused.\"","myth":{"un":"Letting my son rock the baby or fold clothes will make him soft or confused.","re":"A boy who learns to care and run a home grows up capable and confident; care skills don't weaken him.","why":"Life skills strengthen children; they have no gender."},"relearn":"A boy who learns to care and run a home grows up capable and confident, never weakened."},
  {"id":"ep2-1179","cat":"kids-are-watching","type":"strike-rewrite","persona":"Priya","source":"talk vs do gap","hook":"\"We tell our kids partners are equal, so what they see us do is a smaller detail.\"","myth":{"un":"We tell our kids partners are equal, so what they see us do is a smaller detail.","re":"When the words say equal but the home doesn't, kids believe what they watch; the gap teaches the talk is just talk.","why":"A child trusts the lived example over the spoken one."},"relearn":"When your words say equal but the home doesn't, kids believe what they see, not what they hear."},
  {"id":"ep2-1180","cat":"kids-are-watching","type":"strike-rewrite","persona":"Meena","source":"break my own cycle","hook":"\"I grew up with an unequal home, so my kids are bound to repeat the same pattern.\"","myth":{"un":"I grew up in an unequal home, so my kids are bound to repeat the same pattern.","re":"You can break what you inherited; a shared home this generation gives your kids a new normal to carry forward.","why":"Modelling change is how the intergenerational cycle ends."},"relearn":"You can break what you inherited; a shared home now gives your kids a new normal to carry forward."},
  {"id":"ep2-1181","cat":"kids-are-watching","type":"sort","persona":"Meena","source":"what son absorbs","hook":"Sort: a son watching this home learns care is shared, or learns care isn't his job?","items":[{"id":"a","text":"Papa packs the school tiffin most mornings"},{"id":"b","text":"Only Mummy is ever called for a sick child"},{"id":"c","text":"Both parents wash up after dinner"},{"id":"d","text":"Dad says 'cooking is your mother's department'"},{"id":"e","text":"Papa helps with homework and bedtime"},{"id":"f","text":"Boys excused from chores, girls aren't"}],"bins":[{"id":"shared","label":"Care is shared","valence":"pos"},{"id":"notmine","label":"Care isn't his job","valence":"neg"}],"key":{"a":"shared","b":"notmine","c":"shared","d":"notmine","e":"shared","f":"notmine"},"relearn":"A son learns care is shared from a dad who cooks and parents; he learns it isn't his from mum-only homes."},
  {"id":"ep2-1182","cat":"kids-are-watching","type":"sort","persona":"Priya","source":"models or not","hook":"Sort: does this moment model equality for the kids, or quietly undermine it?","items":[{"id":"a","text":"Parents decide the budget together"},{"id":"b","text":"Dad waits to be 'asked' before he helps"},{"id":"c","text":"Mum has the final say on her own career"},{"id":"d","text":"Kids hear 'real men don't do dishes'"},{"id":"e","text":"Both parents attend the school meeting"},{"id":"f","text":"Daughter told to serve her brother first"}],"bins":[{"id":"models","label":"Models equality","valence":"pos"},{"id":"undermines","label":"Undermines it","valence":"neg"}],"key":{"a":"models","b":"undermines","c":"models","d":"undermines","e":"models","f":"undermines"},"relearn":"Joint decisions and both parents showing up model equality; gendered jabs undermine it."},
  {"id":"ep2-1183","cat":"kids-are-watching","type":"sort","persona":"Meena","source":"daily vs cameo","hook":"Sort: which of these does a child actually watch every day, and which is just an occasional cameo?","items":[{"id":"a","text":"Who gets up for the early school rush daily"},{"id":"b","text":"Who plans the week's meals and groceries"},{"id":"c","text":"Dad's once-a-month trip to the park"},{"id":"d","text":"Who notices when uniforms need washing"},{"id":"e","text":"A grand 'helping out' on a festival day"},{"id":"f","text":"Who keeps track of homework each evening"}],"bins":[{"id":"daily","label":"Watched daily","valence":"neutral"},{"id":"cameo","label":"Occasional cameo","valence":"uhoh"}],"key":{"a":"daily","b":"daily","c":"cameo","d":"daily","e":"cameo","f":"daily"},"relearn":"Kids absorb the daily routine of care, not the occasional cameo, so the everyday split is what they learn."},
  {"id":"ep2-1184","cat":"kids-are-watching","type":"sort","persona":"Priya","source":"chore gendered","hook":"Sort: which teaches kids chores have no gender, and which teaches the old divide?","items":[{"id":"a","text":"Son and daughter both learn to cook dal"},{"id":"b","text":"Only the girl is taught to keep house"},{"id":"c","text":"Brother and sister share the sweeping"},{"id":"d","text":"Boy handed money, girl handed a broom"},{"id":"e","text":"Both kids fold their own clothes"},{"id":"f","text":"Sister serves, brother is served"}],"bins":[{"id":"nogender","label":"Chores have no gender","valence":"pos"},{"id":"olddivide","label":"Teaches the old divide","valence":"neg"}],"key":{"a":"nogender","b":"olddivide","c":"nogender","d":"olddivide","e":"nogender","f":"olddivide"},"relearn":"Same chores for sons and daughters teach care has no gender; splitting by sex teaches the divide."},
  {"id":"ep2-1185","cat":"kids-are-watching","type":"sort","persona":"Meena","source":"present dad","hook":"Sort: which shows a child dads can be tender, and which says dads keep their distance?","items":[{"id":"a","text":"Papa cuddles the toddler when she cries"},{"id":"b","text":"'Go to your mother' when a child is upset"},{"id":"c","text":"Dad sits and listens to a kid's bad day"},{"id":"d","text":"'Ask your mum about feelings,' says dad"},{"id":"e","text":"Papa sings the baby to sleep"},{"id":"f","text":"Dad never does the soothing or soft stuff"}],"bins":[{"id":"tender","label":"Dads can be tender","valence":"pos"},{"id":"distant","label":"Dads keep distance","valence":"neg"}],"key":{"a":"tender","b":"distant","c":"tender","d":"distant","e":"tender","f":"distant"},"relearn":"A dad who soothes shows kids men can be tender; pushing soft stuff to mum teaches distance."},
  {"id":"ep2-1186","cat":"kids-are-watching","type":"sort","persona":"Priya","source":"counter or cede","hook":"Sort: when relatives push old roles on your kids, which keeps your home the lesson?","items":[{"id":"a","text":"Gently say 'in our home, both of us cook'"},{"id":"b","text":"Stay silent so the gendered remark stands"},{"id":"c","text":"Show the kids dad doing it right then"},{"id":"d","text":"Let 'that's girls' work' go unchallenged"},{"id":"e","text":"Repeat your shared split out loud, kindly"},{"id":"f","text":"Agree quietly just to avoid a scene"}],"bins":[{"id":"holds","label":"Keeps home the lesson","valence":"tell"},{"id":"cedes","label":"Lets the script win","valence":"neg"}],"key":{"a":"holds","b":"cedes","c":"holds","d":"cedes","e":"holds","f":"cedes"},"relearn":"Gently naming your shared split keeps home the lesson; silence lets the old script teach instead."},
  {"id":"ep2-1187","cat":"kids-are-watching","type":"sort","persona":"any","source":"belief planted","hook":"Sort: which homes teach a child care is everyone's, and which that care is women's only?","items":[{"id":"a","text":"Both parents on hospital duty when a kid is ill"},{"id":"b","text":"Father has never made a meal at home"},{"id":"c","text":"Both parents do nights with a new baby"},{"id":"d","text":"Mum alone runs every birthday and illness"},{"id":"e","text":"Papa irons the school uniforms"},{"id":"f","text":"Care talk is always aimed at the women"}],"bins":[{"id":"everyone","label":"Care is everyone's","valence":"pos"},{"id":"womenonly","label":"Care is women's only","valence":"neg"}],"key":{"a":"everyone","b":"womenonly","c":"everyone","d":"womenonly","e":"everyone","f":"womenonly"},"relearn":"Kids learn care is everyone's from both parents sharing it, and women's from mum-only homes."},
  {"id":"ep2-1188","cat":"kids-are-watching","type":"sort","persona":"Meena","source":"mental load seen","hook":"Sort: which lets kids see planning is shared, and which hides it as mum's invisible work?","items":[{"id":"a","text":"Both parents fill the family calendar"},{"id":"b","text":"Only mum remembers every vaccine"},{"id":"c","text":"Dad openly tracks fees and supplies"},{"id":"d","text":"Father asks 'what do I buy?' every time"},{"id":"e","text":"Parents plan the school year together"},{"id":"f","text":"Mum carries the to-do list in her head"}],"bins":[{"id":"shared","label":"Planning is shared","valence":"pos"},{"id":"hidden","label":"Mum's invisible work","valence":"uhoh"}],"key":{"a":"shared","b":"hidden","c":"shared","d":"hidden","e":"shared","f":"hidden"},"relearn":"Kids see planning as shared when both parents track it openly; mum-only remembering hides it."},
  {"id":"ep2-1189","cat":"kids-are-watching","type":"branch","persona":"Priya","source":"son refuses chore","hook":"Your son won't clear his plate: 'that's didi's job.' What do you do?","options":[{"text":"Have him clear it, noting you and dad do it too","consequence":"He learns the job is everyone's, by seeing it.","outcome":"model","best":true},{"text":"Let his sister do it to avoid the fuss","consequence":"He learns the divide was right, and so does she."},{"text":"Tell him equality matters, but clear it yourself","consequence":"Words against the home he watches don't stick."}],"debrief":"When a child voices the old divide, change what both parents do, not just what you say.","relearn":"Reteach by having both parents share the job in front of him."},
  {"id":"ep2-1190","cat":"kids-are-watching","type":"branch","persona":"Priya","source":"dad sofa","hook":"You're clearing up while husband and kids watch TV. You want a fairer picture for them.","options":[{"text":"Ask him to split the clean-up so kids see both of you","consequence":"The kids watch care being shared, every night.","outcome":"share","best":true},{"text":"Do it all yourself and resent it silently","consequence":"The kids keep watching mum-only care as normal."},{"text":"Snap that nobody helps, in front of the kids","consequence":"They learn fairness is a fight, not a default."}],"debrief":"Sharing the clean-up where kids see it teaches more than doing it alone.","relearn":"Splitting the clean-up where kids can see it models shared care."},
  {"id":"ep2-1191","cat":"kids-are-watching","type":"branch","persona":"Meena","source":"daughter quit","hook":"Your daughter says 'I'll stop working when I have kids, like mums do.' You say?","options":[{"text":"Show her dad and you both kept careers and care","consequence":"She sees parenthood need not cost only her.","outcome":"show","best":true},{"text":"Agree it's just what mothers have to do","consequence":"She accepts the load as hers alone, in advance."},{"text":"Say don't think that way, but change nothing","consequence":"Your unchanged home outweighs the words."}],"debrief":"A daughter rethinks the default by watching both parents share care and work.","relearn":"A daughter expects a fair future when both parents share care and their own lives."},
  {"id":"ep2-1192","cat":"kids-are-watching","type":"branch","persona":"Priya","source":"praise dad","hook":"A relative gushes 'what a husband, he even feeds the baby!' before your kids. Your reply?","options":[{"text":"Warmly note feeding his own child is just his job","consequence":"Kids hear care is a dad's duty, not a bonus.","outcome":"reframe","best":true},{"text":"Smile and agree he's being extra helpful","consequence":"Kids learn a dad's care is a favour, not a given."},{"text":"Brush it off and say nothing","consequence":"The 'great for helping' frame stands."}],"debrief":"Reframing a dad's care as his own job, not a favour, corrects what kids just heard.","relearn":"Naming a dad's care as his own duty teaches kids care is shared, not a favour."},
  {"id":"ep2-1193","cat":"kids-are-watching","type":"branch","persona":"Meena","source":"play house","hook":"Your kids play 'house' with the boy 'at office' and the girl 'cooking'. What now?","options":[{"text":"Join in and have the 'dad' doll cook, the 'mum' work","consequence":"Their play world widens to a fairer home.","outcome":"widen","best":true},{"text":"Stop the game and lecture them on equality","consequence":"The lecture fades; the watched home shaped it."},{"text":"Find it cute and leave the script as is","consequence":"The gendered script they copied stays put."}],"debrief":"Kids' play mirrors the home they watch; widen it by rebalancing what you do.","relearn":"Children's play copies the home they watch; reshape it by changing your split."},
  {"id":"ep2-1194","cat":"kids-are-watching","type":"branch","persona":"Priya","source":"dad distance","hook":"Your child runs crying to you; husband says 'go to mama, I'm no good at it.' What helps?","options":[{"text":"Hand the moment to him so the child sees dad comfort","consequence":"Kids learn fathers soothe, not just mums.","outcome":"share","best":true},{"text":"Take over every time so it's easier","consequence":"Kids learn comfort is mum's department only."},{"text":"Say he should help, but always step in first","consequence":"Your stepping-in is the lesson, not your words."}],"debrief":"Letting dad comfort, even clumsily, teaches kids that fathers are tender too.","relearn":"When kids watch dad soothe, they learn tenderness is for fathers too."},
  {"id":"ep2-1195","cat":"kids-are-watching","type":"branch","persona":"Meena","source":"mocks dad","hook":"Your son giggles 'Papa's doing the washing, that's funny!' How do you shift it?","options":[{"text":"Calmly say it's normal, both parents run the home","consequence":"He recalibrates what's ordinary for a dad.","outcome":"normalise","best":true},{"text":"Laugh along so it stays a joke","consequence":"He keeps filing a caring dad under 'funny, unusual'."},{"text":"Scold him sharply for laughing","consequence":"He learns the topic is tense, not that it's normal."}],"debrief":"Treating a caring dad as ordinary, not a punchline, resets what your son thinks is normal.","relearn":"Naming a dad's care as completely normal stops a child filing it as funny."},
  {"id":"ep2-1196","cat":"kids-are-watching","type":"branch","persona":"Priya","source":"women serve","hook":"Guests arrive; kids watch the women rush to serve while the men sit. Your move?","options":[{"text":"Have you and your husband host and serve together","consequence":"Kids watch hosting shared across genders.","outcome":"share","best":true},{"text":"Send your daughter to help serve, not your son","consequence":"Kids learn serving guests is a girl's duty."},{"text":"Let the old pattern run to keep the peace","consequence":"The watched scene teaches the divide again."}],"debrief":"Sharing the hosting before the kids, men included, rewrites the gendered scene.","relearn":"When kids watch both parents host and serve, they learn hosting has no gender."},
  {"id":"ep2-1197","cat":"kids-are-watching","type":"reflect","persona":"any","source":"first textbook","hook":"Lensy: your home is the first 'textbook' on men and women your child ever reads. Sit with that?","prompt":"What comes up for you?","options":["It lands","First textbook","I'll be mindful"],"affirm":"A child's first lesson on what men and women do comes from the home they watch, long before any school.","relearn":"Home is a child's first textbook on gender roles; what they watch there is read as the truth."},
  {"id":"ep2-1198","cat":"kids-are-watching","type":"reflect","persona":"Priya","source":"son future wife","hook":"Lensy: the way your son sees his dad treat you is the blueprint he'll carry into his own home. Feel it?","prompt":"What's your take?","options":["I feel it","A blueprint","Worth getting right"],"affirm":"A son watches how his father shares and respects at home, and carries that blueprint into his own family.","relearn":"How a son watches his dad share and respect at home becomes the blueprint for his own future family."},
  {"id":"ep2-1199","cat":"kids-are-watching","type":"reflect","persona":"any","source":"silence teaches too","hook":"Lensy: even on a quiet day, who does what at home is teaching your kids something. Notice that?","prompt":"What do you think?","options":["I notice","Always teaching","Even quietly"],"affirm":"There's no neutral day; the everyday split of care your kids watch is teaching them, whether you mean it or not.","relearn":"There is no off day; the daily split of care your kids watch is always teaching them what's normal."},
  {"id":"ep2-1200","cat":"kids-are-watching","type":"reflect","persona":"Meena","source":"daughter whole person","hook":"Lensy: your daughter learns whether a mum can be a whole person, with her own work and rest, by watching you. Big?","prompt":"What's your take?","options":["Big","A whole person","She's watching"],"affirm":"A daughter learns a mother can have her own work, rest and dreams by watching one who keeps them.","relearn":"A daughter learns a mum can be a whole person, with her own life, by watching one who keeps hers."},
  {"id":"ep2-1201","cat":"kids-are-watching","type":"reflect","persona":"any","source":"copy not comply","hook":"Lensy: your kids will copy what they see you both do, not what you tell them to do. Sit with that?","prompt":"What comes up?","options":["It's true","Copy, not comply","Noted"],"affirm":"Children copy the example they watch far more reliably than they follow the instructions they're given.","relearn":"Kids copy what they watch you do far more than they obey what they're told; the example is the lesson."},
  {"id":"ep2-1202","cat":"kids-are-watching","type":"reflect","persona":"any","source":"both parents capable","hook":"Lensy: when kids see both parents handle a fever, a tantrum and a tiffin, they learn either parent can. Worth it?","prompt":"What's your take?","options":["Worth it","Either parent can","Good lesson"],"affirm":"When kids watch both parents handle the messy, hard care, they learn competence in care isn't a gender.","relearn":"Kids who watch both parents handle the hard care learn either parent is capable; care isn't a gender."},
  {"id":"ep2-1203","cat":"kids-are-watching","type":"reflect","persona":"Priya","source":"new family normal","hook":"Lensy: you get to decide what 'a normal family' looks like to your kids, starting with today. Powerful?","prompt":"What do you feel?","options":["Powerful","Starting today","It's ours to set"],"affirm":"What 'normal' looks like to your children is being set by what they watch at home, and you help shape it.","relearn":"You help set what 'a normal family' means to your kids by what they watch you both do at home."},
  {"id":"ep2-1204","cat":"kids-are-watching","type":"reflect","persona":"Meena","source":"chain ends here","hook":"Lensy: the unequal split you may have grown up in can stop with you, so your kids start fresh. Sit with it?","prompt":"What's your take?","options":["It can stop here","A fresh start","I'll try"],"affirm":"The home pattern you inherited can end with your generation; a shared home gives your kids a new starting point.","relearn":"An inherited unequal split can stop with you; a shared home hands your kids a fresh starting point."},
  {"id":"ep2-1205","cat":"kids-are-watching","type":"reflect","persona":"any","source":"small eyes watching","hook":"Lensy: the small eyes in your home clock who's tired, who rests, who's always 'on'. Did you realise?","prompt":"What comes up?","options":["I realise now","Small eyes","They clock it"],"affirm":"Children quietly notice who is always 'on' and who gets to rest, and they learn whose comfort counts.","relearn":"Kids quietly notice who's always 'on' and who rests, learning whose comfort and time are treated as theirs."},
  {"id":"ep2-1206","cat":"kids-are-watching","type":"reflect","persona":"any","source":"sons gain too","hook":"Lensy: a boy who learns to cook, care and clean grows up able to run his own life, not just lucky to find a wife. Yes?","prompt":"What's your take?","options":["Yes","He gains too","A gift to him"],"affirm":"Teaching a son to cook, care and keep house is a gift to him; he grows up able to run his own life.","relearn":"A son taught to cook, care and clean gains independence; the skills serve him, they don't weaken him."},
  {"id":"ep2-1207","cat":"kids-are-watching","type":"reflect","persona":"Priya","source":"watch then expect","hook":"Lensy: the home your kids watch today quietly sets what they'll expect from a partner tomorrow. Big thought?","prompt":"What do you feel?","options":["Big thought","Watch then expect","Long reach"],"affirm":"What children watch at home becomes the standard they'll expect from, and bring to, their own partnerships.","relearn":"The home kids watch now sets what they'll expect from a partner, and what they'll offer, as adults."},
  {"id":"ep2-1208","cat":"kids-are-watching","type":"match","persona":"any","source":"home to belief","hook":"Match a home a child watches to the belief it quietly plants.","pairs":[{"left":"Papa cooks dinner on weeknights","right":"A kitchen belongs to everyone"},{"left":"Both parents at the doctor visit","right":"Caring for a sick child is a shared duty"},{"left":"Mum keeps her own job and rest","right":"A mother is a full person too"},{"left":"Dad comforts a crying toddler","right":"Fathers can be gentle and present"},{"left":"Decisions made by both together","right":"Partners are equals, not boss and helper"}],"relearn":"Each home pattern a child watches plants a belief about who cooks, who cares, and who counts as an equal."},
  {"id":"ep2-1209","cat":"kids-are-watching","type":"match","persona":"any","source":"unequal to lesson","hook":"Match an unequal home pattern to the lesson a watching child takes from it.","pairs":[{"left":"Only mum ever cooks and cleans","right":"Housework is a woman's job"},{"left":"Dad never changes a nappy","right":"Babies are not a father's concern"},{"left":"Sister serves, brother is served","right":"Girls exist to wait on boys"},{"left":"Dad praised loudly for any care","right":"A father's care is a rare favour"},{"left":"Mum's needs always come last","right":"A mother's own comfort doesn't matter"}],"relearn":"Each unequal pattern a child watches teaches a lesson about whose work care is and whose needs come last."},
  {"id":"ep2-1210","cat":"kids-are-watching","type":"match","persona":"Priya","source":"who does, who learns","hook":"Match what a child sees a parent do to who they grow up believing should do it.","pairs":[{"left":"Papa packs school bags each morning","right":"Either parent can run the school routine"},{"left":"Both parents track fees and forms","right":"Remembering kid-stuff isn't only mum's"},{"left":"Dad nurses a sick child overnight","right":"Nights with kids are a shared job"},{"left":"Parents split the festival cooking","right":"Feeding the family isn't gendered"},{"left":"Both attend sports day","right":"Showing up for kids is for both"}],"relearn":"What a child watches a parent do becomes who they believe should do it."},
  {"id":"ep2-1211","cat":"kids-are-watching","type":"match","persona":"any","source":"reframe lines","hook":"Match a thing your child says to the reframe that reteaches them in the moment.","pairs":[{"left":"'Cooking is only for mummies'","right":"'See? Papa cooks for us too'"},{"left":"'Boys don't cry'","right":"'Everyone has big feelings, even Papa'"},{"left":"'Cleaning is a girl's job'","right":"'In our home, all of us tidy up'"},{"left":"'Babies need only their mum'","right":"'Papa feeds and rocks you as well'"},{"left":"'Dad earns, mum does the rest'","right":"'We both earn and we both care'"}],"relearn":"A gentle reframe in the moment, backed by what the child sees you do, reteaches what they just assumed."},
  {"id":"ep2-1212","cat":"kids-are-watching","type":"match","persona":"any","source":"shared home gains","hook":"Match a shared-home habit to the strength it builds in a watching child.","pairs":[{"left":"A son taught to cook and clean","right":"Grows up able to run his own home"},{"left":"A daughter who sees mum work","right":"Aims high without guilt"},{"left":"Kids watching parents share","right":"Expect equality in their own homes"},{"left":"A boy watching dad be tender","right":"Learns to name his feelings safely"},{"left":"Children seeing joint decisions","right":"Learn to listen and decide fairly"}],"relearn":"Every shared-home habit a child watches builds a real strength they carry into adulthood."},
  {"id":"ep2-1213","cat":"kids-are-watching","type":"match","persona":"Meena","source":"cycle break","hook":"Match a thing you change at home to the cycle it helps your kids break.","pairs":[{"left":"Dad starts owning the night feeds","right":"Care won't skip the next men"},{"left":"Sons given the same chores as girls","right":"The chore divide ends with your kids"},{"left":"Mum stops carrying the load alone","right":"Daughters won't assume it's theirs"},{"left":"Both parents plan the week openly","right":"The mental load stops being invisible"},{"left":"You name a relative's old script","right":"Kids see the old norm can be questioned"}],"relearn":"Each thing you change at home helps your kids break a piece of the inherited cycle."},
  {"id":"ep2-1214","cat":"kids-are-watching","type":"match","persona":"any","source":"see vs hear","hook":"Match what parents often say to kids with what those kids learn from watching.","pairs":[{"left":"'We treat each other as equals'","right":"Learned only if the home shows it"},{"left":"'Respect women, beta'","right":"Sunk in when dad shares the work"},{"left":"'Your father loves you'","right":"Believed when dad is present, not just earning"},{"left":"'Help your mother out'","right":"Heard as 'it's her job, you assist'"},{"left":"'Both parents matter equally'","right":"Real when both show up, not just one"}],"relearn":"Children learn from the home they watch, not the lines they're told; words land only if the example backs them."},
  {"id":"ep2-1215","cat":"kids-are-watching","type":"match","persona":"any","source":"task to shared owner","hook":"Match a daily care task to how a shared home teaches kids it gets owned.","pairs":[{"left":"The morning school rush","right":"Whoever's free leads it, not always mum"},{"left":"A child's doctor appointment","right":"Either parent books and takes them"},{"left":"Helping with homework","right":"Both parents take turns through the week"},{"left":"Soothing a midnight nightmare","right":"Whichever parent the child reaches for"},{"left":"Remembering a friend's birthday gift","right":"Tracked by both, not one parent's head"}],"relearn":"A shared home shows kids each care task is owned by whoever's free, not defaulted to one parent."},
  {"id":"ep2-1216","cat":"kids-are-watching","type":"spot","persona":"Meena","source":"two old-divide signals","hook":"Spot the two moments that quietly teach your kids the old gender divide.","scene":[{"id":"a","text":"Both parents wash up together after dinner","trick":false},{"id":"b","text":"Daughter told to serve her brother first","trick":true},{"id":"c","text":"Papa helps with homework at the table","trick":false},{"id":"d","text":"'Cooking is your mother's job,' dad tells the son","trick":true},{"id":"e","text":"Mum and dad plan the school week jointly","trick":false}],"why":"Telling a daughter to serve her brother and calling cooking 'mum's job' teach kids the old, gendered divide.","relearn":"Kids learn the old divide from gendered serving rules and 'that's mum's job' lines, not from shared care."},
  {"id":"ep2-1217","cat":"kids-are-watching","type":"spot","persona":"Priya","source":"two helper-frame slips","hook":"Spot the two lines that teach kids a dad's care is just 'helping mum', not his own job.","scene":[{"id":"a","text":"'Papa, can you babysit while I cook?'","trick":true},{"id":"b","text":"'Papa's taking you to the doctor today'","trick":false},{"id":"c","text":"'Look how he helps me out with the kids!'","trick":true},{"id":"d","text":"'Both of us are putting you to bed tonight'","trick":false},{"id":"e","text":"'Papa packed your tiffin this morning'","trick":false}],"why":"Calling a dad's time with his own kids 'babysitting' or 'helping me' teaches kids care is mum's, dad just assists.","relearn":"'Babysitting' and 'helping me' frame a dad's care as a favour; kids learn it's optional for men."},
  {"id":"ep2-1218","cat":"kids-are-watching","type":"spot","persona":"Meena","source":"two distance signals","hook":"Spot the two moments that teach kids fathers keep an emotional distance.","scene":[{"id":"a","text":"Papa hugs the toddler after a fall","trick":false},{"id":"b","text":"'Go cry to your mother, I can't deal with this'","trick":true},{"id":"c","text":"Dad sits and hears out a kid's hard day","trick":false},{"id":"d","text":"'Feelings are a mum thing, ask her,' says dad","trick":true},{"id":"e","text":"Papa sings the baby back to sleep","trick":false}],"why":"Pushing every upset and feeling to mum teaches kids that fathers stay distant from the soft, tender side of care.","relearn":"Sending all comfort and feelings to mum teaches kids dads keep distant; a soothing dad teaches the opposite."},
  {"id":"ep2-1219","cat":"kids-are-watching","type":"spot","persona":"Priya","source":"two gendered chore slips","hook":"Spot the two moments that teach kids chores come with a gender.","scene":[{"id":"a","text":"Son and daughter both learn to make tea","trick":false},{"id":"b","text":"Boy handed pocket money, girl handed a broom","trick":true},{"id":"c","text":"Both kids fold their own clothes","trick":false},{"id":"d","text":"'Sweeping isn't for boys,' the son is told","trick":true},{"id":"e","text":"Brother and sister share the washing-up","trick":false}],"why":"Handing the broom to the girl and excusing the boy from sweeping teach kids that chores are split by gender.","relearn":"Splitting chores by sex teaches kids housework has a gender; the same tasks for all teach it doesn't."},
  {"id":"ep2-1220","cat":"kids-are-watching","type":"spot","persona":"any","source":"two undermining lines","hook":"Spot the two remarks that quietly undermine the equality your kids are watching for.","scene":[{"id":"a","text":"'We decided the budget together, kids'","trick":false},{"id":"b","text":"'Real men don't do dishes,' jokes dad","trick":true},{"id":"c","text":"'Both of us will be at your match'","trick":false},{"id":"d","text":"'Your mum's the boss of all this kid stuff'","trick":true},{"id":"e","text":"'Papa and I both cooked tonight'","trick":false}],"why":"'Real men don't do dishes' and 'mum's the boss of kid stuff' teach kids care is women's and men opt out.","relearn":"Throwaway lines that brand care as women's work undermine the equality kids are watching you live."},
  {"id":"ep2-1221","cat":"kids-are-watching","type":"spot","persona":"Priya","source":"two daughter-limiting","hook":"Spot the two moments that teach a daughter to shrink her own future.","scene":[{"id":"a","text":"Mum keeps her job and her hobbies","trick":false},{"id":"b","text":"'Learn to cook, that's what a wife needs'","trick":true},{"id":"c","text":"Parents cheer her science project","trick":false},{"id":"d","text":"'No point studying too much, you'll marry'","trick":true},{"id":"e","text":"Dad helps her with her maths homework","trick":false}],"why":"Telling a girl her future is cooking and that study is pointless once she marries teaches her to shrink her own life.","relearn":"Lines that reduce a daughter's future to marriage and housework teach her to expect less; her watching takes it in."},
  {"id":"ep2-1222","cat":"kids-are-watching","type":"spot","persona":"Meena","source":"two invisible-load signals","hook":"Spot the two moments that teach kids the planning is mum's invisible job, not shared.","scene":[{"id":"a","text":"Both parents fill the family calendar","trick":false},{"id":"b","text":"'Ask your mother, she knows the schedule'","trick":true},{"id":"c","text":"Dad openly tracks the kids' vaccines","trick":false},{"id":"d","text":"'Papa, what do I need to buy?' every time","trick":true},{"id":"e","text":"Parents plan the school year together","trick":false}],"why":"Defaulting every plan and reminder to mum teaches kids the remembering is hers alone, an unshared load.","relearn":"When dad always sends kids to mum for plans, they learn the mental load is mum's invisible job."},
  {"id":"ep2-1223","cat":"kids-are-watching","type":"role-play","persona":"Priya","source":"son cooking is girls","hook":"Your son announces 'cooking is for girls' at dinner, with his little sister listening. Reframe it warmly.","setup":"What do you say?","yourLine":[{"text":"\"Cooking's for everyone, beta. Papa makes the best omelette in this house, remember?\"","best":true},{"text":"\"Don't say silly things,\" and you change the topic.\""}],"relearn":"Naming a dad who cooks, in the moment your son assumes otherwise, reteaches both kids that cooking has no gender."},
  {"id":"ep2-1224","cat":"kids-are-watching","type":"role-play","persona":"Meena","source":"daughter quit work","hook":"Your daughter says 'mums stop working once they have a baby, na?' You want to widen what she pictures.","setup":"How do you answer?","yourLine":[{"text":"\"Some do, some don't. Papa and I both worked and cared for you; you'll choose your own way.\"","best":true},{"text":"\"Yes, that's how it usually goes for mothers.\""}],"relearn":"Showing a daughter that both parents worked and cared widens what she believes a mother's life can hold."},
  {"id":"ep2-1225","cat":"kids-are-watching","type":"role-play","persona":"Priya","source":"son mocks dad washing","hook":"Your son laughs at his dad doing laundry: 'that's a funny job for Papa!' Set the record straight, gently.","setup":"What do you say?","yourLine":[{"text":"\"Nothing funny about it, beta. Running our home is both our job, always has been.\"","best":true},{"text":"\"Ha, yes, your dad's quite the housewife!\""}],"relearn":"Naming home-running as normal for both parents stops a child filing a caring dad as funny or unusual."},
  {"id":"ep2-1226","cat":"kids-are-watching","type":"role-play","persona":"Meena","source":"son wont help sister can","hook":"Your son refuses to wipe the table: 'let didi do it, that's girls' work.' Both kids are watching you respond.","setup":"What do you say?","yourLine":[{"text":"\"In our home, table's whoever's turn it is, and tonight it's yours. Papa wiped it yesterday.\"","best":true},{"text":"\"Fine, your sister can do it this once.\""}],"relearn":"Holding a son to a fair turn, and naming dad's turn too, teaches both kids chores aren't a girl's job."},
  {"id":"ep2-1227","cat":"kids-are-watching","type":"role-play","persona":"Priya","source":"relative dad helps so much","hook":"A relative tells your kids 'you're lucky, your papa helps your mummy so much!' Reframe it for the kids' ears.","setup":"What do you say?","yourLine":[{"text":"\"He's not helping me, he's parenting his own kids, same as I am. That's just how we both do it.\"","best":true},{"text":"\"Yes, we're so lucky he pitches in when he can.\""}],"relearn":"Reframing 'helping mum' as a dad parenting his own kids teaches them care is shared, not a man's favour."},
  {"id":"ep2-1228","cat":"kids-are-watching","type":"role-play","persona":"Meena","source":"son boys dont cry","hook":"Your son tells his younger brother 'boys don't cry, only girls do.' You want to reframe it for both of them.","setup":"What do you say?","yourLine":[{"text":"\"Everyone cries, beta, even Papa and me. Big feelings aren't a boy or girl thing.\"","best":true},{"text":"\"Well, try to be a brave boy anyway, hmm?\""}],"relearn":"Naming that everyone, dad included, has big feelings reteaches kids that emotions aren't split by gender."},
  {"id":"ep2-1229","cat":"kids-are-watching","type":"role-play","persona":"Priya","source":"daughter serve brother","hook":"At a meal your child asks 'why does didi always serve bhaiya?' You want to answer so the habit shifts.","setup":"What do you say?","yourLine":[{"text":"\"Good question, she shouldn't have to. From now we all serve ourselves and each other, turn by turn.\"","best":true},{"text":"\"That's just how it's always been done, beta.\""}],"relearn":"Naming the unfair serving habit and sharing it out reteaches kids that no child exists to wait on another."},
  {"id":"ep2-990","cat":"parental-mental-load","type":"strike-rewrite","hook":"\"I help a lot, so the planning side is naturally hers to hold.\"","myth":{"un":"I help a lot, so the planning side is naturally hers to hold.","re":"The planning isn't naturally anyone's; whoever ends up holding it just got handed it, and either parent can own it.","why":"Defaults feel natural but are just habits."},"relearn":"The planning isn't naturally one parent's; it got defaulted to them, and either parent can take a real share.","persona":"Vikram","source":"not naturally hers"},
  {"id":"ep2-991","cat":"parental-mental-load","type":"strike-rewrite","hook":"\"If nothing's been forgotten, the load must be fairly shared.\"","myth":{"un":"If nothing's been forgotten, the load must be fairly shared.","re":"Nothing being forgotten often means one parent is silently carrying all the tracking; smooth doesn't mean shared.","why":"A smooth home can hide one exhausted manager."},"relearn":"A home where nothing slips can still rest on one parent carrying all the tracking; smooth isn't the same as shared.","persona":"Divya","source":"smooth not shared"},
  {"id":"ep2-992","cat":"parental-mental-load","type":"strike-rewrite","hook":"\"Worrying about the kids at 2am is just a mother thing.\"","myth":{"un":"Worrying about the kids at 2am is just a mother thing.","re":"The worrying is part of the mental load, not a gender trait; a father can carry his share of the lying-awake too.","why":"Worry follows who owns the tracking, not gender."},"relearn":"Night-worry about the kids is part of the mental load both parents can carry, not a built-in mother thing.","persona":"any","source":"worry isn't gendered"},
  {"id":"ep2-993","cat":"parental-mental-load","type":"strike-rewrite","hook":"\"A shared family calendar means we've split the mental load.\"","myth":{"un":"A shared family calendar means we've split the mental load.","re":"A calendar only helps if both put things on it and act on it; if one parent fills and checks it, they still carry the load.","why":"A tool only shares load if both actually use it."},"relearn":"A shared calendar splits the load only if both parents add to it and act on it, not just one keeping it updated.","persona":"any","source":"calendar isn't sharing"},
  {"id":"ep2-994","cat":"parental-mental-load","type":"strike-rewrite","hook":"\"She just notices these things faster, so it makes sense she tracks them.\"","myth":{"un":"She just notices these things faster, so it makes sense she tracks them.","re":"She notices faster because she's been doing the tracking; let a father own a domain and he gets just as quick.","why":"Noticing is a practised skill, not an instinct."},"relearn":"One parent notices faster because they practise the tracking; owning a domain builds the same speed in either parent.","persona":"Vikram","source":"noticing is practised"},
  {"id":"ep2-995","cat":"parental-mental-load","type":"strike-rewrite","hook":"\"Once the kids are in school, the mental load basically disappears.\"","myth":{"un":"Once the kids are in school, the mental load basically disappears.","re":"School just swaps the load: fees, forms, projects, fittings and timetables are a whole new tracking job to share.","why":"The load changes shape; it doesn't go away."},"relearn":"School doesn't end the mental load; fees, forms, projects and timetables become a new tracking job to share.","persona":"Meena","source":"school load"},
  {"id":"ep2-996","cat":"parental-mental-load","type":"strike-rewrite","hook":"\"Telling my partner I'm tired of all the remembering would just sound like nagging.\"","myth":{"un":"Telling my partner I'm tired of all the remembering would just sound like nagging.","re":"Naming an invisible load you carry isn't nagging; it's the only way the work can be seen and then genuinely split.","why":"You can't share what's never named out loud."},"relearn":"Naming the invisible load you carry isn't nagging; it's how it gets seen and finally split between both parents.","persona":"Divya","source":"naming isn't nagging"},
  {"id":"ep2-997","cat":"parental-mental-load","type":"strike-rewrite","hook":"\"Grandparents help so much that there's no real mental load left to share.\"","myth":{"un":"Grandparents help so much that there's no real mental load left to share.","re":"Grandparents lighten the doing, but one parent usually still tracks and decides; that planning is the load to share.","why":"Helpers do tasks; the tracking still sits somewhere."},"relearn":"Grandparents help with tasks, but the tracking and deciding still sits with a parent; that mental load is yours to share.","persona":"any","source":"grandparents help"},
  {"id":"ep2-998","cat":"parental-mental-load","type":"strike-rewrite","hook":"\"I earn for the family, so the day-to-day kid-tracking fairly falls to her.\"","myth":{"un":"I earn for the family, so the day-to-day kid-tracking fairly falls to her.","re":"Earning is part of the job, not the whole of it; the kid-tracking is real work too and can be genuinely shared.","why":"Providing money doesn't cancel the planning work."},"relearn":"Earning is part of parenting, not all of it; the day-to-day kid-tracking is real work that can be shared too.","persona":"Vikram","source":"earning isn't enough"},
  {"id":"ep2-999","cat":"parental-mental-load","type":"strike-rewrite","hook":"\"Keeping a list on my phone of everything the kids need means I'm on top of it together.\"","myth":{"un":"Keeping a list on my phone of everything the kids need means I'm on top of it together.","re":"If only one of you keeps and acts on the list, you're not sharing; you're the sole manager with a neat list.","why":"Being organised alone is still carrying it alone."},"relearn":"Holding the whole list yourself is being a tidy sole manager, not sharing; the load lifts when both own parts of it.","persona":"Divya","source":"list isn't sharing"},
  {"id":"ep2-1000","cat":"parental-mental-load","type":"sort","hook":"Sort: someone owning a whole domain, or just doing scattered tasks on request?","items":[{"id":"a","text":"\"I run all of health, start to finish\""},{"id":"b","text":"\"I gave the baby a bath when asked\""},{"id":"c","text":"\"School is mine: fees, forms, the lot\""},{"id":"d","text":"\"I dropped him today because she told me to\""},{"id":"e","text":"\"I own meals and the grocery planning\""},{"id":"f","text":"\"I changed a nappy when she handed me one\""}],"bins":[{"id":"own","label":"Owns a domain","valence":"pos"},{"id":"task","label":"Task on request","valence":"uhoh"}],"key":{"a":"own","b":"task","c":"own","d":"task","e":"own","f":"task"},"relearn":"Running health, school or meals end-to-end is owning a domain; doing single tasks when asked is not.","persona":"Vikram","source":"own vs task"},
  {"id":"ep2-1001","cat":"parental-mental-load","type":"sort","hook":"Sort: this genuinely lifts the mental load, or it just adds to the manager's job?","items":[{"id":"a","text":"\"I'll fully own the doctor visits\""},{"id":"b","text":"\"Make me a list and I'll work through it\""},{"id":"c","text":"\"I'll track the school dates myself\""},{"id":"d","text":"\"Just remind me each time something's due\""},{"id":"e","text":"\"I'll plan and pack for the trip\""},{"id":"f","text":"\"Tell me exactly what to buy and I'll get it\""}],"bins":[{"id":"lifts","label":"Lifts the load","valence":"pos"},{"id":"adds","label":"Adds to it","valence":"neg"}],"key":{"a":"lifts","b":"adds","c":"lifts","d":"adds","e":"lifts","f":"adds"},"relearn":"Owning and tracking lifts the load; asking for lists and reminders keeps your partner managing you.","persona":"Vikram","source":"lifts or adds"},
  {"id":"ep2-1002","cat":"parental-mental-load","type":"sort","hook":"Sort: a real chunk of mental load, or a one-off five-minute task?","items":[{"id":"a","text":"Owning all the school admin for the year"},{"id":"b","text":"Signing one form she put in front of you"},{"id":"c","text":"Tracking the child's whole medical history"},{"id":"d","text":"Posting one courier when asked"},{"id":"e","text":"Knowing every birthday and gift to plan"},{"id":"f","text":"Buying one item off a sent list"}],"bins":[{"id":"load","label":"Real mental load","valence":"tell"},{"id":"oneoff","label":"One-off task","valence":"neutral"}],"key":{"a":"load","b":"oneoff","c":"load","d":"oneoff","e":"load","f":"oneoff"},"relearn":"Owning the year's admin, the medical history or the social calendar is mental load; one signed form is a task.","persona":"any","source":"load vs one-off"},
  {"id":"ep2-1003","cat":"parental-mental-load","type":"sort","hook":"Sort: a fair way to split the load, or a tidier way to keep one manager?","items":[{"id":"a","text":"Each parent owns whole domains, fully"},{"id":"b","text":"One makes the other a daily to-do list"},{"id":"c","text":"Both check and update the same calendar"},{"id":"d","text":"One is the family's single reminder app"},{"id":"e","text":"You swap who owns what every few months"},{"id":"f","text":"One keeps all the info and delegates pieces"}],"bins":[{"id":"fair","label":"Fairly split","valence":"pos"},{"id":"manager","label":"One stays manager","valence":"uhoh"}],"key":{"a":"fair","b":"manager","c":"fair","d":"manager","e":"fair","f":"manager"},"relearn":"Owning domains, sharing the calendar and swapping is fair; lists and delegating keep one as manager.","persona":"Divya","source":"fair or manager"},
  {"id":"ep2-1004","cat":"parental-mental-load","type":"sort","hook":"Sort: visible care, or the invisible mental load behind it?","items":[{"id":"a","text":"Cooking the child's dinner"},{"id":"b","text":"Knowing what they will and won't eat"},{"id":"c","text":"Dropping them at tuition"},{"id":"d","text":"Choosing the tuition and tracking fees"},{"id":"e","text":"Giving the medicine"},{"id":"f","text":"Remembering the dose, timing and refill"}],"bins":[{"id":"visible","label":"Visible care","valence":"neutral"},{"id":"mental","label":"Mental load","valence":"tell"}],"key":{"a":"visible","b":"mental","c":"visible","d":"mental","e":"visible","f":"mental"},"relearn":"Cooking, dropping and dosing are visible; knowing preferences, choosing tuition and remembering refills is the load.","persona":"any","source":"care vs load"},
  {"id":"ep2-1005","cat":"parental-mental-load","type":"sort","hook":"Sort: which belong to the parental mental load, and which don't?","items":[{"id":"a","text":"Tracking when the next jab is due"},{"id":"b","text":"Watching a cartoon with the child"},{"id":"c","text":"Planning the week's meals and supplies"},{"id":"d","text":"Carrying the child to bed once"},{"id":"e","text":"Holding every deadline and form in your head"},{"id":"f","text":"Pushing the swing at the park"}],"bins":[{"id":"load","label":"Mental load","valence":"tell"},{"id":"notload","label":"Not the load","valence":"neutral"}],"key":{"a":"load","b":"notload","c":"load","d":"notload","e":"load","f":"notload"},"relearn":"Tracking jabs, planning meals and holding deadlines is mental load; watching cartoons or pushing a swing isn't.","persona":"any","source":"load or not"},
  {"id":"ep2-1006","cat":"parental-mental-load","type":"sort","hook":"Sort: a remark that sees the mental load, or one that keeps it invisible?","items":[{"id":"a","text":"\"You're holding a lot in your head; let me own some\""},{"id":"b","text":"\"But the house runs fine, what load?\""},{"id":"c","text":"\"I'll take over remembering the medical stuff\""},{"id":"d","text":"\"You never even mentioned you were tired\""},{"id":"e","text":"\"Let's name everything you track and split it\""},{"id":"f","text":"\"You make it look easy, so it must be easy\""}],"bins":[{"id":"sees","label":"Sees the load","valence":"pos"},{"id":"hides","label":"Keeps it invisible","valence":"neg"}],"key":{"a":"sees","b":"hides","c":"sees","d":"hides","e":"sees","f":"hides"},"relearn":"Naming what a partner tracks and offering to own some sees the load; 'it looks easy' keeps it invisible.","persona":"Vikram","source":"sees or hides"},
  {"id":"ep2-1007","cat":"parental-mental-load","type":"sort","hook":"Sort: a real sign the load is shared, or only a sign it looks shared?","items":[{"id":"a","text":"Either parent knows when the next checkup is"},{"id":"b","text":"He helps a lot but always asks her what's next"},{"id":"c","text":"Both feel the worry, not just one"},{"id":"d","text":"She still 'manages' him through every task"},{"id":"e","text":"Either can run a sick day solo, start to end"},{"id":"f","text":"He does loads but she's the only planner"}],"bins":[{"id":"shared","label":"Really shared","valence":"pos"},{"id":"looks","label":"Only looks shared","valence":"uhoh"}],"key":{"a":"shared","b":"looks","c":"shared","d":"looks","e":"shared","f":"looks"},"relearn":"Either parent knowing, worrying and running a day solo is shared; doing tasks while one plans only looks shared.","persona":"Divya","source":"shared or looks"},
  {"id":"ep2-1008","cat":"parental-mental-load","type":"branch","hook":"Your partner lies awake tracking the kids' week while you sleep fine.","options":[{"text":"Take over a whole domain so half that tracking is genuinely yours","consequence":"Half the lying-awake becomes yours; the worry is shared, not just heard.","outcome":"shared","best":true},{"text":"Reassure her it'll be fine and roll over","consequence":"Reassuring without taking tracking leaves the worry on her."}],"debrief":"Take a whole domain so the worry is yours too, not just sympathised with.","relearn":"Sharing night-worry means owning some tracking, not only offering reassurance.","persona":"Vikram","source":"share the worry"},
  {"id":"ep2-1009","cat":"parental-mental-load","type":"branch","hook":"You're away two days and realise only your partner knows the kids' full routine.","options":[{"text":"Learn it now so you can run it solo, not just be told","consequence":"A second parent fully knows, so the load no longer rests on one head.","outcome":"learn","best":true},{"text":"Ask her to write detailed notes for you","consequence":"Notes keep her the one who knows; you still depend on her brain."}],"debrief":"Learn the routine so two of you hold it, not stay dependent on one memory.","relearn":"The load lifts when a second parent truly knows the routine, not when one writes it down.","persona":"Vikram","source":"learn the routine"},
  {"id":"ep2-1010","cat":"parental-mental-load","type":"branch","hook":"At lunch a relative says 'she's just better at keeping track of the kids'.","options":[{"text":"Say warmly you're learning to own your half; it's practice, not instinct","consequence":"You name it as a shared skill and model owning your share.","outcome":"reframe","best":true},{"text":"Laugh and agree to keep the peace","consequence":"Agreeing reinforces that tracking is hers by nature."}],"debrief":"Name tracking as a learnable, shared skill, not 'she's just better'.","relearn":"Tracking is practice, not instinct; naming that resists the default that it's the mother's.","persona":"Vikram","source":"not better by nature"},
  {"id":"ep2-1011","cat":"parental-mental-load","type":"branch","hook":"You keep being the one who notices the kids are out of socks and snacks.","options":[{"text":"Hand your partner full ownership of supplies, so noticing becomes theirs","consequence":"They start catching the gaps; the noticing moves off you.","outcome":"own","best":true},{"text":"Keep noticing but text them to buy each thing","consequence":"Texting each item keeps you noticing; only the buying moves."}],"debrief":"Give a whole domain over so the noticing moves too, not just the shop trip.","relearn":"Handing over the buying isn't enough; the load lifts only when the noticing becomes theirs.","persona":"Divya","source":"hand over noticing"},
  {"id":"ep2-1012","cat":"parental-mental-load","type":"branch","hook":"Your partner says 'just tell me what to do and I'll happily do it'.","options":[{"text":"Suggest he pick a domain to fully own, so you stop telling him","consequence":"He carries the thinking there; you're no longer his manager.","outcome":"ownership","best":true},{"text":"Start making him a daily list of tasks","consequence":"A daily list keeps you planning; managing him is the load."}],"debrief":"Invite him to own a domain so the planning leaves your head, not list-manage him.","relearn":"'Tell me what to do' keeps one parent the manager; owning a domain moves the thinking.","persona":"Divya","source":"stop managing"},
  {"id":"ep2-1013","cat":"parental-mental-load","type":"branch","hook":"You've never once had to think about the kids' clothes; your partner just handles it.","options":[{"text":"Take clothing fully: sizes, seasons, restocking, all of it","consequence":"A whole tracking job leaves her head for good; you carry it.","outcome":"take","best":true},{"text":"Offer to buy clothes whenever she tells you the sizes","consequence":"Buying on instructions keeps the sizes and timing in her head."}],"debrief":"Absorb the whole clothing domain, tracking included, not just act on her cues.","relearn":"Truly taking a domain means owning its tracking and timing, not just shopping when told.","persona":"Vikram","source":"take clothing"},
  {"id":"ep2-1014","cat":"parental-mental-load","type":"branch","hook":"You and your partner are both fried and snapping over forgotten kid-admin.","options":[{"text":"List everything you each track and reassign whole domains fairly","consequence":"The invisible work becomes visible and splits; the snapping eases.","outcome":"map","best":true},{"text":"Just try harder to remember more between you","consequence":"Trying harder without splitting domains leaves both overloaded."}],"debrief":"Map and reassign whole domains, not each strain to hold more in your head.","relearn":"When both are fried, naming and splitting the tracking beats trying to remember more.","persona":"any","source":"map and split"},
  {"id":"ep2-1015","cat":"parental-mental-load","type":"branch","hook":"Your partner finally lists out loud all the kid-admin she silently carries.","options":[{"text":"Thank her, then pick real domains to own this week","consequence":"Naming turns into action; her load actually drops.","outcome":"act","best":true},{"text":"Tell her you had no idea and feel bad about it","consequence":"Feeling bad without taking domains leaves the list on her."}],"debrief":"Turn her naming into you owning real domains, not just sympathy and guilt.","relearn":"Once the hidden load is named, the fix is real ownership, not stopping at feeling bad.","persona":"Vikram","source":"naming to action"},
  {"id":"ep2-1016","cat":"parental-mental-load","type":"branch","hook":"Your partner asks you to 'own bedtime', but you keep checking in with her about it.","options":[{"text":"Fully run bedtime, learn the quirks, stop asking her to confirm","consequence":"Bedtime leaves her mind; she can switch off knowing it's handled.","outcome":"own","best":true},{"text":"Do bedtime but text her nightly to check you're right","consequence":"Nightly check-ins keep bedtime on her radar; she still manages it."}],"debrief":"Own bedtime end-to-end so it leaves her head, not do it while she oversees.","relearn":"Owning a domain means carrying it without check-ins, so it leaves your partner's mind.","persona":"Vikram","source":"own bedtime"},
  {"id":"ep2-1017","cat":"parental-mental-load","type":"branch","hook":"You've taken over health admin but keep forgetting things in the early weeks.","options":[{"text":"Stick with it, build your own system, let your partner let go","consequence":"You get practised and reliable; the tracking shifts to you.","outcome":"persist","best":true},{"text":"Hand it back, saying she's clearly better at it","consequence":"Handing it back when it's hard relearns the myth that it's hers."}],"debrief":"Push through the clumsy weeks so the skill, and the load, become yours.","relearn":"You get good at tracking by practising; giving up early hands the load back unchanged.","persona":"Vikram","source":"push through"},
  {"id":"ep2-1018","cat":"parental-mental-load","type":"branch","hook":"Your partner keeps redoing the kid-admin you took on, 'just to be sure'.","options":[{"text":"Agree she'll hand it over and trust your way, even if it differs","consequence":"You own it for real; she gets to drop it from her head.","outcome":"trust","best":true},{"text":"Let her keep double-checking everything you do","consequence":"Double-checking means she's still tracking it all; the load stays."}],"debrief":"For the load to lift, your partner has to let go and trust your handling.","relearn":"Sharing the load needs the other parent to truly hand over, not silently re-track the work.","persona":"any","source":"let go to lift"},
  {"id":"ep2-1019","cat":"parental-mental-load","type":"reflect","hook":"Lensy: the parent who can take a holiday and the home keeps running is usually not the one carrying the load. Notice that?","prompt":"What's your take?","options":["I notice that","Worth a look","True for us"],"affirm":"If you can step away and nothing wobbles, you're likely not the one holding the tracking; noticing that is the start.","relearn":"Being able to switch off while the home runs often means the other parent is silently carrying the mental load.","persona":"any","source":"who can switch off"},
  {"id":"ep2-1020","cat":"parental-mental-load","type":"reflect","hook":"Lensy: try this; for one week, notice every time you ask your partner 'where is...' or 'when is...'. Worth trying?","prompt":"How does that sit?","options":["Worth trying","I'll notice","Good idea"],"affirm":"Each 'where is' or 'when is' is a moment your partner is holding info you could be holding too; noticing it is step one.","relearn":"Counting how often you ask your partner for kid-info reveals how much tracking quietly sits with them.","persona":"Vikram","source":"count the asks"},
  {"id":"ep2-1021","cat":"parental-mental-load","type":"reflect","hook":"Lensy: 'I do half the tasks' and 'I carry half the thinking' are very different claims. Sit with that?","prompt":"What do you think?","options":["I'll sit with it","Fair point","Different, yes"],"affirm":"Doing half the tasks is real, but carrying half the thinking is the harder, invisible half worth aiming for too.","relearn":"Splitting the doing isn't the same as splitting the thinking; the mental load is that second, invisible half.","persona":"any","source":"tasks vs thinking"},
  {"id":"ep2-1022","cat":"parental-mental-load","type":"reflect","hook":"Lensy: if you both vanished for a day, would the other parent know the kids' full routine, or only one of you? Wonder about it?","prompt":"What's your honest answer?","options":["Only one of us","Worth checking","Both, I hope"],"affirm":"If only one of you holds the full routine, that's the mental load made visible; sharing it means both knowing.","relearn":"When only one parent holds the whole routine, the load is on them; sharing it means both can run the day.","persona":"any","source":"who holds the routine"},
  {"id":"ep2-1023","cat":"parental-mental-load","type":"reflect","hook":"Lensy: owning a domain isn't 'helping with it', it's it never crossing the other parent's mind again. Ring true?","prompt":"What's your take?","options":["Rings true","I get it","Yes, that"],"affirm":"You've owned something when your partner can fully forget it exists; that's the load genuinely lifting.","relearn":"True ownership means a whole area leaves your partner's mind for good, not that you assist with it.","persona":"Vikram","source":"owning vs helping"},
  {"id":"ep2-1024","cat":"parental-mental-load","type":"reflect","hook":"Lensy: the tiredness from constant tracking is real, even when nobody can see you doing anything. Worth honouring?","prompt":"How does that land?","options":["Worth honouring","I feel that","It's real"],"affirm":"Holding a hundred small kid-things in your head is genuinely tiring work; it counts, even when it's invisible.","relearn":"The fatigue of always tracking is real cognitive work, not nothing, even though no one sees it happening.","persona":"Divya","source":"invisible tiredness"},
  {"id":"ep2-1025","cat":"parental-mental-load","type":"reflect","hook":"Lensy: when one parent always 'just knows', the other rarely learns. Worth thinking about?","prompt":"What do you think?","options":["Worth thinking about","I see that","Makes sense"],"affirm":"If one parent always knows, the other never has to learn; swapping who tracks lets both build the skill.","relearn":"One parent always knowing keeps the other from learning; sharing the tracking lets both get practised.","persona":"any","source":"both can learn"},
  {"id":"ep2-1026","cat":"parental-mental-load","type":"reflect","hook":"Lensy: 'managing my partner through tasks' can quietly become its own full-time job. Recognise it?","prompt":"What's your take?","options":["I recognise it","Hits home","Yes"],"affirm":"Reminding, checking and delegating is itself work; the fix is owned domains so there's nobody to manage.","relearn":"Managing your partner through tasks is its own load; owned domains remove the managing altogether.","persona":"Divya","source":"managing is work"},
  {"id":"ep2-1027","cat":"parental-mental-load","type":"spot","hook":"Spot the two lines that keep the mental load on one parent.","scene":[{"id":"a","text":"\"You're the one who remembers, so you handle the doctor.\"","trick":true},{"id":"b","text":"\"I'll own all the medical tracking from now on.\"","trick":false},{"id":"c","text":"\"Make me a list and I'll get to it.\"","trick":true},{"id":"d","text":"\"Let's each take whole areas, planning included.\"","trick":false},{"id":"e","text":"\"I'll learn the routine so I can run it solo.\"","trick":false}],"why":"Leaving the remembering to one parent and asking for a list keep that parent the planner.","relearn":"Lines that assign remembering to one parent or wait for a list keep the load lopsided.","persona":"Vikram","source":"keeps the load"},
  {"id":"ep2-1028","cat":"parental-mental-load","type":"spot","hook":"Spot the two phrases that treat the mental load as not-real-work.","scene":[{"id":"a","text":"\"It's all in your head, that's hardly work.\"","trick":true},{"id":"b","text":"\"Tracking the kids' week is real, tiring work.\"","trick":false},{"id":"c","text":"\"You didn't do anything, you just remembered.\"","trick":true},{"id":"d","text":"\"Holding all those dates deserves sharing.\"","trick":false},{"id":"e","text":"\"Worrying and planning counts; let me carry some.\"","trick":false}],"why":"Calling remembering 'hardly work' or 'not doing anything' denies that tracking is real labour.","relearn":"The mental load is real, tiring work; calling it 'nothing' erases the labour of tracking.","persona":"Divya","source":"load is real"},
  {"id":"ep2-1029","cat":"parental-mental-load","type":"spot","hook":"Spot the two moves that look like sharing but keep one parent as manager.","scene":[{"id":"a","text":"He texts to ask what to cook every single night","trick":true},{"id":"b","text":"He fully owns dinners, menu and shopping","trick":false},{"id":"c","text":"She writes him a detailed list each morning","trick":true},{"id":"d","text":"They split domains and stop checking each other","trick":false},{"id":"e","text":"Either of them can run a sick day alone","trick":false}],"why":"Asking what to cook nightly and writing daily lists keep the planning on one parent.","relearn":"Nightly 'what should I do' and daily lists leave one parent planning; owned domains don't.","persona":"Vikram","source":"looks like sharing"},
  {"id":"ep2-1030","cat":"parental-mental-load","type":"spot","hook":"Spot the two beliefs that wrongly tie the mental load to being a mother.","scene":[{"id":"a","text":"\"A mother just naturally remembers all of it.\"","trick":true},{"id":"b","text":"\"Whoever tracks it gets practised at it.\"","trick":false},{"id":"c","text":"\"Worrying about the kids is a mum thing.\"","trick":true},{"id":"d","text":"\"A father can carry his full share of planning.\"","trick":false},{"id":"e","text":"\"The load is learned by doing, not by gender.\"","trick":false}],"why":"'Mothers naturally remember' and 'worry is a mum thing' tie the load to gender; it's practice, not biology.","relearn":"The mental load isn't a mother's instinct; it's a learned, practised skill either parent can carry.","persona":"any","source":"not a mum thing"},
  {"id":"ep2-1031","cat":"parental-mental-load","type":"spot","hook":"Spot the two lines that hand over tasks but keep the tracking.","scene":[{"id":"a","text":"\"Buy these three things I've listed on your way home.\"","trick":true},{"id":"b","text":"\"I'll own groceries: noticing what's low and restocking.\"","trick":false},{"id":"c","text":"\"Remind me and I'll book the appointment.\"","trick":true},{"id":"d","text":"\"I'll watch our health needs and book them myself.\"","trick":false},{"id":"e","text":"\"School admin is mine; I'll catch the dates myself.\"","trick":false}],"why":"A ready-made list and 'remind me' move the doing but keep the noticing on one parent.","relearn":"Handing over tasks while keeping the noticing isn't sharing; owning the noticing is.","persona":"Divya","source":"task not tracking"},
  {"id":"ep2-1032","cat":"parental-mental-load","type":"spot","hook":"Spot the two responses that dodge owning a share of the load.","scene":[{"id":"a","text":"\"You're just better at this stuff than me.\"","trick":true},{"id":"b","text":"\"I'll take a domain and get practised at it.\"","trick":false},{"id":"c","text":"\"I'd only do it wrong, so you keep it.\"","trick":true},{"id":"d","text":"\"I'll learn the routine so it's genuinely mine.\"","trick":false},{"id":"e","text":"\"Let's split the tracking, not just the tasks.\"","trick":false}],"why":"'You're better at it' and 'I'd do it wrong' use skill-gaps as reasons to keep the load on one parent.","relearn":"'You're better' and 'I'd mess it up' dodge ownership; the skill comes from practising your share.","persona":"Vikram","source":"dodge ownership"},
  {"id":"ep2-1033","cat":"parental-mental-load","type":"spot","hook":"Spot the two replies that quietly make 'remembering' her permanent job.","scene":[{"id":"a","text":"\"You've got such a good memory, you keep all the dates.\"","trick":true},{"id":"b","text":"\"Let's both put dates in the shared calendar.\"","trick":false},{"id":"c","text":"\"Your brain is the family diary, it works for us.\"","trick":true},{"id":"d","text":"\"I'll own and track the school calendar myself.\"","trick":false},{"id":"e","text":"\"We can swap who tracks what every few months.\"","trick":false}],"why":"Praising her memory as 'the family diary' assigns all remembering to her for good.","relearn":"Praising one parent's memory to keep them the diary entrenches the load; sharing lifts it.","persona":"Vikram","source":"her permanent job"},
  {"id":"ep2-1034","cat":"parental-mental-load","type":"role-play","hook":"Your partner looks wiped out from holding the kids' whole week in her head. You want to genuinely take some.","setup":"Offer real ownership:","yourLine":[{"text":"\"Let me fully own school and meals, tracking and all, so they leave your head.\"","best":true},{"text":"\"Tell me what to do today and I'll handle it.\""}],"relearn":"Offering to fully own whole domains, tracking included, lifts the planning off your partner, not just the tasks.","persona":"Vikram","source":"own domains"},
  {"id":"ep2-1035","cat":"parental-mental-load","type":"role-play","hook":"You're the parent silently carrying all the kid-admin, and you want your partner to truly share it.","setup":"Name it and ask for ownership, not help:","yourLine":[{"text":"\"I'm tracking everything in my head; can you take full ownership of health and clothes?\"","best":true},{"text":"\"Could you maybe help out a bit more when I ask?\""}],"relearn":"Asking a partner to fully own domains shares the tracking; asking for 'help when I ask' keeps you the manager.","persona":"Divya","source":"ask for ownership"},
  {"id":"ep2-1036","cat":"parental-mental-load","type":"role-play","hook":"A relative says your wife is 'just naturally better with the kids' admin'. You want to reframe it kindly.","setup":"Reframe it as shared and learned:","yourLine":[{"text":"\"It's practice, not nature; I'm learning to own my half of the tracking too.\"","best":true},{"text":"\"Yeah, she's the organised one, I just pitch in.\""}],"relearn":"Naming tracking as learned, shareable practice resists 'she's naturally better' and models owning your half.","persona":"Vikram","source":"learned not natural"},
  {"id":"ep2-1037","cat":"parental-mental-load","type":"role-play","hook":"Your partner keeps double-checking the kid-admin you've taken on. You want her to actually let it go.","setup":"Ask for trust so it leaves her head:","yourLine":[{"text":"\"I've fully got health now; you can let it go and stop tracking it.\"","best":true},{"text":"\"Keep checking my work, just in case I miss something.\""}],"relearn":"For the load to lift, a partner has to truly let go and stop re-tracking; double-checking keeps it on her.","persona":"Vikram","source":"let her let go"},
  {"id":"ep2-1038","cat":"parental-mental-load","type":"role-play","hook":"You catch yourself about to ask your partner 'just make me a list'. You want to take real ownership instead.","setup":"Take the thinking, not a list:","yourLine":[{"text":"\"Don't make me a list, I'll take meals and groceries and run them myself.\"","best":true},{"text":"\"Write down everything you need and I'll work through it.\""}],"relearn":"Owning a domain and its planning lifts the load; asking for a list keeps your partner doing the thinking.","persona":"Vikram","source":"no list"},
  {"id":"ep2-1039","cat":"parental-mental-load","type":"role-play","hook":"You're heading away for work and only your partner knows the kids' full routine. You want to fix that for good.","setup":"Offer to learn it, not lean on her:","yourLine":[{"text":"\"Teach me the whole routine so I carry it too, not so I keep asking you.\"","best":true},{"text":"\"Just text me whenever you need me to do something.\""}],"relearn":"Learning the routine so two parents hold it shares the load; staying dependent on one parent's memory doesn't.","persona":"Vikram","source":"learn it yourself"},
  {"id":"ep2-1040","cat":"parental-mental-load","type":"role-play","hook":"At bedtime your partner is still rattling off what you both need to remember tomorrow. You want to split it fairly.","setup":"Propose owned domains so nobody holds it all:","yourLine":[{"text":"\"Let's each own whole areas, so neither of us carries the whole list in our head.\"","best":true},{"text":"\"You keep track and just tell me my bits in the morning.\""}],"relearn":"Splitting into owned domains stops one parent holding the whole list; being told your bits keeps them the planner.","persona":"any","source":"split the holding"},
  {"id":"ep2-1041","cat":"parental-mental-load","type":"strike-rewrite","hook":"\"I take the kids out every weekend, so I'm clearly carrying my half.\"","myth":{"un":"I take the kids out every weekend, so I'm clearly carrying my half.","re":"Fun outings are great, but the invisible planning, tracking and worrying runs all week; that's the half to share too.","why":"Weekends are the easy, visible part of the load."},"relearn":"Weekend outings are real, but the week-long tracking and planning is the invisible half that also needs sharing.","persona":"Vikram","source":"weekend isn't half"},
  {"id":"ep2-1042","cat":"parental-mental-load","type":"match","hook":"Match the everyday moment to the hidden tracking behind it.","pairs":[{"left":"The lunchbox is packed","right":"Knowing what they'll eat and what's low"},{"left":"Clean uniform on time","right":"Tracking laundry, sizes and spares"},{"left":"Fees paid by the deadline","right":"Holding every due date in your head"},{"left":"Medicine given on schedule","right":"Remembering the dose, timing and refill"},{"left":"Party gift ready to go","right":"Knowing whose birthday and what they'd like"}],"relearn":"Behind each smooth daily moment sits invisible tracking; naming it is how it gets shared.","persona":"any","source":"moment to tracking"},
  {"id":"ep2-1043","cat":"parental-mental-load","type":"match","hook":"Match the 'I'll help' offer to the fuller 'I'll own it' version.","pairs":[{"left":"\"Tell me which doctor, I'll drive\"","right":"\"I'll run all the health visits\""},{"left":"\"Send a list and I'll shop\"","right":"\"I'll own groceries and what's low\""},{"left":"\"Remind me about the form\"","right":"\"I'll watch all the school dates\""},{"left":"\"Wake me if the baby cries\"","right":"\"I'll take the night shifts as mine\""},{"left":"\"Ask me when you need a hand\"","right":"\"I'll carry two whole domains\""}],"relearn":"Each 'help when asked' offer has an 'own it' version that moves the tracking, not just the task.","persona":"Vikram","source":"help to own"},
  {"id":"ep2-900","cat":"share-the-care","type":"strike-rewrite","hook":"\"I'm just babysitting my own kids while she's at the temple.\"","myth":{"un":"I'm just babysitting my own kids today.","re":"A father caring for his own child is parenting, not babysitting; it's your job, not a favour you do.","why":"You don't babysit your own children."},"relearn":"Caring for your own child is parenting, never babysitting.","persona":"Vikram","source":"not babysitting"},
  {"id":"ep2-901","cat":"share-the-care","type":"strike-rewrite","hook":"\"A baby just needs its mother in the first year; I'll get involved later.\"","myth":{"un":"A baby just needs its mother in the first year.","re":"Babies bond with both parents from birth; feeds, nappies and soothing are yours to own from day one.","why":"Bonding starts at birth, for both parents."},"relearn":"Infants attach to both parents from birth; start owning care from day one.","persona":"Vikram","source":"from day one"},
  {"id":"ep2-902","cat":"share-the-care","type":"strike-rewrite","hook":"\"Men's hands are too clumsy for nappies and tiny clothes.\"","myth":{"un":"Men's hands are too clumsy for nappies and tiny clothes.","re":"Nappies and dressing are learned by repetition; any parent who practises gets quick and confident.","why":"It's practice, not biology."},"relearn":"Care skills come from practice, not from being a mother.","persona":"any","source":"learned by doing"},
  {"id":"ep2-903","cat":"share-the-care","type":"strike-rewrite","hook":"\"I earn the money, so the night feeds are fair to leave to her.\"","myth":{"un":"I earn the money, so the nights are fairly hers.","re":"Providing is part of the job, not all of it; children need your hands-on nights and presence too.","why":"A pay-cheque isn't a pass on care."},"relearn":"Providing financially doesn't buy out your share of hands-on care.","persona":"Vikram","source":"more than the wage"},
  {"id":"ep2-904","cat":"share-the-care","type":"strike-rewrite","hook":"\"I help out a lot at home, so the care is basically shared.\"","myth":{"un":"I help out a lot, so care is basically shared.","re":"'Helping' still makes her the manager who notices and asks; sharing means owning whole tasks yourself.","why":"A helper waits to be told."},"relearn":"Owning tasks is sharing; 'helping when asked' leaves one parent in charge.","persona":"Vikram","source":"own not help"},
  {"id":"ep2-905","cat":"share-the-care","type":"strike-rewrite","hook":"\"Taking the baby to the doctor is really a mother's errand.\"","myth":{"un":"Doctor visits are really a mother's errand.","re":"Either parent can book, attend and ask the questions at check-ups; it's a task to own, not a gendered errand.","why":"Appointments aren't mother-only."},"relearn":"Appointments are a job either parent can fully own.","persona":"any","source":"appointments shared"},
  {"id":"ep2-906","cat":"share-the-care","type":"strike-rewrite","hook":"\"I can't do the school-run; I wouldn't know the routine.\"","myth":{"un":"I can't do the school-run; I don't know the routine.","re":"You learn the routine the same way she did, by doing it a few times; not-knowing is a head-start gap, not a rule.","why":"Routines are learnable, fast."},"relearn":"Not knowing a routine is fixed by doing it, not a reason to opt out.","persona":"Vikram","source":"learn the run"},
  {"id":"ep2-907","cat":"share-the-care","type":"strike-rewrite","hook":"\"Weekend dad is enough; she handles the weekdays.\"","myth":{"un":"Being the weekend dad is enough.","re":"Daily feeds, baths and bedtimes are where bonds grow; presence across the week beats a Sunday cameo.","why":"Quality care is daily, not occasional."},"relearn":"Everyday presence builds the bond; weekend-only isn't a fair share.","persona":"Vikram","source":"daily not sunday"},
  {"id":"ep2-908","cat":"share-the-care","type":"strike-rewrite","hook":"\"My father never changed a nappy and we turned out fine.\"","myth":{"un":"My father never did nappies and we turned out fine.","re":"The old default isn't a target to copy; sharing care now is better for your kids and for you.","why":"You can break the pattern you grew up with."},"relearn":"Inheriting an unequal split isn't a reason to repeat it.","persona":"Vikram","source":"break the pattern"},
  {"id":"ep2-909","cat":"share-the-care","type":"strike-rewrite","hook":"\"Sharing care fairly means I track every nappy I do versus her.\"","myth":{"un":"Sharing fairly means tracking every nappy each of us does.","re":"Fair sharing is owning whole domains and flexing for each other, not tallying a scorecard.","why":"Ownership and flexibility beat counting."},"relearn":"Fairness is owned domains plus flexibility, not a nappy scoreboard.","persona":"any","source":"no scorecard"},
  {"id":"ep2-910","cat":"share-the-care","type":"strike-rewrite","hook":"\"She breastfeeds, so naturally everything baby-related falls to her.\"","myth":{"un":"She breastfeeds, so all baby tasks fall to her.","re":"Only breastfeeding is mother-specific; burping, winding, changing and settling are all yours to take.","why":"One task is hers; the rest aren't."},"relearn":"Only feeding at the breast is mother-only; the rest you can own.","persona":"Divya","source":"only breastfeeding"},
  {"id":"ep2-911","cat":"share-the-care","type":"sort","hook":"Sort: a task only the breastfeeding mother can do, or one either parent can own?","items":[{"id":"a","text":"Feeding milk at the breast"},{"id":"b","text":"Winding the baby after a feed"},{"id":"c","text":"Bathing and dressing"},{"id":"d","text":"Rocking back to sleep at 2am"},{"id":"e","text":"Sterilising and prepping bottles"},{"id":"f","text":"Clipping tiny nails"}],"bins":[{"id":"either","label":"Either parent","valence":"pos"},{"id":"mum","label":"Mother-specific","valence":"neutral"}],"key":{"a":"mum","b":"either","c":"either","d":"either","e":"either","f":"either"},"relearn":"Only feeding at the breast is mother-specific; winding, bathing, settling and prepping are jobs either parent owns.","persona":"any","source":"either or mum"},
  {"id":"ep2-912","cat":"share-the-care","type":"sort","hook":"Sort: genuinely shared care, or lopsided dressed up as sharing?","items":[{"id":"a","text":"Each owns whole care domains"},{"id":"b","text":"One does it all, one 'helps' sometimes"},{"id":"c","text":"Nights alternated between you"},{"id":"d","text":"One is always the default backup"},{"id":"e","text":"Both can run a day solo"},{"id":"f","text":"She must remind you of every task"}],"bins":[{"id":"fair","label":"Genuinely shared","valence":"pos"},{"id":"lop","label":"Lopsided","valence":"neg"}],"key":{"a":"fair","b":"lop","c":"fair","d":"lop","e":"fair","f":"lop"},"relearn":"Owning domains, alternating nights and both running solo is shared; one doing it all while the other 'helps' is lopsided.","persona":"Vikram","source":"fair vs lopsided"},
  {"id":"ep2-913","cat":"share-the-care","type":"sort","hook":"Sort: builds both parents' competence, or keeps one parent the only 'expert'?","items":[{"id":"a","text":"Both do solo stretches with the baby"},{"id":"b","text":"One always supervises the other"},{"id":"c","text":"Both learn the full bedtime routine"},{"id":"d","text":"Treating one as the only 'expert'"},{"id":"e","text":"Swapping who does the early start"},{"id":"f","text":"Redoing his work 'properly' after"}],"bins":[{"id":"both","label":"Builds both","valence":"pos"},{"id":"one","label":"Keeps it one-sided","valence":"neg"}],"key":{"a":"both","b":"one","c":"both","d":"one","e":"both","f":"one"},"relearn":"Solo time, shared routines and swapping starts build both; constant supervision, a single 'expert' and redoing his work keep it one-sided.","persona":"any","source":"both vs one-sided"},
  {"id":"ep2-914","cat":"share-the-care","type":"sort","hook":"Sort each daily care job: clearly owned by one of you, or floating with no owner?","items":[{"id":"a","text":"Morning bath: Dad owns it"},{"id":"b","text":"Whoever notices does the nappy"},{"id":"c","text":"Bedtime story: Mum owns it"},{"id":"d","text":"'Someone' should book the jab"},{"id":"e","text":"School-run: Dad owns Mon-Wed"},{"id":"f","text":"Sick days: 'we'll figure it out'"}],"bins":[{"id":"owned","label":"Clearly owned","valence":"pos"},{"id":"float","label":"No owner","valence":"uhoh"}],"key":{"a":"owned","b":"float","c":"owned","d":"float","e":"owned","f":"float"},"relearn":"Named owners keep care reliable; 'whoever notices' and 'someone should' float onto whoever cracks first.","persona":"Meena","source":"owned vs floating"},
  {"id":"ep2-915","cat":"share-the-care","type":"sort","hook":"Sort: a fair way to split a recurring duty, or a way that quietly reloads one parent?","items":[{"id":"a","text":"Alternate night wake-ups by turn"},{"id":"b","text":"'You're better at it, you do it'"},{"id":"c","text":"Each owns some appointments"},{"id":"d","text":"Wait to be asked before helping"},{"id":"e","text":"Split the school week in half"},{"id":"f","text":"One stays the permanent backup"}],"bins":[{"id":"fair","label":"Fair split","valence":"pos"},{"id":"reload","label":"Reloads one parent","valence":"neg"}],"key":{"a":"fair","b":"reload","c":"fair","d":"reload","e":"fair","f":"reload"},"relearn":"Turns, owned appointments and a split week share the duty; 'you're better at it' and 'wait to be asked' reload one parent.","persona":"any","source":"split vs reload"},
  {"id":"ep2-916","cat":"share-the-care","type":"sort","hook":"Sort each line: owning your share, or handing it back to her?","items":[{"id":"a","text":"'I've got bath and bed tonight'"},{"id":"b","text":"'Just tell me what to do'"},{"id":"c","text":"'I booked the dentist for Friday'"},{"id":"d","text":"'Ask your mother, she'll know'"},{"id":"e","text":"'I'll take the early shift this week'"},{"id":"f","text":"'I helped a lot today, didn't I?'"}],"bins":[{"id":"own","label":"Owning it","valence":"pos"},{"id":"back","label":"Handing it back","valence":"neg"}],"key":{"a":"own","b":"back","c":"own","d":"back","e":"own","f":"back"},"relearn":"Naming what you've got and booking it yourself is owning; 'tell me what to do' and 'didn't I help?' hand it back.","persona":"Vikram","source":"own vs hand back"},
  {"id":"ep2-917","cat":"share-the-care","type":"sort","hook":"Sort: part of hands-on parenting, or only the providing half of the job?","items":[{"id":"a","text":"Paying school fees on time"},{"id":"b","text":"Doing the bedtime routine"},{"id":"c","text":"Earning the household income"},{"id":"d","text":"Sitting up with a feverish child"},{"id":"e","text":"Buying the formula and nappies"},{"id":"f","text":"Packing the school tiffin daily"}],"bins":[{"id":"hands","label":"Hands-on care","valence":"pos"},{"id":"provide","label":"Providing only","valence":"neutral"}],"key":{"a":"provide","b":"hands","c":"provide","d":"hands","e":"provide","f":"hands"},"relearn":"Providing matters, but bedtime, fevers and tiffins are the hands-on care children also need from you.","persona":"Vikram","source":"provide and care"},
  {"id":"ep2-918","cat":"share-the-care","type":"sort","hook":"Sort: a sign care is genuinely shared at home, or a sign it's still one-parent-run?","items":[{"id":"a","text":"Either of you can leave for a day"},{"id":"b","text":"Only one knows the bedtime steps"},{"id":"c","text":"Both have the paediatrician's number"},{"id":"d","text":"Tasks pile up if she's unwell"},{"id":"e","text":"Both pack the bag for an outing"},{"id":"f","text":"She writes you a list to manage"}],"bins":[{"id":"shared","label":"Truly shared","valence":"pos"},{"id":"solo","label":"One-parent-run","valence":"neg"}],"key":{"a":"shared","b":"solo","c":"shared","d":"solo","e":"shared","f":"solo"},"relearn":"Either-can-leave, both-know-the-doctor and both-pack point to shared care; pile-ups and a list point to one-parent-run.","persona":"any","source":"shared vs solo"},
  {"id":"ep2-919","cat":"share-the-care","type":"sort","hook":"Sort each move: makes care a swappable two-person job, or keeps it stuck on one?","items":[{"id":"a","text":"Both kept in the school WhatsApp"},{"id":"b","text":"Only her number on the forms"},{"id":"c","text":"Both know where the medicines are"},{"id":"d","text":"Dad never told the daily timings"},{"id":"e","text":"Either can call in the maid's leave"},{"id":"f","text":"One parent holds all the passwords"}],"bins":[{"id":"swap","label":"Swappable","valence":"pos"},{"id":"stuck","label":"Stuck on one","valence":"neg"}],"key":{"a":"swap","b":"stuck","c":"swap","d":"stuck","e":"swap","f":"stuck"},"relearn":"Shared contacts, knowledge and access make care swappable; single-name forms and hidden info keep it stuck on one.","persona":"Meena","source":"swappable vs stuck"},
  {"id":"ep2-920","cat":"share-the-care","type":"sort","hook":"Sort each weekend habit: shares the care, or leaves the real load on her?","items":[{"id":"a","text":"Dad takes the kids the whole Sunday"},{"id":"b","text":"He plays, she does feeds and naps"},{"id":"c","text":"Both cook and clean up after meals"},{"id":"d","text":"He naps while she manages both kids"},{"id":"e","text":"He owns the park-and-bath shift"},{"id":"f","text":"'Fun dad' leaves the hard bits to her"}],"bins":[{"id":"share","label":"Shares it","valence":"pos"},{"id":"leave","label":"Leaves load on her","valence":"neg"}],"key":{"a":"share","b":"leave","c":"share","d":"leave","e":"share","f":"leave"},"relearn":"Taking whole shifts and the messy bits shares the care; being 'fun dad' who skips feeds, naps and clean-up leaves the load on her.","persona":"Vikram","source":"share vs fun-dad"},
  {"id":"ep2-921","cat":"share-the-care","type":"sort","hook":"Sort: a fair way to bring in grandparent help, or a way that sidelines you as a parent?","items":[{"id":"a","text":"Grandparents help; you stay hands-on"},{"id":"b","text":"Your share quietly shifts to Dadi"},{"id":"c","text":"Family covers while both of you work"},{"id":"d","text":"You opt out because Nani's there"},{"id":"e","text":"You still own nights and bath time"},{"id":"f","text":"Grandma becomes the second parent"}],"bins":[{"id":"good","label":"Help, still parenting","valence":"pos"},{"id":"side","label":"Sidelines you","valence":"neg"}],"key":{"a":"good","b":"side","c":"good","d":"side","e":"good","f":"side"},"relearn":"Welcome grandparent help while you stay hands-on; letting your share pass to them sidelines you from your own child.","persona":"Vikram","source":"help not replace"},
  {"id":"ep2-922","cat":"share-the-care","type":"branch","hook":"It's the third night running she's done the 2am feed while you slept through.","options":[{"text":"Agree to alternate nights so you each rest and bond","consequence":"Both of you sleep and both bond with the baby.","outcome":"alternate","best":true},{"text":"Let it ride since you're 'a heavier sleeper'","consequence":"Being 'a heavy sleeper' just makes her the permanent night parent."}],"debrief":"Alternate the nights so rest and bonding are shared, not defaulted to one of you.","relearn":"Alternate night feeds; 'heavy sleeper' shouldn't decide who's up every night.","persona":"Vikram","source":"alternate nights"},
  {"id":"ep2-923","cat":"share-the-care","type":"branch","hook":"You realise you've never once taken your child to the doctor on your own.","options":[{"text":"Take over the next appointment fully, from booking to questions","consequence":"You learn your child's health and stop being the spare parent.","outcome":"own-it","best":true},{"text":"Keep tagging along as the silent driver","consequence":"Tagging along silently keeps her the only parent who knows the health story."}],"debrief":"Own a whole appointment end to end so the health domain is genuinely shared.","relearn":"Own appointments fully; being the silent driver isn't sharing them.","persona":"Vikram","source":"own appointments"},
  {"id":"ep2-924","cat":"share-the-care","type":"branch","hook":"Your partner says 'just leave it, it's faster if I do it' every time you try a feed.","options":[{"text":"Ask her to step back so you can learn by doing it your way","consequence":"You build real competence and she stops being the only capable one.","outcome":"learn","best":true},{"text":"Step aside and let her keep doing it","consequence":"Stepping aside keeps you deskilled and her permanently on duty."}],"debrief":"Push past the 'faster if I do it' habit so both of you become fully capable.","relearn":"Learn by doing, even if slower; stepping aside keeps care one-sided.","persona":"Vikram","source":"learn by doing"},
  {"id":"ep2-925","cat":"share-the-care","type":"branch","hook":"A relative praises you for 'helping your wife so much with the kids'.","options":[{"text":"Gently say you're parenting your own children, not helping","consequence":"You reset the frame: care is your job, not her favour to receive.","outcome":"reframe","best":true},{"text":"Smile and accept the praise for 'helping'","consequence":"Accepting the 'helper' praise quietly keeps her the real owner."}],"debrief":"Reframe 'helping' as parenting so your share is owned, not credited as a favour.","relearn":"You parent your own kids; 'helping' framing leaves her the manager.","persona":"Vikram","source":"reframe helping"},
  {"id":"ep2-926","cat":"share-the-care","type":"branch","hook":"Back from paternity leave, you feel the school-runs and feeds sliding back to her.","options":[{"text":"Lock in specific shifts you own even on work days","consequence":"Your share survives the return to work instead of evaporating.","outcome":"lock-in","best":true},{"text":"Let work be the reason to hand it all back","consequence":"Using work as the reason quietly rebuilds the old default."}],"debrief":"Protect owned shifts after leave ends so the share doesn't snap back to her.","relearn":"Hold owned care shifts after leave; don't let work undo the split.","persona":"Vikram","source":"hold after leave"},
  {"id":"ep2-927","cat":"share-the-care","type":"branch","hook":"Your toddler is sick and someone has to stay home from work tomorrow.","options":[{"text":"Offer to take the sick day yourself this time","consequence":"You share the career hit so the bedside care doesn't always fall on her.","outcome":"take-turns","best":true},{"text":"Assume she'll take it, like always","consequence":"Assuming she'll take every sick day stalls her work and never yours."}],"debrief":"Take turns on sick days so the career cost and the caregiving are both shared.","relearn":"Share sick days; defaulting them to her loads care and career hits on one.","persona":"any","source":"share sick days"},
  {"id":"ep2-928","cat":"share-the-care","type":"branch","hook":"You can name your child's favourite snack but not their shoe size or doctor.","options":[{"text":"Take over a whole domain like health or clothing to learn it","consequence":"You hold real knowledge instead of just the fun-parent trivia.","outcome":"own-domain","best":true},{"text":"Keep being the fun parent and leave details to her","consequence":"Staying 'fun parent' keeps every real detail her job to carry."}],"debrief":"Own a full domain so you carry real care knowledge, not just the fun bits.","relearn":"Owning a domain builds real knowledge; fun-parent trivia isn't sharing.","persona":"Vikram","source":"fun parent gap"},
  {"id":"ep2-929","cat":"share-the-care","type":"branch","hook":"Your wife is travelling for work for a week and relatives offer to 'manage the kids'.","options":[{"text":"Run the week solo yourself, calling family only if needed","consequence":"You prove you can fully parent and your kids see it too.","outcome":"solo-week","best":true},{"text":"Hand the kids to grandparents for the week","consequence":"Handing them off signals you can't run your own home solo."}],"debrief":"Run the solo stretch yourself so your competence and your child's trust both grow.","relearn":"Take the solo week yourself; routinely handing off keeps you deskilled.","persona":"Vikram","source":"run it solo"},
  {"id":"ep2-930","cat":"share-the-care","type":"branch","hook":"You both list out the daily care and see almost every job sits with her.","options":[{"text":"Redistribute it now into fair, owned shares together","consequence":"You rebalance before resentment sets in; naming it is the work.","outcome":"rebalance","best":true},{"text":"Note it but leave the split as it is","consequence":"Noticing without rebalancing just makes the imbalance official."}],"debrief":"Naming an unequal split is common; rebalancing it together is the actual work.","relearn":"Don't just name the imbalance; rebalance it into owned shares together.","persona":"Divya","source":"rebalance together"},
  {"id":"ep2-931","cat":"share-the-care","type":"branch","hook":"Your partner wants a weekend away alone and you feel a flicker of panic about the kids.","options":[{"text":"Say yes and own the full weekend so she truly rests","consequence":"She gets real rest and you get real confidence with the kids.","outcome":"yes","best":true},{"text":"Say yes but text her about every little thing","consequence":"Texting for every decision means she never actually gets off duty."}],"debrief":"Own the solo weekend end to end so her break is real, not remote-managed.","relearn":"Give a real break by deciding solo, not by texting her every choice.","persona":"Vikram","source":"real break"},
  {"id":"ep2-932","cat":"share-the-care","type":"branch","hook":"You and your partner keep clashing over who forgot what; it's getting tense.","options":[{"text":"Each take whole domains so no one is chasing the other","consequence":"Owned domains end the chasing; you each just run your part.","outcome":"domains","best":true},{"text":"Make a shared list she keeps reminding you about","consequence":"A list she polices keeps her the manager and you the helper."}],"debrief":"Split into owned domains, not a list one of you has to enforce on the other.","relearn":"Owned domains stop the chasing; a policed list keeps one parent in charge.","persona":"any","source":"domains not list"},
  {"id":"ep2-933","cat":"share-the-care","type":"match","hook":"Match each recurring duty to a fair way to share it.","pairs":[{"left":"Night wake-ups","right":"Take turns or split the week"},{"left":"Doctor and dentist visits","right":"Each owns some, not all on one"},{"left":"Daily feeds and bathing","right":"Whoever's free, both capable"},{"left":"School drop and pick-up","right":"Own set days each, by name"},{"left":"Sick days off work","right":"Alternate who stays home"}],"relearn":"Nights, appointments, daily care, the school-run and sick days each have a fair, owned split when both parents can do them.","persona":"any","source":"fair splits"},
  {"id":"ep2-934","cat":"share-the-care","type":"match","hook":"Match each shared-care move to what it actually achieves.","pairs":[{"left":"Each owns set tasks","right":"No constant negotiating"},{"left":"Alternating nights","right":"Both rest and both bond"},{"left":"Both know the routines","right":"Either can step in fully"},{"left":"Both on the school forms","right":"Either gets the call"},{"left":"Dad does solo days","right":"Real, not supervised, skill"}],"relearn":"Owned tasks, alternating nights, shared routines and contacts, and solo days make care genuinely two-person.","persona":"any","source":"moves and effects"},
  {"id":"ep2-935","cat":"share-the-care","type":"match","hook":"Match each 'I'm sharing' line to whether it owns the work or just helps.","pairs":[{"left":"'I booked the jab myself'","right":"Owns the health task"},{"left":"'Tell me and I'll do it'","right":"Waits to be managed"},{"left":"'I've got bedtimes this week'","right":"Owns a whole shift"},{"left":"'I helped with the kids today'","right":"Frames care as a favour"},{"left":"'I know our daily routine'","right":"Can run the day solo"}],"relearn":"Booking, owning shifts and knowing the routine is owning care; 'tell me' and 'I helped' is being a helper.","persona":"Vikram","source":"own vs help"},
  {"id":"ep2-936","cat":"share-the-care","type":"match","hook":"Match each care job to who can actually do it.","pairs":[{"left":"Feeding at the breast","right":"Only the nursing mother"},{"left":"Giving a bottle feed","right":"Either parent, learned by doing"},{"left":"Changing and bathing","right":"Either parent, no instinct needed"},{"left":"Soothing back to sleep","right":"Either parent, with practice"},{"left":"Booking the check-up","right":"Either parent owns it"}],"relearn":"Only feeding at the breast is mother-specific; bottle feeds, changing, soothing and appointments are either parent's to own.","persona":"any","source":"who can do it"},
  {"id":"ep2-937","cat":"share-the-care","type":"match","hook":"Match each home setup to what it does to the care load.","pairs":[{"left":"Both names on school forms","right":"Either parent gets reached"},{"left":"Only her on every contact","right":"She fields every call"},{"left":"Both know where medicines are","right":"Either handles a fever"},{"left":"Dad owns Mon-Wed runs","right":"The week is truly split"},{"left":"'Whoever notices' does it","right":"Loads onto whoever cracks"}],"relearn":"Shared contacts, knowledge and named days split the load; single-contact and 'whoever notices' setups pile it on one parent.","persona":"Meena","source":"setup and load"},
  {"id":"ep2-938","cat":"share-the-care","type":"match","hook":"Match each parenting belief to the truth that replaces it.","pairs":[{"left":"'Dad is just helping out'","right":"Dad is parenting his own kids"},{"left":"'Only mum can soothe baby'","right":"Soothing is learned by doing"},{"left":"'I provide, that's my part'","right":"Kids need presence too"},{"left":"'Fair means a scorecard'","right":"Fair means owned domains"},{"left":"'Baby just needs mum early'","right":"Babies bond with both"}],"relearn":"Helping, mum-only soothing, providing-is-enough, scorecards and 'just needs mum' each get replaced by a shared-care truth.","persona":"any","source":"belief to truth"},
  {"id":"ep2-939","cat":"share-the-care","type":"match","hook":"Match each parent's everyday action to the fair-sharing principle it shows.","pairs":[{"left":"Dad runs a full solo day","right":"Both build real competence"},{"left":"They swap the early shift","right":"Flexing, not a fixed default"},{"left":"Each owns whole domains","right":"No one waits to be asked"},{"left":"Both cover sick days","right":"Career hits are shared"},{"left":"Welcome Dadi, still hands-on","right":"Help without being sidelined"}],"relearn":"Solo days, swapping shifts, owned domains, shared sick days and staying hands-on with grandparents each show fair sharing in action.","persona":"any","source":"action to principle"},
  {"id":"ep2-940","cat":"share-the-care","type":"match","hook":"Match each fairness pitfall to the fix that actually shares the care.","pairs":[{"left":"One parent the default backup","right":"Each owns set shifts"},{"left":"'You're better, you do it'","right":"He practises till capable"},{"left":"Care collapses if she's ill","right":"Both can run it solo"},{"left":"Praise for 'helping wife'","right":"Reframe it as parenting"},{"left":"Share shifts back after leave","right":"Lock in work-day shifts"}],"relearn":"Default-backup, 'you're better', single-capable, helper-praise and post-leave drift each have a fix that genuinely shares care.","persona":"any","source":"pitfall to fix"},
  {"id":"ep2-941","cat":"share-the-care","type":"role-play","hook":"Your partner assumes you can't handle the baby alone for a full day. Claim your competence.","setup":"Say it warmly:","yourLine":[{"text":"\"I've got this. Go enjoy your day, I know our routines and we'll be just fine.\"","best":true},{"text":"\"Okay, leave me a long list, I'll probably mess something up.\""}],"relearn":"Owning solo care builds your competence and frees your partner from being the only capable one.","persona":"Vikram","source":"claim competence"},
  {"id":"ep2-942","cat":"share-the-care","type":"role-play","hook":"A relative calls you a great dad for 'babysitting' your own kids. Reset the frame kindly.","setup":"You reply:","yourLine":[{"text":"\"I'm not babysitting, they're my kids. Looking after them is just my job too.\"","best":true},{"text":"\"Ha, yeah, giving the wife a little break today.\""}],"relearn":"Naming it as parenting, not babysitting, claims your real share instead of a favour.","persona":"Vikram","source":"not babysitting"},
  {"id":"ep2-943","cat":"share-the-care","type":"role-play","hook":"At the clinic the nurse keeps addressing only your wife. You want to own the health domain.","setup":"You step in:","yourLine":[{"text":"\"I handle his appointments too, you can tell me the dosage and the next date.\"","best":true},{"text":"\"Oh, just tell her everything, she's the one who keeps track.\""}],"relearn":"Speaking up at appointments makes the health domain genuinely yours to share.","persona":"Vikram","source":"own health domain"},
  {"id":"ep2-944","cat":"share-the-care","type":"role-play","hook":"Your partner is up again at night and starts to take the feed. You want to share it.","setup":"You offer:","yourLine":[{"text":"\"I'll take tonight, you sleep. Let's just swap nights from now on.\"","best":true},{"text":"\"Wake me only if you really can't manage it yourself.\""}],"relearn":"Offering to take and swap nights shares the rest and the bonding, instead of defaulting to one of you.","persona":"Vikram","source":"take the night"},
  {"id":"ep2-945","cat":"share-the-care","type":"role-play","hook":"Your wife keeps redoing your nappy changes 'properly'. You want room to learn.","setup":"You say:","yourLine":[{"text":"\"Let me do it my way and learn. If I never practise, I'll always need you for it.\"","best":true},{"text":"\"Fine, you're better at it, you just handle the changes.\""}],"relearn":"Asking for room to practise stops one parent staying the only expert.","persona":"Vikram","source":"room to learn"},
  {"id":"ep2-946","cat":"share-the-care","type":"role-play","hook":"Your mother insists 'leave the baby with me, you two rest'. You want to stay hands-on.","setup":"You answer warmly:","yourLine":[{"text":"\"Thanks Ma, sit with us, but I'll do his bath and bed myself tonight.\"","best":true},{"text":"\"Sure Ma, you take over, you know better than us anyway.\""}],"relearn":"Welcoming help while keeping your own care tasks lets you stay a present parent, not a sidelined one.","persona":"Vikram","source":"stay hands-on"},
  {"id":"ep2-947","cat":"share-the-care","type":"role-play","hook":"Your partner says 'it's just easier if I do everything'. You want to take a real share.","setup":"You respond:","yourLine":[{"text":"\"Easier now, harder forever. Give me the school-run and bedtimes to fully own.\"","best":true},{"text":"\"Okay, you run it, just shout if you need a hand sometime.\""}],"relearn":"Taking whole tasks to own beats letting 'it's easier' quietly load everything onto one parent.","persona":"Vikram","source":"take a share"},
  {"id":"ep2-948","cat":"share-the-care","type":"spot","hook":"Spot the two lines that quietly leave the care on one parent.","scene":[{"id":"a","text":"'I've got bath and bedtime tonight'","trick":false},{"id":"b","text":"'Just tell me whenever you need help'","trick":true},{"id":"c","text":"'I booked his check-up for Friday'","trick":false},{"id":"d","text":"'You're better at this, you do it'","trick":true},{"id":"e","text":"'I'll take Monday and Tuesday runs'","trick":false}],"why":"'Tell me when you need help' and 'you're better, you do it' both keep her the manager who notices and decides.","relearn":"Catch helper-talk: owning whole tasks shares care; 'tell me' and 'you do it' don't.","persona":"Vikram","source":"spot the helper lines"},
  {"id":"ep2-949","cat":"share-the-care","type":"spot","hook":"Spot the two excuses for opting out of hands-on care.","scene":[{"id":"a","text":"'I provide, so feeds are her job'","trick":true},{"id":"b","text":"'I'll learn the routine by doing it'","trick":false},{"id":"c","text":"'Men's hands are clumsy with nappies'","trick":true},{"id":"d","text":"'I'll own bath time this month'","trick":false},{"id":"e","text":"'Either of us can do the night feed'","trick":false}],"why":"'I provide, so feeds are hers' and 'men's hands are clumsy' are excuses; providing isn't the whole job and care is learned by doing.","relearn":"Catch opt-out excuses: providing and 'clumsy hands' don't excuse skipping hands-on care.","persona":"Vikram","source":"spot the excuses"},
  {"id":"ep2-950","cat":"share-the-care","type":"spot","hook":"In this 'shared' setup, spot the two things that keep it one-parent-run.","scene":[{"id":"a","text":"Both parents on the school contact list","trick":false},{"id":"b","text":"Only Mum knows the bedtime steps","trick":true},{"id":"c","text":"They alternate the night wake-ups","trick":false},{"id":"d","text":"Dad waits for a list before acting","trick":true},{"id":"e","text":"Either can take a day off solo","trick":false}],"why":"Only Mum knowing bedtime and Dad waiting for a list mean care still runs through one parent, not two.","relearn":"Catch the single-points-of-failure: shared care needs both to know the routines and act without a list.","persona":"any","source":"spot one-parent-run"},
  {"id":"ep2-951","cat":"share-the-care","type":"spot","hook":"Spot the two 'fun dad' moves that leave the hard care on her.","scene":[{"id":"a","text":"Plays all evening, skips the feeds","trick":true},{"id":"b","text":"Takes the kids the whole Sunday","trick":false},{"id":"c","text":"Naps while she manages both kids","trick":true},{"id":"d","text":"Owns the park-then-bath shift","trick":false},{"id":"e","text":"Cooks and clears up after meals","trick":false}],"why":"Playing but skipping feeds, and napping while she manages both, hand the real care back to her; sharing means taking the hard bits too.","relearn":"Catch 'fun dad': sharing care means the feeds and clean-up, not only the play.","persona":"Vikram","source":"spot fun-dad"},
  {"id":"ep2-952","cat":"share-the-care","type":"spot","hook":"Spot the two myths hiding in this chat about a new baby.","scene":[{"id":"a","text":"'A baby just needs its mother early on'","trick":true},{"id":"b","text":"'I can do bottle feeds and nappies'","trick":false},{"id":"c","text":"'Only breastfeeding is truly mum-only'","trick":false},{"id":"d","text":"'Soothing is a mother's natural instinct'","trick":true},{"id":"e","text":"'I'll take the early-morning shift'","trick":false}],"why":"'Babies just need mum early' and 'soothing is mum's instinct' are myths; babies bond with both, and soothing is learned by doing.","relearn":"Catch the baby myths: both parents bond from birth and soothing is practice, not instinct.","persona":"any","source":"spot baby myths"},
  {"id":"ep2-953","cat":"share-the-care","type":"spot","hook":"Spot the two lines that frame a father's care as a favour, not his job.","scene":[{"id":"a","text":"'I'm just helping the wife today'","trick":true},{"id":"b","text":"'I've got the kids, you go rest'","trick":false},{"id":"c","text":"'Babysitting my own two this evening'","trick":true},{"id":"d","text":"'Their appointments are mine to book'","trick":false},{"id":"e","text":"'I run our bedtime routine solo'","trick":false}],"why":"'Helping the wife' and 'babysitting my own' frame care as a favour; caring for your own kids is parenting, your job too.","relearn":"Catch favour-framing: parenting your own children is never 'helping' or 'babysitting'.","persona":"Vikram","source":"spot favour-framing"},
  {"id":"ep2-954","cat":"share-the-care","type":"spot","hook":"Spot the two things that quietly make her the only backup when plans change.","scene":[{"id":"a","text":"Only her number on every form","trick":true},{"id":"b","text":"Both know the paediatrician's name","trick":false},{"id":"c","text":"Sick-day leave always falls to her","trick":true},{"id":"d","text":"They split the school week by days","trick":false},{"id":"e","text":"Either can prep and pack the bag","trick":false}],"why":"Her on every form and always taking the sick day make her the default backup; shared care spreads the contacts and the time off.","relearn":"Catch the default-backup traps: share the forms and the sick days so either parent can cover.","persona":"any","source":"spot default backup"},
  {"id":"ep2-955","cat":"share-the-care","type":"reflect","hook":"Lensy: caring for your own child is just your job, never a favour you do your partner. Sit right?","prompt":"What do you think?","options":["Sits right","It's my job","Not a favour"],"affirm":"Shared care is simply both parents doing their own job, not one doing the other a favour.","relearn":"Caring for your own child is your job, not a favour to your partner.","persona":"any","source":"not a favour"},
  {"id":"ep2-956","cat":"share-the-care","type":"reflect","hook":"Lensy: which part of the care feels most 'defaulted' to one of you right now?","prompt":"Sit with it:","options":["The nights","The appointments","The school-run","The daily feeds"],"affirm":"Naming the part that's defaulted is the first step; you can pick it up and own it together.","relearn":"Spotting the defaulted task lets you rebalance it into an owned, shared share.","persona":"any","source":"name the default"},
  {"id":"ep2-957","cat":"share-the-care","type":"reflect","hook":"Lensy: if your partner left for a week tomorrow, which task would you feel least ready for?","prompt":"Be honest:","options":["Bedtime routine","Doctor visits","Packing for school","Soothing at night"],"affirm":"Whatever you picked is just a skill you haven't practised yet, not one only she can do.","relearn":"A task you feel unready for is unpractised, not mother-only; you can learn it.","persona":"Vikram","source":"ready to solo"},
  {"id":"ep2-958","cat":"share-the-care","type":"reflect","hook":"Lensy: think of one care task you'd like to fully own from now on. Which is it?","prompt":"Pick one:","options":["Mornings and school-run","Bath and bedtime","Health and appointments","Night feeds"],"affirm":"Owning even one whole domain end to end shifts you from helper to genuine co-parent.","relearn":"Owning a full domain, not scattered chores, is what makes care truly shared.","persona":"Vikram","source":"pick a domain"},
  {"id":"ep2-959","cat":"share-the-care","type":"reflect","hook":"Lensy: what's one moment from this week where you were the parent your child really needed?","prompt":"Recall it:","options":["A night I settled them","A meal I made them","A worry I eased","A trip I handled"],"affirm":"That moment is proof your hands-on presence matters as much as anything you provide.","relearn":"Your everyday presence and care matter as much as providing; both are your job.","persona":"Vikram","source":"presence matters"},
  {"id":"ep2-960","cat":"share-the-care","type":"reflect","hook":"Lensy: an uneven split isn't a failing; naming it together is the work. How does that land?","prompt":"What comes up?","options":["A relief","Feels fair","Worth a talk","Let's rebalance"],"affirm":"You're not blaming anyone; you're just choosing to share the care more fairly from here.","relearn":"An unequal split is common, not a failing; naming and rebalancing it together is the work.","persona":"any","source":"no blame"},
  {"id":"ep2-961","cat":"share-the-care","type":"reflect","hook":"Lensy: when does a fair split tend to snap back to one parent in your week?","prompt":"Notice it:","options":["After a work crunch","On weekends","When relatives visit","When someone's ill"],"affirm":"Spotting when it slips lets you protect your owned shifts exactly when defaults pull hardest.","relearn":"Defaults snap back at predictable moments; spotting them helps you hold your share.","persona":"any","source":"when it slips"},
  {"id":"ep2-1350","type":"branch","persona":"Vikram","source":"fair-start tool","hook":"A new baby is weeks away. You want a concrete way to set up a fair split, not just intentions.","options":[{"text":"List every newborn task and the worry, then each pick domains to own","consequence":"Fair becomes a map you both built.","outcome":"mapped","best":true},{"text":"Decide you'll 'pitch in a lot' once the baby's here","consequence":"'Pitching in' leaves your partner the manager who assigns tasks."}],"debrief":"List the tasks and the worry, then each own domains — a built plan beats a vague 'pitch in'.","relearn":"Map newborn tasks and the worry, then each own domains; 'pitching in' keeps one the manager.","cat":"tools-and-help"},
  {"id":"ep2-1351","type":"branch","persona":"Divya","source":"monthly check-in","hook":"It's three months since you split the parenting. You're not sure it's still fair.","options":[{"text":"Hold a calm monthly check-in to name what's drifted and re-trade domains","consequence":"You catch drift before it hardens.","outcome":"checked-in","best":true},{"text":"Wait until someone snaps to talk about it","consequence":"Waiting for a blow-up means the drift is already entrenched."}],"debrief":"A calm monthly check-in catches drift early; waiting for a blow-up means it's already entrenched.","relearn":"Schedule a calm monthly check-in to name drift and re-trade domains, not wait for a blow-up.","cat":"tools-and-help"},
  {"id":"ep2-1352","type":"branch","persona":"Vikram","source":"shared calendar","hook":"Appointments and class events keep landing only in your partner's head, catching you off guard.","options":[{"text":"Put every kid date in one shared calendar you both add to and check","consequence":"The schedule lives in one place, not one head.","outcome":"shared-cal","best":true},{"text":"Ask your partner to text you a reminder each time","consequence":"Reminders keep your partner tracking it all; you just execute."}],"debrief":"A shared calendar you both own moves tracking out of one head; reminders keep one the manager.","relearn":"Use one shared calendar you both keep, so the schedule isn't held in one head.","cat":"tools-and-help"},
  {"id":"ep2-1353","type":"branch","persona":"Meena","source":"domain swap","hook":"You own all the health admin; your partner owns school. You're both stretched thin in your lane.","options":[{"text":"Swap a domain for a month so each learns the other's load","consequence":"Each finally sees the work the other carries.","outcome":"swapped","best":true},{"text":"Keep your lanes fixed forever","consequence":"Fixed lanes mean neither sees or can cover the other's load."}],"debrief":"Swapping a domain now and then builds backup and respect; fixed lanes mean neither can cover.","relearn":"Swap domains now and then so each learns the other's load and can cover it, not lock lanes.","cat":"tools-and-help"},
  {"id":"ep2-1411","type":"branch","persona":"Vikram","source":"default snap-back","hook":"Your second baby arrives and the load quietly slides back to your partner, like the first time.","options":[{"text":"Name that the default is creeping back and re-claim your domains","consequence":"Naming it early lets you both reset.","outcome":"reset","best":true},{"text":"Tell yourself it's only temporary while it's hectic","consequence":"'Only temporary' is how the old default becomes permanent again."}],"debrief":"Defaults snap back hardest with each baby; name it and re-claim domains before 'temporary' sticks.","relearn":"Name the default creeping back with a new baby and re-claim domains, not 'temporary'.","cat":"tools-and-help"},
  {"id":"ep2-1354","type":"branch","persona":"any","source":"grandparent help","hook":"Grandparents at home keep doing things only with your partner, assuming care is 'her' department.","options":[{"text":"Kindly loop them in: you both parent, so coordinate with both","consequence":"The household learns you both own the care.","outcome":"looped-in","best":true},{"text":"Let them keep routing everything to your partner","consequence":"Routing it all to one parent rebuilds the default you want to change."}],"debrief":"Warmly tell grandparents you both own the care, so they coordinate with both — not just one.","relearn":"Loop grandparents in to coordinate care with both parents, not route everything to one.","cat":"tools-and-help"},
  {"id":"ep2-1355","type":"branch","persona":"Divya","source":"load audit","hook":"You suspect you carry far more invisible kid-admin, but your partner thinks it's even.","options":[{"text":"Write down a week of who-noticed-and-decided-what, then read it together","consequence":"The written week settles it with evidence.","outcome":"audited","best":true},{"text":"Keep debating from memory who does more","consequence":"Debating from memory just hardens both positions and changes nothing."}],"debrief":"Log a real week of who noticed and decided what; the record settles 'it's even' better than memory.","relearn":"Log a week of who noticed and decided, then read it together, not argue fairness from memory.","cat":"tools-and-help"},
  {"id":"ep2-1356","type":"branch","persona":"Vikram","source":"stop assigning","hook":"You keep waiting for your partner to tell you what the kids need before you act.","options":[{"text":"Own one domain fully so you notice and decide, not wait to be told","consequence":"You become a co-manager, not a helper on call.","outcome":"owned","best":true},{"text":"Ask 'just tell me what to do and I'll do it'","consequence":"'Just tell me' keeps your partner the manager tracking it all."}],"debrief":"Own a domain end-to-end so you notice and decide; 'just tell me' keeps your partner the manager.","relearn":"Own a domain so you notice and decide yourself; 'just tell me' keeps your partner the manager.","cat":"tools-and-help"},
  {"id":"ep2-1357","type":"branch","persona":"Meena","source":"route burnout","hook":"Your partner has run on empty for weeks, snapping and exhausted by the parenting load.","options":[{"text":"Treat it as real burnout: take over domains and reach support together","consequence":"You protect your partner and steady the home.","outcome":"supported","best":true},{"text":"Suggest they just 'toughen up' and push on","consequence":"Telling a depleted parent to toughen up risks their health."}],"debrief":"Persistent depletion is real burnout — shift domains and reach Looking After You, or Tele-MANAS 14416.","relearn":"Treat persistent depletion as real burnout; rebalance and reach support, not 'toughen up'.","cat":"tools-and-help"},
  {"id":"ep2-1358","type":"branch","persona":"Vikram","source":"review as kids grow","hook":"Your split worked for a toddler, but now there's homework, tuitions and clubs, and it feels lopsided.","options":[{"text":"Re-map the older-kid tasks and re-divide the load","consequence":"The split keeps pace with the kids' changing lives.","outcome":"remapped","best":true},{"text":"Keep the toddler-era split since it 'worked before'","consequence":"A toddler-era split can't hold school-age work; it piles onto one."}],"debrief":"Each new stage adds tasks; re-map and re-divide them or the load piles onto one parent.","relearn":"Re-map the load at each stage; a split that fit toddlers won't fit school-age kids.","cat":"tools-and-help"},
  {"id":"ep2-1359","type":"branch","persona":"any","source":"praise trap","hook":"Relatives keep praising you lavishly for basic care your partner does daily without a word.","options":[{"text":"Redirect it: 'we both do this — it's parenting, not a favour'","consequence":"You reset the bar so basic care isn't heroics.","outcome":"redirected","best":true},{"text":"Soak up the praise as your due for 'helping out'","consequence":"Praise for 'helping' frames your own parenting as a favour."}],"debrief":"Redirect over-praise for basic care; calling it 'helping' frames your parenting as a favour.","relearn":"Redirect lavish praise for basic care — it's your job, not a favour you do by 'helping out'.","cat":"tools-and-help"},
  {"id":"ep2-1360","type":"branch","persona":"Divya","source":"ask vs own","hook":"Your partner says 'just delegate to me' — but building the to-do list is itself exhausting you.","options":[{"text":"Hand over whole domains to own, not a list of tasks to assign","consequence":"The mental load of listing lifts off you too.","outcome":"handed-over","best":true},{"text":"Keep writing the task lists for them to action","consequence":"Writing the lists keeps the heaviest part — the tracking — on you."}],"debrief":"Hand over whole domains, not tasks-to-assign; else the tracking that tires you most stays with you.","relearn":"Hand over whole domains to own; writing the task list keeps the tracking load on you.","cat":"tools-and-help"},
  {"id":"ep2-1361","type":"branch","persona":"Vikram","source":"model for kids","hook":"Your kids only ever see their mother pack bags, cook and plan. You want them to see shared care.","options":[{"text":"Do visible care in front of them as your normal job","consequence":"Kids grow up seeing care as everyone's work.","outcome":"modelled","best":true},{"text":"Keep care behind the scenes since the result's the same","consequence":"Hidden care teaches kids the old divide; they copy what they see."}],"debrief":"Do care visibly so kids see it as everyone's job; hidden care quietly teaches the old divide.","relearn":"Do visible care in front of the kids on purpose; they learn the divide from what they see.","cat":"tools-and-help"},
  {"id":"ep2-1362","type":"branch","persona":"Meena","source":"first-week setup","hook":"You're back at work after parental leave, worried the routines you built will collapse onto one.","options":[{"text":"Write down each owned domain and the handover before leave ends","consequence":"The routines survive the return to work.","outcome":"documented","best":true},{"text":"Assume you'll both just remember how it ran","consequence":"'We'll remember' lets the working parent's domains slide back."}],"debrief":"Write down owned domains and handovers before leave ends so they survive the return to work.","relearn":"Document owned domains and handovers before leave ends; 'we'll remember' lets the load slide back.","cat":"tools-and-help"},
  {"id":"ep2-1363","type":"branch","persona":"any","source":"tool not scorecard","hook":"Your fairness chats keep turning into tallying who did more nappies this week.","options":[{"text":"Check each owns whole domains and flexes, instead of counting tasks","consequence":"Fairness becomes ownership, not a tense scoreboard.","outcome":"reframed","best":true},{"text":"Keep a running tally of every chore each did","consequence":"A chore tally turns parenting into a scorecard and breeds resentment."}],"debrief":"Measure fairness by owned domains and flexibility, not a nappy tally that becomes a scoreboard.","relearn":"Check each owns whole domains and flexes, rather than tallying every chore into a scoreboard.","cat":"tools-and-help"},
  {"id":"ep2-1364","type":"match","persona":"any","source":"tool to job","hook":"Match each fair-parenting tool to the job it does.","pairs":[{"left":"The task-and-load map","right":"See and split everything fairly"},{"left":"A shared family calendar","right":"Both hold the schedule"},{"left":"A monthly parenting check-in","right":"Rebalance as life changes"},{"left":"Owned whole domains","right":"End the 'wait to be told' habit"},{"left":"A domain swap now and then","right":"Build backup and see each other's load"}],"relearn":"Map, shared calendar, check-in, owned domains and a domain swap each do a distinct job in fair parenting.","cat":"tools-and-help"},
  {"id":"ep2-1365","type":"match","persona":"any","source":"problem to fix","hook":"Match each common snag to the tool that fixes it.","pairs":[{"left":"Split drifted back to one parent","right":"A regular rebalancing check-in"},{"left":"Appointments only in one head","right":"One shared calendar you both keep"},{"left":"You keep waiting to be told","right":"Take a whole domain to own"},{"left":"Arguing fairness from memory","right":"A written week-long load audit"},{"left":"Persistent burnout from the load","right":"Reach Tele-MANAS 14416"}],"relearn":"Each parenting snag has a tool: a check-in, a shared calendar, owned domains, a load audit, or support.","cat":"tools-and-help"},
  {"id":"ep2-1366","type":"match","persona":"Vikram","source":"helper to owner","hook":"Match each 'helper' line to the 'owner' move that replaces it.","pairs":[{"left":"'Just tell me what to do'","right":"'I'll own health end-to-end'"},{"left":"'I babysat the kids today'","right":"'I parented our kids today'"},{"left":"'Remind me when it's due'","right":"'It's on my shared calendar'"},{"left":"'I helped her out a lot'","right":"'We split it as equals'"},{"left":"'You're better at this stuff'","right":"'I'll learn it by doing it'"}],"relearn":"Each helper line has an owner version: own a domain, call it parenting, track it, split it, learn by doing.","cat":"tools-and-help"},
  {"id":"ep2-1367","type":"match","persona":"any","source":"visible vs invisible","hook":"Match each parenting job to whether it's visible care or the invisible mental load.","pairs":[{"left":"Changing a nappy","right":"Visible care, anyone can see it"},{"left":"Remembering the next vaccine is due","right":"Invisible load, runs in the background"},{"left":"Packing the school bag","right":"Visible care, a clear task"},{"left":"Noticing shoes are outgrown","right":"Invisible load, the tracking work"},{"left":"Booking the dentist","right":"Invisible load, the planning work"}],"relearn":"Some jobs are visible care; the remembering, noticing and planning are the invisible load — both get shared.","cat":"tools-and-help"},
  {"id":"ep2-1368","type":"match","persona":"any","source":"check-in cadence","hook":"Match each parenting milestone to the check-in it calls for.","pairs":[{"left":"New baby arrives","right":"Re-map the whole split from scratch"},{"left":"Parent returns to work","right":"Document domains and handovers"},{"left":"Child starts school","right":"Add the new school admin to the split"},{"left":"One parent is depleting","right":"Shift domains and reach support"},{"left":"A quiet ordinary month","right":"A short routine rebalancing check-in"}],"relearn":"Each milestone calls for its own check-in: re-map, document, add new admin, shift load, or routine rebalance.","cat":"tools-and-help"},
  {"id":"ep2-1369","type":"match","persona":"any","source":"myth to tool","hook":"Match each parenting myth to the tool that quietly disproves it.","pairs":[{"left":"'She's just naturally better at it'","right":"A domain swap proves it's practice"},{"left":"'We split it once, so it's fair'","right":"A rebalancing check-in catches drift"},{"left":"'It's all even, I'm sure'","right":"A written load audit shows the truth"},{"left":"'I help plenty when asked'","right":"Owning a domain ends the asking"},{"left":"'Coping alone shows I'm strong'","right":"Tele-MANAS 14416 is for real burnout"}],"relearn":"A swap, a check-in, an audit, owned domains and support each disprove a common fair-parenting myth.","cat":"tools-and-help"},
  {"id":"ep2-1370","type":"match","persona":"any","source":"domain to owner-task","hook":"Match each owned domain to what owning it actually means end-to-end.","pairs":[{"left":"Own 'health'","right":"Track jabs, book and attend, refill medicine"},{"left":"Own 'school'","right":"Hold the calendar, forms, fees and homework"},{"left":"Own 'food'","right":"Plan meals, shop, cook, watch what's running low"},{"left":"Own 'sleep'","right":"Run the bedtime routine and the night wakings"},{"left":"Own 'clothes'","right":"Notice sizes, buy ahead, sort the laundry"}],"relearn":"Owning a domain means the whole loop — tracking, deciding and doing — not just the visible task.","cat":"tools-and-help"},
  {"id":"ep2-1371","type":"reflect","persona":"any","source":"tools recap","hook":"Lensy: the toolkit is a map, a shared calendar and a regular check-in. Which feels most useful to you?","prompt":"Which would help most?","options":["The task-and-load map","The shared calendar","The regular check-in"],"affirm":"Any of these is a real start — a map, a shared calendar or a check-in each moves you toward a fairer split.","relearn":"The map, the shared calendar and the regular check-in are the core tools; any one is a real start.","cat":"tools-and-help"},
  {"id":"ep2-1372","type":"reflect","persona":"any","source":"difficulty is normal","hook":"Lensy: keeping a fair split going takes ongoing effort for everyone — that difficulty is normal, not a sign to quit. Sit with that?","prompt":"How does that land?","options":["It's reassuring","Makes it feel workable","Good to hear it's normal"],"affirm":"It's true: the difficulty is normal and workable with tools and check-ins — never a reason to give up on fair.","relearn":"Keeping equal parenting going is ongoing effort for all; the difficulty is normal and workable, not a quit signal.","cat":"tools-and-help"},
  {"id":"ep2-1373","type":"reflect","persona":"Divya","source":"naming not blame","hook":"Lensy: an unequal split is common, not a failing — naming it together is the work, not blaming anyone. Ready to name it?","prompt":"What's your honest take?","options":["I can name it","No blame, just fix it","It's common, not a flaw"],"affirm":"Exactly — an unequal split is common, not a failing; naming and rebalancing it together is the actual work.","relearn":"An unequal split is common, not a failing; naming and rebalancing it together — without blame — is the work.","cat":"tools-and-help"},
  {"id":"ep2-1374","type":"reflect","persona":"any","source":"over-the-years","hook":"Lensy: rebalancing isn't a one-time fix — it's a practice you maintain over the years as the kids grow. Picture that?","prompt":"What do you think?","options":["A practice, not a fix","I can keep it up","Makes sense over years"],"affirm":"Yes — rebalancing is a maintained practice over the years, not a single fix; you revisit it as life changes.","relearn":"Rebalancing the split is a maintained, over-the-years practice, not a one-time fix done and forgotten.","cat":"tools-and-help"},
  {"id":"ep2-1375","type":"reflect","persona":"any","source":"burnout not weakness","hook":"Lensy: parental burnout is real, not weakness — reaching for support is strength, not failure. How does that sit?","prompt":"What's your take?","options":["Reaching out is strength","It's real, not weakness","Good to know support exists"],"affirm":"Right — parental burnout is real, not weakness; persistent depletion routes to Looking After You, or Tele-MANAS 14416.","relearn":"Parental burnout is real, not weakness; persistent depletion routes to Looking After You, or Tele-MANAS 14416.","cat":"tools-and-help"},
  {"id":"ep2-1376","type":"reflect","persona":"any","source":"set the tone early","hook":"Lensy: tools work best when you set the tone early and keep supporting, not undermining, each other. Feel ready to set it?","prompt":"Where are you?","options":["Ready to set the tone","We support each other","Early is better"],"affirm":"Tools support a fair-from-day-one path: set the tone early and keep backing each other, not undercutting it.","relearn":"Tools work best set early, with partners supporting — not undermining — each other on a fair-from-day-one path.","cat":"tools-and-help"},
  {"id":"ep2-1377","type":"reflect","persona":"any","source":"equipped","hook":"Lensy: map it, own domains, check in, route burnout to support — that's the whole kit. Feel equipped?","prompt":"How equipped do you feel?","options":["Equipped","I've got the kit","Ready to use it"],"affirm":"You hold the kit: map the load, own whole domains, check in to rebalance, and route real burnout to support.","relearn":"The kit: map the load, own whole domains, check in to rebalance, and route real burnout to support.","cat":"tools-and-help"},
  {"id":"ep2-1378","type":"reflect","persona":"any","source":"tools serve family","hook":"Lensy: every tool here serves the same goal — a sustainable, fair split that's better for the whole family. Worth it?","prompt":"What do you feel?","options":["Worth the effort","Better for everyone","A goal we share"],"affirm":"Every tool here serves a sustainable, fair split — one that's genuinely better for the kids and both of you.","relearn":"The tools all serve one goal: a sustainable, fair split that's better for the kids and both parents alike.","cat":"tools-and-help"},
  {"id":"ep2-1379","type":"strike-rewrite","persona":"any","source":"tools too rigid","hook":"\"All these maps and check-ins make parenting feel like a corporate project, not a family.\"","myth":{"un":"All these maps and check-ins make parenting feel like a corporate project, not a family.","re":"The tools just make the invisible load visible so it can be shared; they free you to be present, not rigid.","why":"Naming who-does-what removes the daily friction, leaving more space for the warmth."},"relearn":"Fair-parenting tools make the hidden load visible so it can be shared and you can be more present, not rigid.","cat":"tools-and-help"},
  {"id":"ep2-1380","type":"strike-rewrite","persona":"Vikram","source":"set once","hook":"\"We agreed a fair split once, so we're sorted for good.\"","myth":{"un":"We agreed a fair split once, so we're sorted for good.","re":"Rebalancing is a practice you maintain over the years; a split set once quietly drifts back to one parent.","why":"Kids' needs and your schedules keep changing, so the split has to be revisited to stay fair."},"relearn":"A fair split set once drifts back over time; rebalancing is a maintained practice as needs keep changing.","cat":"tools-and-help"},
  {"id":"ep2-1381","type":"strike-rewrite","persona":"any","source":"asking is anti-men","hook":"\"Asking dads to use 'fair-split tools' is just nagging men into extra chores.\"","myth":{"un":"Asking dads to use 'fair-split tools' is just nagging men into extra chores.","re":"The tools help fathers claim real ownership and bond with their kids — that's pro-men, not a chore list.","why":"Owning whole domains builds a father's confidence and closeness, which is a gain, not a burden."},"relearn":"Fair-split tools help fathers claim ownership and bond; that's pro-men and a gain, not nagging into chores.","cat":"tools-and-help"},
  {"id":"ep2-1382","type":"strike-rewrite","persona":"Divya","source":"needing tools = failing","hook":"\"If we need tools and check-ins to share parenting, we must be bad at it.\"","myth":{"un":"If we need tools and check-ins to share parenting, we must be bad at it.","re":"Using tools is what good co-parents do; an unequal split is common, not a failing, and tools are how you fix it.","why":"Defaults pull hard toward one parent, so naming and rebalancing on purpose is skill, not weakness."},"relearn":"Needing tools isn't failing; an unequal split is common, and using tools to rebalance is exactly the skill.","cat":"tools-and-help"},
  {"id":"ep2-1383","type":"strike-rewrite","persona":"any","source":"burnout = weak","hook":"\"A good parent should be able to cope with the load without asking for help.\"","myth":{"un":"A good parent should be able to cope with the load without asking for help.","re":"Parental burnout is real, not weakness; reaching Looking After You, or Tele-MANAS 14416, is strength.","why":"Persistent depletion is a health issue that rest and support fix, not a character test to pass alone."},"relearn":"Parental burnout is real, not weakness; reaching Looking After You, or Tele-MANAS 14416, is the strong move.","cat":"tools-and-help"},
  {"id":"ep2-1384","type":"strike-rewrite","persona":"Vikram","source":"delegating is sharing","hook":"\"I share the load — my partner just tells me what to do and I do it.\"","myth":{"un":"I share the load — my partner just tells me what to do and I do it.","re":"Being told tasks isn't sharing; sharing means owning whole domains so you do the noticing and planning too.","why":"If one parent still tracks and assigns everything, they remain the manager carrying the real load."},"relearn":"Doing tasks when told isn't sharing; owning whole domains, including the noticing and planning, is.","cat":"tools-and-help"},
  {"id":"ep2-1385","type":"strike-rewrite","persona":"any","source":"tools steal spontaneity","hook":"\"Planning the split ahead kills the natural, spontaneous side of being a parent.\"","myth":{"un":"Planning the split ahead kills the natural, spontaneous side of being a parent.","re":"Owning domains is about responsibility, not a rigid script; you still flex for each other day to day.","why":"Fair sharing is ownership plus flexibility, so the plan handles the load and leaves room to be spontaneous."},"relearn":"Owning domains is responsibility plus flexibility, not a rigid script; you still flex and stay spontaneous.","cat":"tools-and-help"},
  {"id":"ep2-1386","type":"role-play","persona":"Vikram","source":"claim a domain","hook":"Your partner is drowning in kid-admin. You want to take real ownership, not just offer to help.","setup":"Claim a domain:","yourLine":[{"text":"\"Let me fully own health from now on — jabs, doctors, medicines — so it's off your plate for good.\"","best":true},{"text":"\"Tell me what doctor stuff needs doing and I'll handle it.\""}],"relearn":"Claiming a whole domain end-to-end lifts the tracking off your partner, not just the odd assigned task.","cat":"tools-and-help"},
  {"id":"ep2-1387","type":"role-play","persona":"Divya","source":"ask for the check-in","hook":"You feel the split has drifted but raising it keeps feeling like a complaint. You want to open a calm check-in.","setup":"Open the check-in:","yourLine":[{"text":"\"Can we do a quick monthly check-in on who's carrying what, so we catch drift before it builds up?\"","best":true},{"text":"\"I feel like I'm doing everything again, but never mind.\""}],"relearn":"Proposing a regular calm check-in catches drift early and keeps it a shared task, not a stored-up complaint.","cat":"tools-and-help"},
  {"id":"ep2-1388","type":"role-play","persona":"Vikram","source":"set tone with grandparents","hook":"Your mother keeps handing all the baby-care questions to your wife in front of you. You want to gently shift it.","setup":"Gently redirect:","yourLine":[{"text":"\"Ma, ask me too — I do his feeds and naps as much as she does; we share all of it.\"","best":true},{"text":"\"She'll know, ask her — she handles the baby stuff.\""}],"relearn":"Telling family to ask you too makes both parents the go-to, instead of routing all care to the mother.","cat":"tools-and-help"},
  {"id":"ep2-1389","type":"role-play","persona":"Meena","source":"name burnout kindly","hook":"Your partner is exhausted and short-tempered from the load but won't admit they're struggling. You want to open the door.","setup":"Offer support, not judgement:","yourLine":[{"text":"\"You sound burnt out, and that's real — let me take some domains, and we can reach support together.\"","best":true},{"text":"\"Everyone's tired, you'll just have to power through it.\""}],"relearn":"Naming burnout as real and offering to take load plus reach support beats telling a depleted parent to push on.","cat":"tools-and-help"},
  {"id":"ep2-1390","type":"role-play","persona":"Vikram","source":"fair from day one","hook":"You and your partner are expecting your first child and planning how you'll parent. You want to set fairness as the default.","setup":"Set it from the start:","yourLine":[{"text":"\"Let's each own real domains from day one and check in monthly, so fair is our default, not a fight.\"","best":true},{"text":"\"Let's just see how it shakes out once the baby's here.\""}],"relearn":"Agreeing owned domains and a monthly check-in from day one makes fairness the default instead of a recurring fight.","cat":"tools-and-help"},
  {"id":"ep2-1391","type":"role-play","persona":"any","source":"decline the scorecard","hook":"A fairness chat is sliding into 'but I did three nappies more than you'. You want to steer it back to ownership.","setup":"Steer off the scoreboard:","yourLine":[{"text":"\"Let's not count nappies — let's check each of us still owns whole domains and can flex for the other.\"","best":true},{"text":"\"Fine, I'll start writing down every single thing I do.\""}],"relearn":"Steering a fairness talk to owned domains and flexibility beats turning it into a chore-by-chore scoreboard.","cat":"tools-and-help"},
  {"id":"ep2-1392","type":"role-play","persona":"Vikram","source":"stop saying babysitting","hook":"A colleague jokes 'babysitting the kids this weekend?'. You want to reframe it without making it awkward.","setup":"Reframe it lightly:","yourLine":[{"text":"\"It's not babysitting when they're mine — I'm just parenting my own kids, same as their mum.\"","best":true},{"text":"\"Ha, yeah, on dad duty, giving the wife a break.\""}],"relearn":"Naming that caring for your own kids is parenting, not babysitting, resets the favour framing in one line.","cat":"tools-and-help"},
  {"id":"ep2-1393","type":"role-play","persona":"Divya","source":"hand over not delegate","hook":"Your partner says 'just make me a list and I'll do it', but the list itself is the exhausting part. You want to hand over real ownership.","setup":"Hand over, don't delegate:","yourLine":[{"text":"\"Instead of a list, take school fully — track the dates, forms and fees yourself, so I stop holding it.\"","best":true},{"text":"\"Okay, I'll write you a list every Sunday night.\""}],"relearn":"Handing over a whole domain to track and run beats being asked for a list, which keeps the load on you.","cat":"tools-and-help"},
  {"id":"ep2-1394","type":"sort","persona":"any","source":"supports vs undermines","hook":"Sort each habit: does it support a fair split, or quietly undermine it?","items":[{"id":"a","text":"A monthly rebalancing check-in"},{"id":"b","text":"Both owning whole domains"},{"id":"c","text":"One shared calendar you both keep"},{"id":"d","text":"Praising dad for the bare minimum"},{"id":"e","text":"Gatekeeping so only mum 'does it right'"},{"id":"f","text":"Waiting to be told every task"}],"bins":[{"id":"support","label":"Supports a fair split","valence":"pos"},{"id":"undermine","label":"Undermines it","valence":"neg"}],"key":{"a":"support","b":"support","c":"support","d":"undermine","e":"undermine","f":"undermine"},"relearn":"Check-ins, owned domains and a shared calendar support a fair split; gatekeeping, bare-minimum praise and waiting undermine it.","cat":"tools-and-help"},
  {"id":"ep2-1395","type":"sort","persona":"any","source":"visible vs mental load","hook":"Sort each job: is it visible care, or the invisible mental load?","items":[{"id":"a","text":"Giving the baby a bath"},{"id":"b","text":"Remembering the next vaccine date"},{"id":"c","text":"Cooking the kids' dinner"},{"id":"d","text":"Noticing the school shoes are too tight"},{"id":"e","text":"Tracking when nappies are running low"},{"id":"f","text":"Dropping them at school"}],"bins":[{"id":"visible","label":"Visible care","valence":"neutral"},{"id":"mental","label":"Invisible mental load","valence":"tell"}],"key":{"a":"visible","c":"visible","f":"visible","b":"mental","d":"mental","e":"mental"},"relearn":"Baths, cooking and drop-offs are visible care; remembering, noticing and tracking are the invisible load — share both.","cat":"tools-and-help"},
  {"id":"ep2-1396","type":"sort","persona":"any","source":"fix vs practice","hook":"Sort each idea: is it a one-time fix, or an ongoing practice fair parenting needs?","items":[{"id":"a","text":"Agree the split just once and stop"},{"id":"b","text":"Revisit the split at each new stage"},{"id":"c","text":"Assume it'll stay fair on its own"},{"id":"d","text":"Hold a regular rebalancing check-in"},{"id":"e","text":"Re-map tasks when a baby arrives"},{"id":"f","text":"Set it and never look again"}],"bins":[{"id":"ongoing","label":"Ongoing practice","valence":"pos"},{"id":"onetime","label":"One-time-and-forget","valence":"uhoh"}],"key":{"b":"ongoing","d":"ongoing","e":"ongoing","a":"onetime","c":"onetime","f":"onetime"},"relearn":"Fair parenting is an ongoing practice — revisit, check in, re-map; set-once-and-forget lets the default return.","cat":"tools-and-help"},
  {"id":"ep2-1397","type":"sort","persona":"Vikram","source":"owning vs helping","hook":"Sort each line: is it owning the load, or just helping when asked?","items":[{"id":"a","text":"'I track and book all the dentist visits'"},{"id":"b","text":"'I do whatever she puts on my list'"},{"id":"c","text":"'I run bedtime start to finish'"},{"id":"d","text":"'I help out when she's overwhelmed'"},{"id":"e","text":"'I notice when supplies run low and restock'"},{"id":"f","text":"'I step in if she asks me to'"}],"bins":[{"id":"owning","label":"Owning a domain","valence":"pos"},{"id":"helping","label":"Helping when asked","valence":"uhoh"}],"key":{"a":"owning","c":"owning","e":"owning","b":"helping","d":"helping","f":"helping"},"relearn":"Owning means tracking and running a domain yourself; helping when asked leaves your partner the manager.","cat":"tools-and-help"},
  {"id":"ep2-1398","type":"sort","persona":"any","source":"when to route support","hook":"Sort each situation: a normal rough patch to ride out, or a sign to reach for support?","items":[{"id":"a","text":"A hard week after a new baby"},{"id":"b","text":"Weeks of exhaustion and dread that won't lift"},{"id":"c","text":"Feeling tired but bouncing back by the weekend"},{"id":"d","text":"Losing interest in the kids and yourself"},{"id":"e","text":"A tough day that a rest fixes"},{"id":"f","text":"Persistent low mood that's not shifting"}],"bins":[{"id":"normal","label":"Normal rough patch","valence":"neutral"},{"id":"support","label":"Reach for support","valence":"tell"}],"key":{"a":"normal","c":"normal","e":"normal","b":"support","d":"support","f":"support"},"relearn":"A hard week or a tired day is normal; weeks of dread, low mood or losing interest signal reaching for support.","cat":"tools-and-help"},
  {"id":"ep2-1399","type":"sort","persona":"any","source":"tool to load type","hook":"Sort each tool: does it mainly map who-does-what, or keep the split fair over time?","items":[{"id":"a","text":"The task-and-load map"},{"id":"b","text":"The monthly rebalancing check-in"},{"id":"c","text":"Listing owned domains up front"},{"id":"d","text":"Re-mapping when a new stage hits"},{"id":"e","text":"A week-long who-decided-what audit"},{"id":"f","text":"Swapping domains now and then"}],"bins":[{"id":"map","label":"Maps who-does-what","valence":"neutral"},{"id":"maintain","label":"Maintains it over time","valence":"pos"}],"key":{"a":"map","c":"map","e":"map","b":"maintain","d":"maintain","f":"maintain"},"relearn":"Mapping tools name who-does-what; check-ins, re-maps and swaps keep the split fair over the years.","cat":"tools-and-help"},
  {"id":"ep2-1412","type":"sort","persona":"any","source":"concrete vs vague","hook":"Sort each plan: a concrete tool that shifts the split, or a vague intention?","items":[{"id":"a","text":"Each picks two domains to own this month"},{"id":"b","text":"'We'll just try to be fairer somehow'"},{"id":"c","text":"Book a monthly check-in in the diary"},{"id":"d","text":"'I'll help out more when I can'"},{"id":"e","text":"Put every kid date on a shared calendar"},{"id":"f","text":"'We'll sort it out as we go along'"}],"bins":[{"id":"concrete","label":"Concrete tool","valence":"pos"},{"id":"vague","label":"Vague intention","valence":"uhoh"}],"key":{"a":"concrete","c":"concrete","e":"concrete","b":"vague","d":"vague","f":"vague"},"relearn":"Owned domains, a booked check-in and a shared calendar are concrete; 'be fairer' or 'help more' are vague wishes that don't shift things.","cat":"tools-and-help"},
  {"id":"ep2-1400","type":"spot","persona":"any","source":"red flags vs sustainable","hook":"Spot the two moves that will quietly let a fair split slide back.","scene":[{"id":"a","text":"Small regular rebalancing check-ins","trick":false},{"id":"b","text":"One grand promise, never revisited","trick":true},{"id":"c","text":"Both owning whole domains over time","trick":false},{"id":"d","text":"Assuming a one-time split holds forever","trick":true},{"id":"e","text":"Re-mapping the load at each new stage","trick":false}],"why":"A one-off promise and assuming the split holds forever both let the default creep back; the rest sustain it.","relearn":"A fair split lasts on regular rebalancing and shared ownership, not a one-off promise left unrevisited.","cat":"tools-and-help"},
  {"id":"ep2-1401","type":"spot","persona":"Vikram","source":"helper-talk red flags","hook":"Spot the two lines that keep one parent the manager instead of sharing the load.","scene":[{"id":"a","text":"'I own health end-to-end'","trick":false},{"id":"b","text":"'Just tell me what to do and I'll do it'","trick":true},{"id":"c","text":"'It's on our shared calendar'","trick":false},{"id":"d","text":"'Remind me each time something's due'","trick":true},{"id":"e","text":"'I track when supplies run low'","trick":false}],"why":"'Just tell me' and 'remind me each time' keep your partner tracking and assigning — they stay the manager.","relearn":"Lines that wait to be told keep one parent the manager; owning and tracking a domain shares the real load.","cat":"tools-and-help"},
  {"id":"ep2-1402","type":"spot","persona":"any","source":"undermining red flags","hook":"Spot the two habits that undermine a fair split.","scene":[{"id":"a","text":"A monthly rebalancing check-in","trick":false},{"id":"b","text":"Gatekeeping so only mum 'does it right'","trick":true},{"id":"c","text":"Both holding the shared calendar","trick":false},{"id":"d","text":"Praising dad for the bare minimum","trick":true},{"id":"e","text":"Each owning whole domains","trick":false}],"why":"Gatekeeping and praising the bare minimum both push the load back onto one parent; the rest keep it shared.","relearn":"Gatekeeping and bare-minimum praise undermine a fair split; check-ins, a shared calendar and owned domains keep it.","cat":"tools-and-help"},
  {"id":"ep2-1403","type":"spot","persona":"any","source":"stale-split red flags","hook":"Spot the two beliefs that let an old split go stale as the kids grow.","scene":[{"id":"a","text":"Revisiting the split as kids change","trick":false},{"id":"b","text":"'The toddler-era split is fine forever'","trick":true},{"id":"c","text":"Both staying hands-on and informed","trick":false},{"id":"d","text":"'We sorted this once, so we're done'","trick":true},{"id":"e","text":"Adding new school admin to the split","trick":false}],"why":"Treating an old split as final ignores new tasks each stage brings; revisiting and staying hands-on keep it fair.","relearn":"An old split goes stale as kids grow; revisit it and both stay hands-on rather than calling it done for good.","cat":"tools-and-help"},
  {"id":"ep2-1404","type":"spot","persona":"any","source":"fake-sharing red flags","hook":"Spot the two things that look like sharing but leave the mental load on one parent.","scene":[{"id":"a","text":"Both owning whole domains end-to-end","trick":false},{"id":"b","text":"One parent assigning tasks to the other","trick":true},{"id":"c","text":"A check-in to rebalance the load","trick":false},{"id":"d","text":"Writing the to-do list for your partner","trick":true},{"id":"e","text":"Each tracking their own domain","trick":false}],"why":"Assigning tasks and writing the list keep one parent doing the tracking — the heaviest, invisible part of the load.","relearn":"Assigning tasks or writing the list keeps the tracking on one parent; owning domains shares the real load.","cat":"tools-and-help"},
  {"id":"ep2-1405","type":"spot","persona":"any","source":"burnout red flags","hook":"Spot the two responses to a burning-out parent that make things worse.","scene":[{"id":"a","text":"Take over some domains for a while","trick":false},{"id":"b","text":"'Just toughen up and push through'","trick":true},{"id":"c","text":"Reach Looking After You together","trick":false},{"id":"d","text":"'A real parent copes alone'","trick":true},{"id":"e","text":"Reach Tele-MANAS 14416 for support","trick":false}],"why":"'Toughen up' and 'cope alone' shame real burnout and risk the parent; taking load and reaching support help.","relearn":"Telling a burnt-out parent to toughen up or cope alone makes it worse; share load and reach support instead.","cat":"tools-and-help"},
  {"id":"ep2-1406","type":"spot","persona":"any","source":"scorecard red flags","hook":"Spot the two ways of doing 'fairness' that turn parenting into a tense scoreboard.","scene":[{"id":"a","text":"Each owning whole domains and flexing","trick":false},{"id":"b","text":"Tallying every nappy each parent did","trick":true},{"id":"c","text":"Checking in on who feels overloaded","trick":false},{"id":"d","text":"Keeping a running chore scoreboard","trick":true},{"id":"e","text":"Covering for each other on a hard day","trick":false}],"why":"Tallying nappies and keeping a chore scoreboard breed resentment; owned domains and flexing keep it fair and warm.","relearn":"Fairness is owned domains and flexibility, not a nappy tally or chore scoreboard that breeds resentment.","cat":"tools-and-help"},
  {"id":"ep2-1407","type":"spot","persona":"any","source":"grandparent-routing red flags","hook":"Spot the two patterns that quietly route all the care back to one parent in a joint family.","scene":[{"id":"a","text":"Family asks both parents about the kids","trick":false},{"id":"b","text":"Every care question goes to mum only","trick":true},{"id":"c","text":"Both parents coordinate with grandparents","trick":false},{"id":"d","text":"'Leave the baby stuff to the women'","trick":true},{"id":"e","text":"Dad's named on the school and clinic lists","trick":false}],"why":"Routing every care question to mum and 'leave it to the women' rebuild the default; involving both keeps care shared.","relearn":"Care routed only to mum, or 'leave it to the women', rebuilds the default; involve both parents.","cat":"tools-and-help"},
  {"id":"ep2-1408","type":"spot","persona":"any","source":"vague-intent red flags","hook":"Spot the two vague intentions that won't actually shift a default split.","scene":[{"id":"a","text":"Each picks domains to own this month","trick":false},{"id":"b","text":"'I'll try to be more helpful around here'","trick":true},{"id":"c","text":"Put all kid dates on a shared calendar","trick":false},{"id":"d","text":"'We'll just be fairer from now on'","trick":true},{"id":"e","text":"Book a monthly check-in in the diary","trick":false}],"why":"'Be more helpful' and 'just be fairer' are vague wishes; owned domains, a shared calendar and a booked check-in are concrete.","relearn":"Vague wishes like 'be more helpful' don't shift a default; owned domains, a shared calendar and a check-in do.","cat":"tools-and-help"},
  {"id":"ep2-1409","type":"spot","persona":"Priya","source":"modelling red flags","hook":"Spot the two habits that teach kids the old divide instead of shared care.","scene":[{"id":"a","text":"Dad cooks and packs bags where kids see","trick":false},{"id":"b","text":"Only mum is ever seen caring for the kids","trick":true},{"id":"c","text":"Both parents do drop-offs and bedtime","trick":false},{"id":"d","text":"Telling a son 'that's not boys' work'","trick":true},{"id":"e","text":"Sons and daughters share chores alike","trick":false}],"why":"Kids copy what they see; only-mum-caring and 'not boys' work' teach the divide, while shared visible care unteaches it.","relearn":"Kids learn from what they see; only-mum care and 'not boys' work' teach the divide — model shared care instead.","cat":"tools-and-help"},
  {"id":"ep2-1410","type":"spot","persona":"any","source":"quit-signal red flags","hook":"Spot the two thoughts that wrongly treat normal difficulty as a reason to give up on fair parenting.","scene":[{"id":"a","text":"'This is hard, so let's use the tools'","trick":false},{"id":"b","text":"'It's hard, so fair just isn't for us'","trick":true},{"id":"c","text":"'Let's check in and rebalance again'","trick":false},{"id":"d","text":"'Too much effort — back to the old way'","trick":true},{"id":"e","text":"'Difficulty is normal, we can work it'","trick":false}],"why":"Treating normal difficulty as proof fair 'isn't for us' is the quit trap; the rest meet the hard part with tools.","relearn":"Keeping a fair split is ongoing effort; difficulty is normal and workable, never a reason to quit.","cat":"tools-and-help"},
];

